                    <h3 className="flex items-center gap-2 text-sm font-semibold text-slate-900">
                        <PencilSquareIcon className="w-5 h-5 text-blue-600" />
                        Düzenle
                    </h3>

                    <div className="pl-1">
                        <label className="block text-xs font-medium text-slate-700 mb-1">Programmverbindung</label>
                        <input 
                            type="text" 
                            className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:ring-blue-500 focus:border-blue-500" 
                            placeholder="-"
                            value={editForm.programmverbindung}
                            onChange={(e) => setEditForm({...editForm, programmverbindung: e.target.value})}
                        />
                    </div>

                    <div className="pl-1">
                        <label className="block text-xs font-medium text-slate-700 mb-1">Abschlusszweck</label>
                        <select 
                            className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:ring-blue-500 focus:border-blue-500 bg-white"
                            value={editForm.abschlusszweck}
                            onChange={(e) => setEditForm({...editForm, abschlusszweck: e.target.value})}
                        >
                            <option>Seçiniz</option>
                            <option>Bilanz</option>
                            <option>GuV</option>
                        </select>
                    </div>

                    <div className="flex gap-2 pt-2">
                         <Button fullWidth variant="primary" onClick={handleUpdate}>Kaydet</Button>
                         <Button variant="secondary" onClick={() => setSelectedId(null)}>İptal</Button>
                    </div>
                </div>

              </div>
            ) : (
               <div className="flex flex-col items-center justify-center h-full text-center text-slate-400 space-y-4">
                  <div className="p-4 bg-slate-50 rounded-full">
                    <ArchiveBoxIcon className="w-12 h-12 text-slate-300" />
                  </div>
                  <p className="text-sm">Listeden detaylarını görüntülemek<br/>istediğiniz hesabı seçin.</p>
               </div>
            )
          )}
        </div>
      </aside>
    </div>
  );
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { supabase } from './supabaseClient';
import { AccountEntry, ViewMode } from './types';
import { 
  TableCellsIcon, 
  DocumentArrowUpIcon, 
  MagnifyingGlassIcon, 
  FunnelIcon,
  ArchiveBoxIcon,
  ChevronRightIcon,
  TagIcon,
  FolderIcon,
  PencilSquareIcon,
  IdentificationIcon,
  InformationCircleIcon,
  ArrowPathIcon,
  BookOpenIcon,
  AcademicCapIcon,
  LightBulbIcon,
  PhotoIcon,
  SparklesIcon,
  XMarkIcon,
  DocumentTextIcon
} from '@heroicons/react/24/outline';

// --- Helper Components ---

const Button: React.FC<{
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger-ghost';
  className?: string;
  fullWidth?: boolean;
  disabled?: boolean;
}> = ({ children, onClick, variant = 'primary', className = '', fullWidth = false, disabled = false }) => {
  const baseStyle = "px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 shadow-sm",
    secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50",
    ghost: "text-slate-600 hover:bg-slate-100 hover:text-slate-900",
    "danger-ghost": "text-red-600 hover:bg-red-50 hover:text-red-700"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`${baseStyle} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
    >
      {children}
    </button>
  );
};

// --- Logic Helpers ---

// Fallback logic for immediate display while AI loads
const getBasicAccountingInsight = (code: string): string => {
  const numericMatch = code.match(/\d+/);
  if (!numericMatch) return "Genel hesap.";
  const firstDigit = numericMatch[0][0];

  if (firstDigit === '0') return "Duran Varlıklar sınıfı.";
  if (firstDigit === '1') return "Dönen Varlıklar ve Finansal Hesaplar.";
  if (firstDigit === '2') return "Özkaynaklar veya Ara Hesaplar.";
  if (firstDigit === '3') return "Yabancı Kaynaklar (Borçlar).";
  if (firstDigit === '4') return "Gelir Hesapları.";
  if (firstDigit === '5' || firstDigit === '6') return "Gider Hesapları.";
  if (firstDigit === '9') return "Nazım Hesaplar.";
  return "Genel muhasebe hesabı.";
};

// --- Main Application ---

export default function App() {
  // State
  const [accounts, setAccounts] = useState<AccountEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<ViewMode>('IMPORT');
  const [rawInput, setRawInput] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState<string>("");

  // AI & Image State
  const [selectedImage, setSelectedImage] = useState<File | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Insight AI State
  const [aiInsight, setAiInsight] = useState<string>("");
  const [isInsightLoading, setIsInsightLoading] = useState<boolean>(false);

  // Edit Form State
  const [editForm, setEditForm] = useState({
    programmverbindung: '',
    abschlusszweck: ''
  });

  // --- Supabase Integration ---

  const fetchAccounts = async () => {
    try {
      const { data, error } = await supabase
        .from('accounts')
        .select('*')
        .order('code', { ascending: true });

      if (error) throw error;

      const mappedData: AccountEntry[] = (data || []).map(item => ({
        id: item.id,
        code: item.code,
        description: item.description,
        category: item.category,
        bilanzPosten: item.bilanz_posten,
        programmverbindung: item.programmverbindung,
        abschlusszweck: item.abschlusszweck
      }));

      setAccounts(mappedData);
    } catch (error) {
      console.error('Error fetching accounts:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAccounts();

    const channel = supabase
      .channel('schema-db-changes')
      .on(
        'postgres_changes',
        {
          event: '*', 
          schema: 'public',
          table: 'accounts',
        },
        () => {
          fetchAccounts();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  // Sync Edit Form & Trigger AI Insight when selection changes
  useEffect(() => {
    let isMounted = true;

    if (selectedId) {
        const account = accounts.find(a => a.id === selectedId);
        if (account) {
            // 1. Set form data
            setEditForm({
                programmverbindung: account.programmverbindung || '',
                abschlusszweck: account.abschlusszweck || 'Seçiniz'
            });

            // 2. Trigger AI Insight
            const generateInsight = async () => {
              setIsInsightLoading(true);
              setAiInsight(getBasicAccountingInsight(account.code)); // Immediate fallback

              try {
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
                const model = "gemini-3-flash-preview"; 

                const prompt = `Sen uzman bir muhasebecisin (Alman Hesap Planı SKR03/04 uzmanı).
                Şu hesabı analiz et:
                Kod: ${account.code}
                İsim: ${account.description}
                Kategori: ${account.category}

                Lütfen bu hesap için Türkçe, profesyonel ama anlaşılır bir "Hesap İçgörüsü" metni yaz.
                Metin şu 3 maddeyi içermelidir (madde işaretleri kullanma, akıcı bir paragraf olsun):
                1. Bu hesabın temel amacı nedir?
                2. Mali tablolarda (Bilanço/Gelir Tablosu) nerede durur ve neyi etkiler?
                3. Pratik bir kullanım örneği ver (Örn: "Şirket yeni bir makine aldığında bu hesaba borç kaydedilir" gibi).

                Metni kısa tut (maksimum 3-4 cümle).`;

                const result = await ai.models.generateContent({
                  model: model,
                  contents: prompt
                });

                if (isMounted && result.text) {
                  setAiInsight(result.text);
                }
              } catch (error) {
                console.error("Insight generation failed", error);
              } finally {
                if (isMounted) setIsInsightLoading(false);
              }
            };

            generateInsight();
        }
    } else {
      setAiInsight("");
    }

    return () => {
      isMounted = false;
    };
  }, [selectedId, accounts]);


  // Derived State
  const selectedAccount = accounts.find(a => a.id === selectedId);
  const filteredAccounts = accounts.filter(acc => 
    acc.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
    acc.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (acc.bilanzPosten && acc.bilanzPosten.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  // Parsing & Inserting Logic
  const handleProcessData = useCallback(async () => {
    if (!rawInput.trim()) return;
    setLoading(true);

    const lines = rawInput.split('\n');
    const newEntries = [];
    const isMarkdownTable = lines.some(line => line.includes('|') && line.includes('---'));

    if (isMarkdownTable) {
        let currentCategory = "";
        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed || trimmed.startsWith('|-') || !trimmed.includes('|')) continue;
            const cols = trimmed.split('|').map(c => c.trim()).filter(c => c !== '');
            if (cols[0]?.toLowerCase().includes('category') || cols[0]?.toLowerCase().includes('bilanz')) continue;

            if (cols.length >= 2) {
                let category = cols[0];
                let code = "";
                let name = "";

                if (!category) {
                    category = currentCategory;
                } else {
                    currentCategory = category;
                }

                if (cols.length >= 3) {
                    code = cols[1];
                    name = cols[2];
                } else {
                    code = cols[1];
                    name = "İsimsiz Hesap"; 
                }

                if (code && code.match(/\d+/)) {
                    newEntries.push({
                        code: code,
                        description: name,
                        category: "Genel",
                        bilanz_posten: category
                    });
                }
            }
        }
    } else {
        // Legacy parsing logic...
        let currentClass = "Genel";
        let currentBilanzPosten = "";
        let buffer: string[] = [];
        let expectingClassName = false;
        let pendingClassDigit = "";
        const ignorePatterns = [/^Bilanz-?$/i, /^Posten\d*\)?$/i, /^Programmverbindung\d*\)?$/i, /^Abschlusszweck\d*\)?$/i, /^\d+\)$/, /^Bilanz-$/];

        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed) continue;
            if (ignorePatterns.some(p => p.test(trimmed))) continue;

            if (/^\d$/.test(trimmed)) {
                pendingClassDigit = trimmed;
                expectingClassName = true;
                buffer = []; 
                continue;
            }

            if (expectingClassName) {
                currentClass = `${pendingClassDigit} ${trimmed}`;
                expectingClassName = false;
                buffer = []; 
                currentBilanzPosten = ""; 
                continue;
            }

            const codeMatch = trimmed.match(/^(\d{4}|KU\s?[\d-]+|R\s?\d{4}[-]?\d{0,2})\s+(.*)/);

            if (codeMatch) {
                if (buffer.length > 0) {
                    currentBilanzPosten = buffer.join(" ");
                    buffer = [];
                }
                newEntries.push({ code: codeMatch[1], description: codeMatch[2], category: currentClass, bilanz_posten: currentBilanzPosten });
            } else {
                if (trimmed.length > 1) buffer.push(trimmed);
            }
        }
    }

    if (newEntries.length > 0) {
        const uniqueCodesInBatch = new Set();
        const deduplicatedEntries = [];
        for (const entry of newEntries) {
            if (!uniqueCodesInBatch.has(entry.code)) {
                uniqueCodesInBatch.add(entry.code);
                deduplicatedEntries.push(entry);
            }
        }

        const codesToCheck = deduplicatedEntries.map(e => e.code);
        try {
            const { data: existingData, error: checkError } = await supabase.from('accounts').select('code').in('code', codesToCheck);
            if (checkError) throw checkError;

            const existingSet = new Set(existingData?.map(d => d.code));
            const finalEntriesToInsert = deduplicatedEntries.filter(e => !existingSet.has(e.code));

            if (finalEntriesToInsert.length > 0) {
                const { error: insertError } = await supabase.from('accounts').insert(finalEntriesToInsert);
                if (insertError) {
                    alert("Kayıt sırasında hata oluştu: " + insertError.message);
                } else {
                    alert(`${finalEntriesToInsert.length} yeni kayıt başarıyla eklendi.`);
                    setRawInput(""); 
                    setActiveTab('DATABASE');
                }
            } else {
                alert("Eklenecek yeni kayıt bulunamadı.");
            }
        } catch (error: any) {
            alert("Veritabanı hatası: " + error.message);
        }
    }
    setLoading(false);
  }, [rawInput]);

  const handleUpdate = async () => {
    if (!selectedId) return;
    const { error } = await supabase.from('accounts').update({
            programmverbindung: editForm.programmverbindung,
            abschlusszweck: editForm.abschlusszweck === 'Seçiniz' ? null : editForm.abschlusszweck
        }).eq('id', selectedId);
    if (error) alert("Güncelleme hatası: " + error.message);
  };

  const handleImageFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
        setSelectedImage(e.target.files[0]);
    }
  };

  const readFileAsBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
            const result = reader.result as string;
            const base64 = result.split(',')[1];
            resolve(base64);
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  };

  const handleAnalyzeImage = async () => {
    if (!selectedImage) return;
    setIsAnalyzing(true);
    try {
        const base64Data = await readFileAsBase64(selectedImage);
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const model = "gemini-3-flash-preview"; 
        const prompt = `Act as an expert accountant and OCR specialist. Analyze the attached file (Image or PDF) which shows a German Chart of Accounts (Kontenrahmen).
Convert this document content into a structured table (CSV format). Output format: Markdown Table.`;

        const response = await ai.models.generateContent({
            model: model,
            contents: {
                parts: [
                    { inlineData: { mimeType: selectedImage.type, data: base64Data } },
                    { text: prompt }
                ]
            }
        });

        const text = response.text;
        if (text) {
            setRawInput(prev => (prev.trim() ? prev + "\n\n" : "") + text);
            setSelectedImage(null);
        }
    } catch (error: any) {
        alert("Dosya analizi sırasında hata: " + error.message);
    } finally {
        setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden">

      {/* 1. LEFT PANEL */}
      <nav className="w-64 bg-slate-900 text-slate-300 flex flex-col border-r border-slate-800 flex-shrink-0">
        <div className="p-4 h-16 flex items-center border-b border-slate-800">
          <div className="flex items-center gap-2 text-white font-semibold text-lg">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
              <TableCellsIcon className="w-5 h-5" />
            </div>
            AccuParse
          </div>
        </div>
        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-3 space-y-1">
            <p className="px-3 text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Veri Yönetimi</p>
            <button onClick={() => setActiveTab('IMPORT')} className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'IMPORT' ? 'bg-blue-600 text-white' : 'hover:bg-slate-800'}`}>
              <DocumentArrowUpIcon className="w-5 h-5" />
              <span>Veri Ekle / Import</span>
            </button>
            <button onClick={() => setActiveTab('DATABASE')} className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'DATABASE' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800'}`}>
              <ArchiveBoxIcon className="w-5 h-5" />
              <span>Bilgi Bankası</span>
            </button>
          </div>
        </div>
        <div className="p-4 border-t border-slate-800 text-xs text-slate-500 flex justify-between items-center">
          <span>v1.6.0 (Smart Insight)</span>
          <div className={`w-2 h-2 rounded-full ${loading ? 'bg-yellow-500 animate-pulse' : 'bg-green-500'}`} title="Bağlantı Durumu"></div>
        </div>
      </nav>

      {/* 2. CENTER PANEL */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative border-r border-slate-200">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 flex-shrink-0">
          <h1 className="text-xl font-semibold text-slate-800">
            {activeTab === 'IMPORT' ? 'Veri İçe Aktar' : 'Bilgi Bankası'}
          </h1>
          <div className="flex items-center gap-2">
            {activeTab === 'DATABASE' && (
              <span className="text-sm text-slate-500 bg-slate-100 px-3 py-1 rounded-full flex items-center gap-2">
                {loading && <ArrowPathIcon className="w-3 h-3 animate-spin" />}
                {accounts.length} Kayıt
              </span>
            )}
          </div>
        </header>

        {activeTab === 'DATABASE' && (
          <>
            <div className="p-4 bg-white border-b border-slate-200 flex items-center gap-4 flex-shrink-0">
              <div className="relative flex-1 max-w-md">
                <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input type="text" placeholder="Hesap kodu, grup veya isim ara..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm" />
              </div>
              <Button variant="secondary"><FunnelIcon className="w-4 h-4" /> Filtrele</Button>
            </div>
            <div className="flex-1 overflow-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
                  <tr>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-24">Kod</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200">Açıklama</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 hidden md:table-cell">Grup / Bilanz Posten</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 hidden lg:table-cell">Hesap Sınıfı</th>
                    <th className="py-3 px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-10"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 bg-white">
                  {filteredAccounts.length === 0 ? (
                    <tr><td colSpan={5} className="py-12 text-center text-slate-400">{loading ? "Veriler yükleniyor..." : "Arama kriterine uygun kayıt bulunamadı."}</td></tr>
                  ) : (
                    filteredAccounts.map((account) => (
                      <tr key={account.id} onClick={() => setSelectedId(account.id)} className={`cursor-pointer transition-colors group ${selectedId === account.id ? 'bg-blue-50' : 'hover:bg-slate-50'}`}>
                        <td className="py-3 px-4 text-sm font-medium text-slate-900 whitespace-nowrap">{account.code}</td>
                        <td className="py-3 px-4 text-sm text-slate-600 truncate max-w-xs">{account.description}</td>
                        <td className="py-3 px-4 text-xs text-slate-600 hidden md:table-cell truncate max-w-[200px]" title={account.bilanzPosten}>{account.bilanzPosten || '-'}</td>
                        <td className="py-3 px-4 text-xs text-slate-500 hidden lg:table-cell"><span className="bg-slate-100 px-2 py-1 rounded text-slate-600 border border-slate-200 whitespace-nowrap">{account.category}</span></td>
                        <td className="py-3 px-4 text-slate-400 text-right"><ChevronRightIcon className={`w-4 h-4 inline-block ${selectedId === account.id ? 'text-blue-500' : 'opacity-0 group-hover:opacity-100'}`} /></td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </>
        )}

        {activeTab === 'IMPORT' && (
          <div className="flex-1 overflow-y-auto p-6 md:p-12">
            <div className="max-w-4xl mx-auto space-y-8">
               <div className="text-center space-y-2 mb-8">
                  <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-2xl flex items-center justify-center mx-auto mb-4"><DocumentArrowUpIcon className="w-8 h-8" /></div>
                  <h2 className="text-2xl font-semibold text-slate-800">Toplu Veri Ekleme Sihirbazı</h2>
                  <p className="text-slate-500">PDF, Görsel veya Metin verilerinizi yükleyin. Sistem otomatik olarak analiz edip veritabanına kaydedecektir.</p>
               </div>
               <div className="bg-slate-50 border-2 border-dashed border-slate-300 rounded-xl p-6 transition-colors hover:border-blue-400">
                  <div className="flex flex-col items-center justify-center space-y-3">
                     {!selectedImage ? (
                       <>
                         <div className="p-3 bg-white rounded-full shadow-sm"><PhotoIcon className="w-8 h-8 text-slate-400" /></div>
                         <div className="text-center"><p className="text-sm font-medium text-slate-700">Bir görsel veya PDF yükleyin</p><p className="text-xs text-slate-500 mt-1">PNG, JPG, PDF (Max. 5MB)</p></div>
                         <input type="file" ref={fileInputRef} accept="image/*,application/pdf" onChange={handleImageFileChange} className="hidden" />
                         <Button variant="secondary" onClick={() => fileInputRef.current?.click()}>Dosya Seç</Button>
                       </>
                     ) : (
                       <div className="w-full flex items-center justify-between bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
                         <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-slate-100 rounded flex items-center justify-center overflow-hidden">
                               {selectedImage.type.startsWith('image/') ? <img src={URL.createObjectURL(selectedImage)} alt="Preview" className="w-full h-full object-cover opacity-80" /> : <DocumentTextIcon className="w-6 h-6 text-slate-500" />}
                            </div>
                            <div><p className="text-sm font-medium text-slate-800">{selectedImage.name}</p><p className="text-xs text-slate-500">{(selectedImage.size / 1024).toFixed(1)} KB</p></div>
                         </div>
                         <div className="flex items-center gap-2">
                             <Button variant="primary" onClick={handleAnalyzeImage} disabled={isAnalyzing} className="bg-indigo-600 hover:bg-indigo-700">
                                {isAnalyzing ? <><SparklesIcon className="w-4 h-4 animate-spin" /> Analiz Ediliyor...</> : <><SparklesIcon className="w-4 h-4" /> AI ile Analiz Et</>}
                             </Button>
                             <button onClick={() => setSelectedImage(null)} className="p-2 text-slate-400 hover:text-red-500 rounded-full hover:bg-red-50"><XMarkIcon className="w-5 h-5" /></button>
                         </div>
                       </div>
                     )}
                  </div>
               </div>
               <div className="space-y-4">
                  <div className="flex items-center justify-between"><label className="block text-sm font-medium text-slate-700">Veri Yapıştırma Alanı</label><span className="text-xs text-slate-400">Ham Metin veya Markdown Tablo</span></div>
                  <div className="relative">
                    <textarea value={rawInput} onChange={(e) => setRawInput(e.target.value)} className="w-full h-80 p-6 text-sm font-mono border border-slate-300 rounded-xl focus:ring-4 focus:ring-blue-100 focus:border-blue-500 shadow-sm resize-none bg-white transition-all" placeholder={`Markdown Tablosu veya Ham Metin...`}></textarea>
                    <div className="absolute bottom-4 right-4 text-xs text-slate-400">{rawInput.split('\n').length} Satır</div>
                  </div>
               </div>
               <div className="flex justify-end gap-4">
                  <Button variant="ghost" onClick={() => setRawInput("")}>Temizle</Button>
                  <Button onClick={handleProcessData} disabled={!rawInput.trim() || loading} className="px-8 py-3 text-base">{loading ? 'İşleniyor...' : 'Verileri Analiz Et ve Yükle'}</Button>
               </div>
            </div>
          </div>
        )}
      </main>

      {/* 3. RIGHT PANEL */}
      <aside className="w-96 bg-white flex flex-col border-l border-slate-200 shadow-xl flex-shrink-0 z-20">
        <div className="h-16 border-b border-slate-200 flex items-center justify-between px-6 bg-slate-50">
          <h2 className="font-semibold text-slate-800">{activeTab === 'DATABASE' ? 'Hesap Detayı' : 'Muhasebe Rehberi'}</h2>
        </div>
        <div className="flex-1 overflow-y-auto p-6">
          {activeTab === 'IMPORT' && (
            <div className="space-y-8">
               <div className="bg-indigo-50 border border-indigo-100 rounded-lg p-4">
                  <h3 className="flex items-center gap-2 font-semibold text-indigo-900 mb-2"><BookOpenIcon className="w-5 h-5" /> Sistem Tanımı</h3>
                  <p className="text-sm text-indigo-800 leading-relaxed">Bu modül, standart hesap planı (SKR03/04 uyumlu) verilerini işler.</p>
               </div>
               <div className="bg-gradient-to-r from-purple-50 to-blue-50 border border-purple-100 rounded-lg p-4">
                  <h3 className="flex items-center gap-2 font-semibold text-purple-900 mb-2"><SparklesIcon className="w-5 h-5 text-purple-600" /> Yapay Zeka Desteği</h3>
                  <p className="text-xs text-purple-800 leading-relaxed">Gemini AI, dokümanlarınızı otomatik olarak analiz eder.</p>
               </div>
               {/* Static Guides kept for reference... */}
            </div>
          )}

          {activeTab === 'DATABASE' && (
            selectedAccount ? (
              <div className="space-y-6">
                <div className="flex items-start justify-between">
                  <div className="bg-blue-100 text-blue-800 px-3 py-1 rounded text-lg font-bold font-mono border border-blue-200">{selectedAccount.code}</div>
                  <span className="text-xs font-medium text-green-600 bg-green-50 border border-green-200 rounded px-2 py-1 uppercase flex items-center gap-1"><div className="w-1.5 h-1.5 rounded-full bg-green-500"></div> Aktif</span>
                </div>

                <div className="bg-amber-50 border border-amber-200 rounded-lg p-4 shadow-sm relative overflow-hidden">
                   <h3 className="flex items-center gap-2 text-sm font-semibold text-amber-900 mb-2">
                      <LightBulbIcon className="w-5 h-5 text-amber-600" />
                      Muhasebe İşlevi & Analiz
                   </h3>
                   <div className="text-sm text-amber-800 leading-relaxed whitespace-pre-wrap">
                     {isInsightLoading ? (
                       <div className="space-y-2 animate-pulse">
                          <div className="h-4 bg-amber-200 rounded w-3/4"></div>
                          <div className="h-4 bg-amber-200 rounded w-full"></div>
                          <div className="h-4 bg-amber-200 rounded w-5/6"></div>
                       </div>
                     ) : (
                       aiInsight
                     )}
                   </div>
                   {isInsightLoading && (
                     <div className="absolute top-2 right-2">
                       <SparklesIcon className="w-4 h-4 text-amber-600 animate-spin" />
                     </div>
                   )}
                </div>

                <div>
                  <label className="flex items-center gap-2 text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1"><TagIcon className="w-4 h-4 text-blue-500" /> Hesap Adı</label>
                  <p className="text-slate-800 text-lg leading-snug font-medium pl-6">{selectedAccount.description}</p>
                </div>

                <div className="grid grid-cols-1 gap-4 bg-slate-50 p-4 rounded-lg border border-slate-100">
                  <div>
                    <label className="flex items-center gap-2 text-xs text-slate-500 mb-1"><FolderIcon className="w-4 h-4 text-slate-400" /> Kategori / Üst Grup</label>
                    <p className="text-sm font-medium text-slate-700 pl-6">{selectedAccount.category}</p>
                  </div>
                  {selectedAccount.bilanzPosten && (
                    <div>
                        <label className="flex items-center gap-2 text-xs text-slate-500 mb-1"><TableCellsIcon className="w-4 h-4 text-slate-400" /> Bilanz Posten</label>
                        <p className="text-sm font-medium text-slate-700 pl-6">{selectedAccount.bilanzPosten}</p>
                    </div>
                  )}
                </div>

                <div className="space-y-4 pt-4 border-t border-slate-200">
                    <h3 className="flex items-center gap-2 text-sm font-semibold text-slate-900"><PencilSquareIcon className="w-5 h-5 text-blue-600" /> Düzenle</h3>
                    <div className="pl-1">
                        <label className="block text-xs font-medium text-slate-700 mb-1">Programmverbindung</label>
                        <input type="text" className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:ring-blue-500 focus:border-blue-500" placeholder="-" value={editForm.programmverbindung} onChange={(e) => setEditForm({...editForm, programmverbindung: e.target.value})} />
                    </div>
                    <div className="pl-1">
                        <label className="block text-xs font-medium text-slate-700 mb-1">Abschlusszweck</label>
                        <select className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:ring-blue-500 focus:border-blue-500 bg-white" value={editForm.abschlusszweck} onChange={(e) => setEditForm({...editForm, abschlusszweck: e.target.value})}>
                            <option>Seçiniz</option><option>Bilanz</option><option>GuV</option>
                        </select>
                    </div>
                    <div className="flex gap-2 pt-2">
                         <Button fullWidth variant="primary" onClick={handleUpdate}>Kaydet</Button>
                         <Button variant="secondary" onClick={() => setSelectedId(null)}>İptal</Button>
                    </div>
                </div>
              </div>
            ) : (
               <div className="flex flex-col items-center justify-center h-full text-center text-slate-400 space-y-4">
                  <div className="p-4 bg-slate-50 rounded-full"><ArchiveBoxIcon className="w-12 h-12 text-slate-300" /></div>
                  <p className="text-sm">Listeden detaylarını görüntülemek<br/>istediğiniz hesabı seçin.</p>
               </div>
            )
          )}
        </div>
      </aside>
    </div>
  );
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { supabase } from './supabaseClient';
import { AccountEntry, ViewMode } from './types';
import { 
  TableCellsIcon, 
  DocumentArrowUpIcon, 
  MagnifyingGlassIcon, 
  FunnelIcon,
  ArchiveBoxIcon,
  ChevronRightIcon,
  TagIcon,
  FolderIcon,
  PencilSquareIcon,
  IdentificationIcon,
  InformationCircleIcon,
  ArrowPathIcon,
  BookOpenIcon,
  AcademicCapIcon,
  LightBulbIcon,
  PhotoIcon,
  SparklesIcon,
  XMarkIcon,
  DocumentTextIcon
} from '@heroicons/react/24/outline';

// --- Helper Components ---

const Button: React.FC<{
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger-ghost';
  className?: string;
  fullWidth?: boolean;
  disabled?: boolean;
}> = ({ children, onClick, variant = 'primary', className = '', fullWidth = false, disabled = false }) => {
  const baseStyle = "px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 shadow-sm",
    secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50",
    ghost: "text-slate-600 hover:bg-slate-100 hover:text-slate-900",
    "danger-ghost": "text-red-600 hover:bg-red-50 hover:text-red-700"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`${baseStyle} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
    >
      {children}
    </button>
  );
};

// --- Logic Helpers ---

// Fallback logic for immediate display while AI loads
const getBasicAccountingInsight = (code: string): string => {
  const numericMatch = code.match(/\d+/);
  if (!numericMatch) return "Genel hesap.";
  const firstDigit = numericMatch[0][0];

  if (firstDigit === '0') return "Duran Varlıklar sınıfı.";
  if (firstDigit === '1') return "Dönen Varlıklar ve Finansal Hesaplar.";
  if (firstDigit === '2') return "Özkaynaklar veya Ara Hesaplar.";
  if (firstDigit === '3') return "Yabancı Kaynaklar (Borçlar).";
  if (firstDigit === '4') return "Gelir Hesapları.";
  if (firstDigit === '5' || firstDigit === '6') return "Gider Hesapları.";
  if (firstDigit === '9') return "Nazım Hesaplar.";
  return "Genel muhasebe hesabı.";
};

// --- Main Application ---

export default function App() {
  // State
  const [accounts, setAccounts] = useState<AccountEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<ViewMode>('IMPORT');
  const [rawInput, setRawInput] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState<string>("");

  // AI & Image State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analyzeStatus, setAnalyzeStatus] = useState<string>("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Insight AI State
  const [aiInsight, setAiInsight] = useState<string>("");
  const [isInsightLoading, setIsInsightLoading] = useState<boolean>(false);

  // Edit Form State
  const [editForm, setEditForm] = useState({
    programmverbindung: '',
    abschlusszweck: ''
  });

  // --- Supabase Integration ---

  const fetchAccounts = async () => {
    try {
      const { data, error } = await supabase
        .from('accounts')
        .select('*')
        .order('code', { ascending: true });

      if (error) throw error;

      const mappedData: AccountEntry[] = (data || []).map(item => ({
        id: item.id,
        code: item.code,
        description: item.description,
        category: item.category,
        bilanzPosten: item.bilanz_posten,
        programmverbindung: item.programmverbindung,
        abschlusszweck: item.abschlusszweck
      }));

      setAccounts(mappedData);
    } catch (error) {
      console.error('Error fetching accounts:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAccounts();

    const channel = supabase
      .channel('schema-db-changes')
      .on(
        'postgres_changes',
        {
          event: '*', 
          schema: 'public',
          table: 'accounts',
        },
        () => {
          fetchAccounts();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  // Sync Edit Form & Trigger AI Insight when selection changes
  useEffect(() => {
    let isMounted = true;

    if (selectedId) {
        const account = accounts.find(a => a.id === selectedId);
        if (account) {
            // 1. Set form data
            setEditForm({
                programmverbindung: account.programmverbindung || '',
                abschlusszweck: account.abschlusszweck || 'Seçiniz'
            });

            // 2. Trigger AI Insight
            const generateInsight = async () => {
              setIsInsightLoading(true);
              setAiInsight(getBasicAccountingInsight(account.code)); // Immediate fallback

              try {
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
                const model = "gemini-3-flash-preview"; 

                const prompt = `Sen uzman bir muhasebecisin (Alman Hesap Planı SKR03/04 uzmanı).
                Şu hesabı analiz et:
                Kod: ${account.code}
                İsim: ${account.description}
                Kategori: ${account.category}

                Lütfen bu hesap için Türkçe, profesyonel ama anlaşılır bir "Hesap İçgörüsü" metni yaz.
                Metin şu 3 maddeyi içermelidir (madde işaretleri kullanma, akıcı bir paragraf olsun):
                1. Bu hesabın temel amacı nedir?
                2. Mali tablolarda (Bilanço/Gelir Tablosu) nerede durur ve neyi etkiler?
                3. Pratik bir kullanım örneği ver (Örn: "Şirket yeni bir makine aldığında bu hesaba borç kaydedilir" gibi).

                Metni kısa tut (maksimum 3-4 cümle).`;

                const result = await ai.models.generateContent({
                  model: model,
                  contents: prompt
                });

                if (isMounted && result.text) {
                  setAiInsight(result.text);
                }
              } catch (error) {
                console.error("Insight generation failed", error);
              } finally {
                if (isMounted) setIsInsightLoading(false);
              }
            };

            generateInsight();
        }
    } else {
      setAiInsight("");
    }

    return () => {
      isMounted = false;
    };
  }, [selectedId, accounts]);


  // Derived State
  const selectedAccount = accounts.find(a => a.id === selectedId);
  const filteredAccounts = accounts.filter(acc => 
    acc.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
    acc.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (acc.bilanzPosten && acc.bilanzPosten.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  // Parsing & Inserting Logic
  const processAndInsertData = async (textInput: string) => {
    const lines = textInput.split('\n');
    const newEntries = [];
    const isMarkdownTable = lines.some(line => line.includes('|') && line.includes('---'));

    if (isMarkdownTable) {
        let currentCategory = "";
        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed || trimmed.startsWith('|-') || !trimmed.includes('|')) continue;
            const cols = trimmed.split('|').map(c => c.trim()).filter(c => c !== '');
            if (cols[0]?.toLowerCase().includes('category') || cols[0]?.toLowerCase().includes('bilanz')) continue;

            if (cols.length >= 2) {
                let category = cols[0];
                let code = "";
                let name = "";

                if (!category) {
                    category = currentCategory;
                } else {
                    currentCategory = category;
                }

                if (cols.length >= 3) {
                    code = cols[1];
                    name = cols[2];
                } else {
                    code = cols[1];
                    name = "İsimsiz Hesap"; 
                }

                if (code && code.match(/\d+/)) {
                    newEntries.push({
                        code: code,
                        description: name,
                        category: "Genel",
                        bilanz_posten: category
                    });
                }
            }
        }
    } else {
        // Legacy parsing logic...
        let currentClass = "Genel";
        let currentBilanzPosten = "";
        let buffer: string[] = [];
        let expectingClassName = false;
        let pendingClassDigit = "";
        const ignorePatterns = [/^Bilanz-?$/i, /^Posten\d*\)?$/i, /^Programmverbindung\d*\)?$/i, /^Abschlusszweck\d*\)?$/i, /^\d+\)$/, /^Bilanz-$/];

        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed) continue;
            if (ignorePatterns.some(p => p.test(trimmed))) continue;

            if (/^\d$/.test(trimmed)) {
                pendingClassDigit = trimmed;
                expectingClassName = true;
                buffer = []; 
                continue;
            }

            if (expectingClassName) {
                currentClass = `${pendingClassDigit} ${trimmed}`;
                expectingClassName = false;
                buffer = []; 
                currentBilanzPosten = ""; 
                continue;
            }

            const codeMatch = trimmed.match(/^(\d{4}|KU\s?[\d-]+|R\s?\d{4}[-]?\d{0,2})\s+(.*)/);

            if (codeMatch) {
                if (buffer.length > 0) {
                    currentBilanzPosten = buffer.join(" ");
                    buffer = [];
                }
                newEntries.push({ code: codeMatch[1], description: codeMatch[2], category: currentClass, bilanz_posten: currentBilanzPosten });
            } else {
                if (trimmed.length > 1) buffer.push(trimmed);
            }
        }
    }

    if (newEntries.length > 0) {
        const uniqueCodesInBatch = new Set();
        const deduplicatedEntries = [];
        for (const entry of newEntries) {
            if (!uniqueCodesInBatch.has(entry.code)) {
                uniqueCodesInBatch.add(entry.code);
                deduplicatedEntries.push(entry);
            }
        }

        const codesToCheck = deduplicatedEntries.map(e => e.code);

        const { data: existingData, error: checkError } = await supabase.from('accounts').select('code').in('code', codesToCheck);
        if (checkError) throw checkError;

        const existingSet = new Set(existingData?.map(d => d.code));
        const finalEntriesToInsert = deduplicatedEntries.filter(e => !existingSet.has(e.code));

        if (finalEntriesToInsert.length > 0) {
            const { error: insertError } = await supabase.from('accounts').insert(finalEntriesToInsert);
            if (insertError) {
                throw new Error("Kayıt hatası: " + insertError.message);
            }
            return { success: true, count: finalEntriesToInsert.length, skipped: deduplicatedEntries.length - finalEntriesToInsert.length };
        } else {
            return { success: true, count: 0, skipped: deduplicatedEntries.length };
        }
    }
    return { success: false, count: 0, skipped: 0 };
  };

  const handleProcessManualInput = useCallback(async () => {
    if (!rawInput.trim()) return;
    setLoading(true);
    try {
        const result = await processAndInsertData(rawInput);
        if (result.success) {
             if (result.count > 0) {
                alert(`${result.count} yeni kayıt eklendi.\n${result.skipped} mükerrer kayıt atlandı.`);
                setRawInput("");
                setActiveTab('DATABASE');
             } else {
                alert("Yeni kayıt bulunamadı (Tümü zaten mevcut).");
             }
        } else {
             alert("İşlenecek geçerli veri bulunamadı.");
        }
    } catch (e: any) {
        alert("Hata: " + e.message);
    } finally {
        setLoading(false);
    }
  }, [rawInput]);

  const handleUpdate = async () => {
    if (!selectedId) return;
    const { error } = await supabase.from('accounts').update({
            programmverbindung: editForm.programmverbindung,
            abschlusszweck: editForm.abschlusszweck === 'Seçiniz' ? null : editForm.abschlusszweck
        }).eq('id', selectedId);
    if (error) alert("Güncelleme hatası: " + error.message);
  };

  const readFileAsBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
            const result = reader.result as string;
            const base64 = result.split(',')[1];
            resolve(base64);
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  };

  const handleAutomaticFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;

    setIsAnalyzing(true);
    setAnalyzeStatus("Dosya okunuyor...");

    try {
        const base64Data = await readFileAsBase64(file);

        setAnalyzeStatus("AI Analizi yapılıyor... (Bu işlem birkaç saniye sürebilir)");
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const model = "gemini-3-flash-preview"; 

        // Optimize prompt for direct execution
        const prompt = `Act as an expert accountant and OCR specialist. Analyze the attached file (Image or PDF) which shows a German Chart of Accounts (Kontenrahmen).
Convert this document content into a structured Markdown Table.
Columns MUST be: | Category | Code | Name |
If Category is missing, use the previous one. Ensure Codes are 4 digits.
Output ONLY the markdown table.`;

        const response = await ai.models.generateContent({
            model: model,
            contents: {
                parts: [
                    { inlineData: { mimeType: file.type, data: base64Data } },
                    { text: prompt }
                ]
            }
        });

        const text = response.text;

        if (text) {
            setAnalyzeStatus("Veriler ayrıştırılıyor ve kaydediliyor...");
            const result = await processAndInsertData(text);

            setIsAnalyzing(false);
            setAnalyzeStatus("");

            if (result.success) {
                if (result.count > 0) {
                   alert(`Başarılı! ${result.count} yeni kayıt eklendi. ${result.skipped > 0 ? `(${result.skipped} mükerrer atlandı)` : ''}`);
                   setActiveTab('DATABASE');
                } else {
                   alert("Dosya analiz edildi ancak eklenecek YENİ kayıt bulunamadı (Hepsi veritabanında mevcut).");
                }
            } else {
                alert("Dosyadan anlamlı veri çıkarılamadı. Lütfen dosya kalitesini kontrol edin.");
            }
        } else {
            throw new Error("AI boş yanıt döndürdü.");
        }

    } catch (error: any) {
        console.error("Auto upload failed", error);
        alert("Otomatik yükleme sırasında hata: " + error.message);
        setIsAnalyzing(false);
        setAnalyzeStatus("");
    } finally {
        // Reset file input so same file can be selected again if needed
        if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  return (
    <div className="flex h-screen w-full bg-white overflow-hidden">

      {/* 1. LEFT PANEL */}
      <nav className="w-64 bg-slate-900 text-slate-300 flex flex-col border-r border-slate-800 flex-shrink-0">
        <div className="p-4 h-16 flex items-center border-b border-slate-800">
          <div className="flex items-center gap-2 text-white font-semibold text-lg">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
              <TableCellsIcon className="w-5 h-5" />
            </div>
            AccuParse
          </div>
        </div>
        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-3 space-y-1">
            <p className="px-3 text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Veri Yönetimi</p>
            <button onClick={() => setActiveTab('IMPORT')} className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'IMPORT' ? 'bg-blue-600 text-white' : 'hover:bg-slate-800'}`}>
              <DocumentArrowUpIcon className="w-5 h-5" />
              <span>Veri Ekle / Import</span>
            </button>
            <button onClick={() => setActiveTab('DATABASE')} className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'DATABASE' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800'}`}>
              <ArchiveBoxIcon className="w-5 h-5" />
              <span>Bilgi Bankası</span>
            </button>
          </div>
        </div>
        <div className="p-4 border-t border-slate-800 text-xs text-slate-500 flex justify-between items-center">
          <span>v1.7.0 (Auto-Upload)</span>
          <div className={`w-2 h-2 rounded-full ${loading ? 'bg-yellow-500 animate-pulse' : 'bg-green-500'}`} title="Bağlantı Durumu"></div>
        </div>
      </nav>

      {/* 2. CENTER PANEL */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative border-r border-slate-200">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 flex-shrink-0">
          <h1 className="text-xl font-semibold text-slate-800">
