                        <p className="text-xs text-slate-500 mt-1">{analyzeStatus}</p>
                    </div>
                  )}

                  <div className="flex flex-col items-center justify-center space-y-4">
                     <div className="p-3 bg-white rounded-full shadow-sm"><PhotoIcon className="w-8 h-8 text-slate-400" /></div>
                     <div className="text-center">
                        <p className="text-sm font-medium text-slate-700">Görsel veya PDF</p>
                     </div>
                     <input type="file" ref={fileInputRef} accept="image/*,application/pdf" onChange={handleAutomaticFileUpload} className="hidden" />
                     <Button variant="primary" fullWidth onClick={() => fileInputRef.current?.click()} disabled={isAnalyzing}>
                        {isAnalyzing ? 'Yükleniyor...' : 'Dosya Seç ve Yükle'}
                     </Button>
                  </div>
               </div>

               <div className="relative py-2">
                  <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div>
                  <div className="relative flex justify-center text-xs"><span className="px-2 bg-slate-50 text-slate-500">VEYA MANUEL</span></div>
               </div>

               <div className="space-y-3">
                  <textarea value={rawInput} onChange={(e) => setRawInput(e.target.value)} className="w-full h-40 p-4 text-xs font-mono border border-slate-300 rounded-xl focus:ring-2 focus:ring-blue-500 shadow-sm resize-none bg-white" placeholder={`Veri yapıştır...`}></textarea>
               </div>
               <div className="flex justify-end gap-3">
                  <Button variant="ghost" onClick={() => setRawInput("")}>Temizle</Button>
                  <Button onClick={handleProcessManualInput} disabled={!rawInput.trim() || loading}>{loading ? '...' : 'İşle'}</Button>
               </div>
            </div>
          </div>
        )}
      </main>

      {/* 3. RIGHT PANEL (Details) - Desktop: Sidebar, Mobile: Full Screen Modal */}
      <aside className={`
        fixed inset-0 z-50 bg-white flex flex-col transition-transform duration-300 ease-in-out
        md:static md:w-96 md:border-l md:border-slate-200 md:shadow-xl md:transform-none md:z-auto
        ${selectedId ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}
        ${!selectedId && 'md:block hidden'} 
      `}>
        <div className="h-16 border-b border-slate-200 flex items-center justify-between px-6 bg-slate-50 flex-shrink-0">
          <div className="flex items-center gap-2">
            {/* Mobile Back Button */}
            <button onClick={() => setSelectedId(null)} className="md:hidden p-1 -ml-2 text-slate-500 hover:text-slate-800">
               <ArrowLeftIcon className="w-6 h-6" />
            </button>
            <h2 className="font-semibold text-slate-800">{activeTab === 'DATABASE' ? 'Hesap Detayı' : 'Rehber'}</h2>
          </div>
          {/* Mobile Close Button */}
          <button onClick={() => setSelectedId(null)} className="md:hidden text-slate-400 hover:text-red-500">
             <span className="text-sm font-medium">Kapat</span>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 pb-24 md:pb-6">
          {activeTab === 'IMPORT' && (
            <div className="space-y-6">
               <div className="bg-gradient-to-r from-blue-50 to-indigo-50 border border-blue-100 rounded-lg p-4">
                  <h3 className="flex items-center gap-2 font-semibold text-blue-900 mb-2"><SparklesIcon className="w-5 h-5" /> Otomatik Akış</h3>
                  <p className="text-xs text-blue-800">Dosyaları seçtiğiniz anda AI analiz eder ve kaydeder.</p>
               </div>
            </div>
          )}

          {activeTab === 'DATABASE' && (
            selectedAccount ? (
              <div className="space-y-6">
                <div className="flex items-start justify-between">
                  <div className="bg-blue-100 text-blue-800 px-4 py-2 rounded-lg text-xl font-bold font-mono border border-blue-200">{selectedAccount.code}</div>
                  <span className="text-xs font-medium text-green-600 bg-green-50 border border-green-200 rounded px-2 py-1 uppercase flex items-center gap-1"><div className="w-1.5 h-1.5 rounded-full bg-green-500"></div> Aktif</span>
                </div>

                <div className="bg-amber-50 border border-amber-200 rounded-lg p-4 shadow-sm relative overflow-hidden">
                   <h3 className="flex items-center gap-2 text-sm font-semibold text-amber-900 mb-2">
                      <LightBulbIcon className="w-5 h-5 text-amber-600" />
                      Analiz
                   </h3>
                   <div className="text-sm text-amber-800 leading-relaxed whitespace-pre-wrap">
                     {isInsightLoading ? (
                       <div className="space-y-2 animate-pulse">
                          <div className="h-3 bg-amber-200 rounded w-3/4"></div>
                          <div className="h-3 bg-amber-200 rounded w-full"></div>
                       </div>
                     ) : aiInsight}
                   </div>
                   {isInsightLoading && <div className="absolute top-2 right-2"><SparklesIcon className="w-4 h-4 text-amber-600 animate-spin" /></div>}
                </div>

                <div>
                  <label className="flex items-center gap-2 text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1"><TagIcon className="w-4 h-4 text-blue-500" /> Hesap Adı</label>
                  <p className="text-slate-800 text-lg leading-snug font-medium pl-6">{selectedAccount.description}</p>
                </div>

                <div className="grid grid-cols-1 gap-4 bg-slate-50 p-4 rounded-lg border border-slate-100">
                  <div>
                    <label className="flex items-center gap-2 text-xs text-slate-500 mb-1"><FolderIcon className="w-4 h-4 text-slate-400" /> Kategori</label>
                    <p className="text-sm font-medium text-slate-700 pl-6">{selectedAccount.category}</p>
                  </div>
                  {selectedAccount.bilanzPosten && (
                    <div>
                        <label className="flex items-center gap-2 text-xs text-slate-500 mb-1"><TableCellsIcon className="w-4 h-4 text-slate-400" /> Bilanz Posten</label>
                        <p className="text-sm font-medium text-slate-700 pl-6">{selectedAccount.bilanzPosten}</p>
                    </div>
                  )}
                </div>

                <div className="space-y-4 pt-4 border-t border-slate-200">
                    <h3 className="flex items-center gap-2 text-sm font-semibold text-slate-900"><PencilSquareIcon className="w-5 h-5 text-blue-600" /> Düzenle</h3>
                    <div className="pl-1">
                        <label className="block text-xs font-medium text-slate-700 mb-1">Programmverbindung</label>
                        <input type="text" className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:ring-blue-500 focus:border-blue-500" placeholder="-" value={editForm.programmverbindung} onChange={(e) => setEditForm({...editForm, programmverbindung: e.target.value})} />
                    </div>
                    <div className="pl-1">
                        <label className="block text-xs font-medium text-slate-700 mb-1">Abschlusszweck</label>
                        <select className="w-full border border-slate-300 rounded px-3 py-2 text-sm focus:ring-blue-500 focus:border-blue-500 bg-white" value={editForm.abschlusszweck} onChange={(e) => setEditForm({...editForm, abschlusszweck: e.target.value})}>
                            <option>Seçiniz</option><option>Bilanz</option><option>GuV</option>
                        </select>
                    </div>
                    <div className="flex gap-2 pt-2">
                         <Button fullWidth variant="primary" onClick={handleUpdate}>Kaydet</Button>
                    </div>
                </div>
              </div>
            ) : (
               <div className="hidden md:flex flex-col items-center justify-center h-full text-center text-slate-400 space-y-4">
                  <div className="p-4 bg-slate-50 rounded-full"><ArchiveBoxIcon className="w-12 h-12 text-slate-300" /></div>
                  <p className="text-sm">Listeden bir hesap seçin.</p>
               </div>
            )
          )}
        </div>
      </aside>

      {/* 4. MOBILE BOTTOM NAVIGATION */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 flex justify-around items-center h-16 z-40 pb-safe">
        <button 
          onClick={() => setActiveTab('IMPORT')}
          className={`flex flex-col items-center justify-center w-full h-full space-y-1 ${activeTab === 'IMPORT' ? 'text-blue-600' : 'text-slate-400'}`}
        >
          <DocumentArrowUpIcon className="w-6 h-6" />
          <span className="text-[10px] font-medium">Veri Ekle</span>
        </button>
        <button 
          onClick={() => setActiveTab('DATABASE')}
          className={`flex flex-col items-center justify-center w-full h-full space-y-1 ${activeTab === 'DATABASE' ? 'text-blue-600' : 'text-slate-400'}`}
        >
          <ArchiveBoxIcon className="w-6 h-6" />
          <span className="text-[10px] font-medium">Liste</span>
        </button>
      </div>

    </div>
  );
}

export interface AccountEntry {
  id: string;
  code: string;
  description: string;
  category: string;
  bilanzPosten?: string;
  programmverbindung?: string;
  abschlusszweck?: string;
  ai_insight?: string;
}

export type ViewMode = 'DATABASE' | 'IMPORT';

export enum PanelMode {
  DETAILS = 'DETAILS',
  IMPORT = 'IMPORT'
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { supabase } from './supabaseClient';
import { AccountEntry, ViewMode } from './types';
import { 
  TableCellsIcon, 
  DocumentArrowUpIcon, 
  MagnifyingGlassIcon, 
  FunnelIcon,
  ArchiveBoxIcon,
  ChevronRightIcon,
  TagIcon,
  FolderIcon,
  PencilSquareIcon,
  IdentificationIcon,
  InformationCircleIcon,
  ArrowPathIcon,
  BookOpenIcon,
  AcademicCapIcon,
  LightBulbIcon,
  PhotoIcon,
  SparklesIcon,
  XMarkIcon,
  DocumentTextIcon,
  ArrowLeftIcon,
  HomeIcon
} from '@heroicons/react/24/outline';

// --- Helper Components ---

const Button: React.FC<{
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'ghost' | 'danger-ghost';
  className?: string;
  fullWidth?: boolean;
  disabled?: boolean;
}> = ({ children, onClick, variant = 'primary', className = '', fullWidth = false, disabled = false }) => {
  const baseStyle = "px-4 py-2 rounded-md text-sm font-medium transition-colors duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 shadow-sm",
    secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50",
    ghost: "text-slate-600 hover:bg-slate-100 hover:text-slate-900",
    "danger-ghost": "text-red-600 hover:bg-red-50 hover:text-red-700"
  };

  return (
    <button 
      onClick={onClick} 
      disabled={disabled}
      className={`${baseStyle} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
    >
      {children}
    </button>
  );
};

// --- Logic Helpers ---

const getBasicAccountingInsight = (code: string): string => {
  const numericMatch = code.match(/\d+/);
  if (!numericMatch) return "Genel hesap.";
  const firstDigit = numericMatch[0][0];

  if (firstDigit === '0') return "Duran Varlıklar sınıfı.";
  if (firstDigit === '1') return "Dönen Varlıklar ve Finansal Hesaplar.";
  if (firstDigit === '2') return "Özkaynaklar veya Ara Hesaplar.";
  if (firstDigit === '3') return "Yabancı Kaynaklar (Borçlar).";
  if (firstDigit === '4') return "Gelir Hesapları.";
  if (firstDigit === '5' || firstDigit === '6') return "Gider Hesapları.";
  if (firstDigit === '9') return "Nazım Hesaplar.";
  return "Genel muhasebe hesabı.";
};

// --- Main Application ---

export default function App() {
  // State
  const [accounts, setAccounts] = useState<AccountEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<ViewMode>('IMPORT');
  const [rawInput, setRawInput] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState<string>("");

  // AI & Image State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analyzeStatus, setAnalyzeStatus] = useState<string>("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Insight AI State
  const [aiInsight, setAiInsight] = useState<string>("");
  const [isInsightLoading, setIsInsightLoading] = useState<boolean>(false);

  // Edit Form State
  const [editForm, setEditForm] = useState({
    programmverbindung: '',
    abschlusszweck: ''
  });

  // --- Supabase Integration ---

  const fetchAccounts = async () => {
    setLoading(true);
    setErrorMsg(null);
    try {
      let allData: any[] = [];
      let page = 0;
      const pageSize = 1000;
      let hasMore = true;

      // Loop to fetch all records in chunks of 1000 (bypassing the hard limit)
      while (hasMore) {
        const from = page * pageSize;
        const to = from + pageSize - 1;

        const { data, error } = await supabase
          .from('accounts')
          .select('*')
          .range(from, to)
          .order('code', { ascending: true });

        if (error) throw error;

        if (data && data.length > 0) {
          allData = [...allData, ...data];

          // If we received fewer rows than requested, we've reached the end
          if (data.length < pageSize) {
            hasMore = false;
          } else {
            page++;
          }
        } else {
          hasMore = false;
        }

        // Safety break to prevent infinite loop in edge cases (limit to 20k records)
        if (page > 20) hasMore = false;
      }

      const mappedData: AccountEntry[] = allData.map(item => ({
        id: item.id,
        code: item.code,
        description: item.description,
        category: item.category,
        bilanzPosten: item.bilanz_posten,
        programmverbindung: item.programmverbindung,
        abschlusszweck: item.abschlusszweck,
        ai_insight: item.ai_insight // Map the new column
      }));

      setAccounts(mappedData);
    } catch (error: any) {
      console.error('Error fetching accounts:', error);
      setErrorMsg(error.message || "Veriler çekilemedi.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAccounts();

    const channel = supabase
      .channel('schema-db-changes')
      .on(
        'postgres_changes',
        {
          event: '*', 
          schema: 'public',
          table: 'accounts',
        },
        () => {
          fetchAccounts();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  // Sync Edit Form & Trigger AI Insight when selection changes
  useEffect(() => {
    let isMounted = true;

    if (selectedId) {
        const account = accounts.find(a => a.id === selectedId);
        if (account) {
            // 1. Set form data
            setEditForm({
                programmverbindung: account.programmverbindung || '',
                abschlusszweck: account.abschlusszweck || 'Seçiniz'
            });

            // 2. CHECK IF INSIGHT EXISTS IN DB
            if (account.ai_insight && account.ai_insight.length > 10) {
                // If exists, use it directly (No API Cost)
                setAiInsight(account.ai_insight);
                setIsInsightLoading(false);
            } else {
                // If NOT exists, generate it
                const generateInsight = async () => {
                  setIsInsightLoading(true);
                  // Temporary placeholder while loading
                  setAiInsight(getBasicAccountingInsight(account.code)); 

                  try {
                    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
                    const model = "gemini-3-flash-preview"; 

                    const prompt = `Sen uzman bir muhasebecisin (Alman Hesap Planı SKR03/04 uzmanı).
                    Şu hesabı analiz et:
                    Kod: ${account.code}
                    İsim: ${account.description}
                    Kategori: ${account.category}

                    Lütfen bu hesap için Türkçe, profesyonel ama anlaşılır bir "Hesap İçgörüsü" metni yaz.
                    Metin şu 3 maddeyi içermelidir (madde işaretleri kullanma, akıcı bir paragraf olsun):
                    1. Bu hesabın temel amacı nedir?
                    2. Mali tablolarda (Bilanço/Gelir Tablosu) nerede durur ve neyi etkiler?
                    3. Pratik bir kullanım örneği ver (Örn: "Şirket yeni bir makine aldığında bu hesaba borç kaydedilir" gibi).

                    Metni kısa tut (maksimum 3-4 cümle).`;

                    const result = await ai.models.generateContent({
                      model: model,
                      contents: prompt
                    });

                    if (isMounted && result.text) {
                      const generatedText = result.text;
                      setAiInsight(generatedText);

                      // SAVE TO SUPABASE IMMEDIATELY
                      const { error } = await supabase
                        .from('accounts')
                        .update({ ai_insight: generatedText })
                        .eq('id', account.id);

                      if (error) {
                        console.error("Error saving insight:", error);
                      } else {
                        // Update local state to avoid re-fetching if user clicks away and back
                        setAccounts(prev => prev.map(a => 
                           a.id === account.id ? { ...a, ai_insight: generatedText } : a
                        ));
                      }
                    }
                  } catch (error) {
                    console.error("Insight generation failed", error);
                  } finally {
                    if (isMounted) setIsInsightLoading(false);
                  }
                };

                generateInsight();
            }
        }
    } else {
      setAiInsight("");
    }

    return () => {
      isMounted = false;
    };
  }, [selectedId, accounts]); // Dependence on accounts allows initial load, but we handle the loop inside


  // Derived State
  const selectedAccount = accounts.find(a => a.id === selectedId);
  const filteredAccounts = accounts.filter(acc => 
    acc.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
    acc.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (acc.bilanzPosten && acc.bilanzPosten.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  // Parsing & Inserting Logic
  const processAndInsertData = async (textInput: string) => {
    const lines = textInput.split('\n');
    const newEntries = [];
    const isMarkdownTable = lines.some(line => line.includes('|') && line.includes('---'));

    if (isMarkdownTable) {
        let currentCategory = "";
        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed || trimmed.startsWith('|-') || !trimmed.includes('|')) continue;
            const cols = trimmed.split('|').map(c => c.trim()).filter(c => c !== '');
            if (cols[0]?.toLowerCase().includes('category') || cols[0]?.toLowerCase().includes('bilanz')) continue;

            if (cols.length >= 2) {
                let category = cols[0];
                let code = "";
                let name = "";

                if (!category) {
                    category = currentCategory;
                } else {
                    currentCategory = category;
                }

                if (cols.length >= 3) {
                    code = cols[1];
                    name = cols[2];
                } else {
                    code = cols[1];
                    name = "İsimsiz Hesap"; 
                }

                if (code && code.match(/\d+/)) {
                    newEntries.push({
                        code: code,
                        description: name,
                        category: "Genel",
                        bilanz_posten: category,
                        ai_insight: null
                    });
                }
            }
        }
    } else {
        // Legacy parsing logic...
        let currentClass = "Genel";
        let currentBilanzPosten = "";
        let buffer: string[] = [];
        let expectingClassName = false;
        let pendingClassDigit = "";
        const ignorePatterns = [/^Bilanz-?$/i, /^Posten\d*\)?$/i, /^Programmverbindung\d*\)?$/i, /^Abschlusszweck\d*\)?$/i, /^\d+\)$/, /^Bilanz-$/];

        for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed) continue;
            if (ignorePatterns.some(p => p.test(trimmed))) continue;

            if (/^\d$/.test(trimmed)) {
                pendingClassDigit = trimmed;
                expectingClassName = true;
                buffer = []; 
                continue;
            }

            if (expectingClassName) {
                currentClass = `${pendingClassDigit} ${trimmed}`;
                expectingClassName = false;
                buffer = []; 
                currentBilanzPosten = ""; 
                continue;
            }

            const codeMatch = trimmed.match(/^(\d{4}|KU\s?[\d-]+|R\s?\d{4}[-]?\d{0,2})\s+(.*)/);

            if (codeMatch) {
                if (buffer.length > 0) {
                    currentBilanzPosten = buffer.join(" ");
                    buffer = [];
                }
                newEntries.push({ code: codeMatch[1], description: codeMatch[2], category: currentClass, bilanz_posten: currentBilanzPosten, ai_insight: null });
            } else {
                if (trimmed.length > 1) buffer.push(trimmed);
            }
        }
    }

    if (newEntries.length > 0) {
        const uniqueCodesInBatch = new Set();
        const deduplicatedEntries = [];
        for (const entry of newEntries) {
            if (!uniqueCodesInBatch.has(entry.code)) {
                uniqueCodesInBatch.add(entry.code);
                deduplicatedEntries.push(entry);
            }
        }

        const codesToCheck = deduplicatedEntries.map(e => e.code);

        const { data: existingData, error: checkError } = await supabase.from('accounts').select('code').in('code', codesToCheck);
        if (checkError) throw checkError;

        const existingSet = new Set(existingData?.map(d => d.code));
        const finalEntriesToInsert = deduplicatedEntries.filter(e => !existingSet.has(e.code));

        if (finalEntriesToInsert.length > 0) {
            const { error: insertError } = await supabase.from('accounts').insert(finalEntriesToInsert);
            if (insertError) {
                throw new Error("Kayıt hatası: " + insertError.message);
            }
            return { success: true, count: finalEntriesToInsert.length, skipped: deduplicatedEntries.length - finalEntriesToInsert.length };
        } else {
            return { success: true, count: 0, skipped: deduplicatedEntries.length };
        }
    }
    return { success: false, count: 0, skipped: 0 };
  };

  const handleProcessManualInput = useCallback(async () => {
    if (!rawInput.trim()) return;
    setLoading(true);
    try {
        const result = await processAndInsertData(rawInput);
        if (result.success) {
             if (result.count > 0) {
                alert(`${result.count} yeni kayıt eklendi.\n${result.skipped} mükerrer kayıt atlandı.`);
                setRawInput("");
                setActiveTab('DATABASE');
             } else {
                alert("Yeni kayıt bulunamadı (Tümü zaten mevcut).");
             }
        } else {
             alert("İşlenecek geçerli veri bulunamadı.");
        }
    } catch (e: any) {
        alert("Hata: " + e.message);
    } finally {
        setLoading(false);
    }
  }, [rawInput]);

  const handleUpdate = async () => {
    if (!selectedId) return;
    const { error } = await supabase.from('accounts').update({
            programmverbindung: editForm.programmverbindung,
            abschlusszweck: editForm.abschlusszweck === 'Seçiniz' ? null : editForm.abschlusszweck
        }).eq('id', selectedId);
    if (error) alert("Güncelleme hatası: " + error.message);
  };

  const readFileAsBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
            const result = reader.result as string;
            const base64 = result.split(',')[1];
            resolve(base64);
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  };

  const handleAutomaticFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;

    setIsAnalyzing(true);
    setAnalyzeStatus("Dosya okunuyor...");

    try {
        const base64Data = await readFileAsBase64(file);

        setAnalyzeStatus("AI Analizi yapılıyor... (Bu işlem birkaç saniye sürebilir)");
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const model = "gemini-3-flash-preview"; 

        const prompt = `Act as an expert accountant and OCR specialist. Analyze the attached file (Image or PDF) which shows a German Chart of Accounts (Kontenrahmen).
Convert this document content into a structured Markdown Table.
Columns MUST be: | Category | Code | Name |
If Category is missing, use the previous one. Ensure Codes are 4 digits.
Output ONLY the markdown table.`;

        const response = await ai.models.generateContent({
            model: model,
            contents: {
                parts: [
                    { inlineData: { mimeType: file.type, data: base64Data } },
                    { text: prompt }
                ]
            }
        });

        const text = response.text;

        if (text) {
            setAnalyzeStatus("Veriler ayrıştırılıyor ve kaydediliyor...");
            const result = await processAndInsertData(text);

            setIsAnalyzing(false);
            setAnalyzeStatus("");

            if (result.success) {
                if (result.count > 0) {
                   alert(`Başarılı! ${result.count} yeni kayıt eklendi. ${result.skipped > 0 ? `(${result.skipped} mükerrer atlandı)` : ''}`);
