                }
            } else {
                alert("Dosyadan anlamlı veri çıkarılamadı. Lütfen dosya kalitesini kontrol edin.");
            }
        } else {
            throw new Error("AI boş yanıt döndürdü.");
        }

    } catch (error: any) {
        console.error("Auto upload failed", error);
        alert("Otomatik yükleme sırasında hata: " + error.message);
        setIsAnalyzing(false);
        setAnalyzeStatus("");
    } finally {
        if (fileInputRef.current) fileInputRef.current.value = '';
