          <div className="flex items-center gap-2 text-white font-semibold text-lg">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
              <TableCellsIcon className="w-5 h-5" />
            </div>
            AccuParse
          </div>
        </div>
        <div className="flex-1 overflow-y-auto py-4">
          <div className="px-3 space-y-1">
            <p className="px-3 text-xs font-semibold uppercase tracking-wider text-slate-500 mb-2">Veri Yönetimi</p>
            <button onClick={() => setActiveTab('IMPORT')} className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'IMPORT' ? 'bg-blue-600 text-white' : 'hover:bg-slate-800'}`}>
              <DocumentArrowUpIcon className="w-5 h-5" />
              <span>Veri Ekle / Import</span>
            </button>
            <button onClick={() => setActiveTab('DATABASE')} className={`w-full text-left px-3 py-2 rounded-md flex items-center gap-3 transition-colors ${activeTab === 'DATABASE' ? 'bg-slate-800 text-white' : 'hover:bg-slate-800'}`}>
              <ArchiveBoxIcon className="w-5 h-5" />
              <span>Bilgi Bankası</span>
            </button>
          </div>
        </div>
        <div className="p-4 border-t border-slate-800 text-xs text-slate-500 flex justify-between items-center">
          <span>v1.8 (Mobile)</span>
          <div className={`w-2 h-2 rounded-full ${loading ? 'bg-yellow-500 animate-pulse' : 'bg-green-500'}`} title="Bağlantı Durumu"></div>
        </div>
      </nav>

      {/* 2. CENTER PANEL (Main Content) - Full Width on Mobile */}
      <main className="flex-1 flex flex-col min-w-0 bg-slate-50 relative border-r border-slate-200 h-full overflow-hidden pb-16 md:pb-0">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-4 md:px-6 flex-shrink-0">
          <div className="flex items-center gap-3">
             {/* Mobile Brand Icon */}
             <div className="md:hidden w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
                <TableCellsIcon className="w-5 h-5" />
             </div>
             <h1 className="text-lg md:text-xl font-semibold text-slate-800 truncate">
               {activeTab === 'IMPORT' ? 'Veri İçe Aktar' : 'Bilgi Bankası'}
             </h1>
          </div>
          <div className="flex items-center gap-2">
            {activeTab === 'DATABASE' && (
              <span className="text-xs md:text-sm text-slate-500 bg-slate-100 px-3 py-1 rounded-full flex items-center gap-2">
                {loading && <ArrowPathIcon className="w-3 h-3 animate-spin" />}
                {accounts.length} <span className="hidden sm:inline">Kayıt</span>
              </span>
            )}
          </div>
        </header>

        {activeTab === 'DATABASE' && (
          <>
            <div className="p-4 bg-white border-b border-slate-200 flex flex-col gap-3 flex-shrink-0">
               <div className="flex flex-col sm:flex-row items-center gap-3 w-full">
                  <div className="relative w-full sm:flex-1">
                     <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                     <input type="text" placeholder="Hesap ara..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-sm" />
                  </div>
                  <Button variant={showFilters ? 'primary' : 'secondary'} onClick={() => setShowFilters(!showFilters)} className="whitespace-nowrap">
                     <FunnelIcon className="w-5 h-5" /> Filtrele
