               <div className={`bg-slate-50 border-2 border-dashed ${isAnalyzing ? 'border-blue-400 bg-blue-50' : 'border-slate-300'} rounded-xl p-6 md:p-8 transition-all hover:border-blue-400 relative`}>
                  {isAnalyzing && (
