}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { supabase } from './supabaseClient';
import { AccountEntry, ViewMode, InvoiceData } from './types';
import { 
  TableCellsIcon, 
  DocumentArrowUpIcon, 
  MagnifyingGlassIcon, 
  FunnelIcon,
  ArchiveBoxIcon,
  ChevronRightIcon,
  TagIcon,
  FolderIcon,
  PencilSquareIcon,
  IdentificationIcon,
  InformationCircleIcon,
  ArrowPathIcon,
  BookOpenIcon,
  AcademicCapIcon,
  LightBulbIcon,
  PhotoIcon,
  SparklesIcon,
  XMarkIcon,
  DocumentTextIcon,
  ArrowLeftIcon,
  HomeIcon,
