// Simple Button Component
const Button = ({ variant = 'primary', className = '', fullWidth = false, children, ...props }: any) => {
    const baseClass = "px-4 py-2 rounded-md text-sm font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2";
    const variants: Record<string, string> = {
        primary: "bg-blue-600 text-white hover:bg-blue-700 focus:ring-blue-500",
        secondary: "bg-white text-slate-700 border border-slate-300 hover:bg-slate-50 focus:ring-indigo-500",
        ghost: "bg-transparent text-slate-600 hover:bg-slate-100 hover:text-slate-900",
    };
    return (
        <button 
            className={`${baseClass} ${variants[variant] || variants.primary} ${fullWidth ? 'w-full' : ''} ${className}`} 
            {...props}
        >
            {children}
        </button>
    );
};

export default function App() {
  // Authentication State
  const [user, setUser] = useState<{ role: 'admin' | 'user', name: string } | null>(null);
  const [adminEmail, setAdminEmail] = useState("cevikademm@gmail.com");
  const [adminPassword, setAdminPassword] = useState("123");

  // App State
  const [activeTab, setActiveTab] = useState<'DATABASE' | 'IMPORT' | 'HISTORY' | 'MESSAGES'>('HISTORY'); // Default to History as per request "fatura listesine tıklandığında" focus

  // Data States
  const [accounts, setAccounts] = useState<AccountEntry[]>([]);
  const [invoiceHistory, setInvoiceHistory] = useState<InvoiceData[]>(INITIAL_INVOICES);

  // --- SUPABASE MESSAGING STATES ---
  const [rawMessages, setRawMessages] = useState<any[]>([]);
  const [messageInput, setMessageInput] = useState("");

  // Admin Messaging States
  const [selectedThreadSender, setSelectedThreadSender] = useState<string | null>(null);
  const [adminMessageInput, setAdminMessageInput] = useState("");

  // UI States
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [showFilters, setShowFilters] = useState(false);
  const [filterCategory, setFilterCategory] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // Invoice Selection State (Right Panel & List Expansion)
  const [selectedInvoiceId, setSelectedInvoiceId] = useState<string | null>('1'); // Default select first
  const [invoiceImage, setInvoiceImage] = useState<string | null>(INITIAL_INVOICES[0].imageData || null);

  // File Upload States
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // 1. Fetch Accounts from Supabase (Bilgi Bankası)
  useEffect(() => {
    if (activeTab === 'DATABASE' && user) {
      const fetchAccounts = async () => {
        setLoading(true);
        try {
          const { data, error } = await supabase
            .from('accounts')
            .select('*')
            .order('code', { ascending: true });

          if (error) throw error;
          if (data) setAccounts(data);
        } catch (err) {
          console.error("Error fetching accounts:", err);
        } finally {
          setLoading(false);
        }
      };
      fetchAccounts();
    }
  }, [activeTab, user]);

  // 2. Fetch Messages from Supabase & Realtime Sub
  useEffect(() => {
    if (activeTab === 'MESSAGES' && user) {
      const fetchMessages = async () => {
        const { data } = await supabase
            .from('messages')
            .select('*')
            .order('created_at', { ascending: true });
        if (data) setRawMessages(data);
      };

      fetchMessages();

      // Realtime subscription
      const subscription = supabase
        .channel('public:messages')
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages' }, (payload) => {
          setRawMessages(prev => [...prev, payload.new]);
        })
        .subscribe();

      return () => {
        supabase.removeChannel(subscription);
      };
    }
  }, [activeTab, user]);

  // --- Derived Logic for Admin & User Views ---

  // For Admin: Group raw messages by Company to create "Threads"
  const adminThreads = useMemo(() => {
    if (user?.role !== 'admin') return [];

    const threads: Record<string, Message> = {};

    // Group by sender (if not admin) or recipient (if sent by admin)
    rawMessages.forEach(msg => {
        const otherParty = msg.sender === 'Admin Support' ? msg.recipient : msg.sender;

        // We only care about the latest message for the preview
        threads[otherParty] = {
            id: msg.id.toString(),
            sender: otherParty,
            subject: msg.subject || 'Konu Yok',
            preview: msg.content,
            date: new Date(msg.created_at).toLocaleDateString('tr-TR'),
            isRead: msg.is_read
        };
    });

    return Object.values(threads).sort((a, b) => b.id.localeCompare(a.id));
  }, [rawMessages, user]);

  // For Admin: Get messages for the selected thread in Right Panel
  const selectedThreadMessages = useMemo(() => {
    if (!selectedThreadSender || user?.role !== 'admin') return [];
    return rawMessages.filter(m => 
        (m.sender === 'Admin Support' && m.recipient === selectedThreadSender) ||
        (m.sender === selectedThreadSender && m.recipient === 'Admin Support')
    ).sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());
  }, [rawMessages, selectedThreadSender, user]);

  // For User: Filter raw messages for just this user and format for Chat View
  const userChatDisplay = useMemo(() => {
    if (user?.role !== 'user') return [];

    return rawMessages
        .filter(m => m.sender === user.name || m.recipient === user.name)
        .map(m => ({
            sender: m.sender === user.name ? 'user' : 'admin',
            text: m.content
        }));
  }, [rawMessages, user]);


  // Derived state for Filtering
  const uniqueCategories = useMemo(() => Array.from(new Set(accounts.map(a => a.category).filter(Boolean))), [accounts]);

  const filteredAccounts = useMemo(() => {
    return accounts.filter(acc => {
        const term = searchTerm.toLowerCase();
        const matchesSearch = 
            (acc.code || '').toLowerCase().includes(term) || 
            (acc.description || '').toLowerCase().includes(term);
        const matchesCategory = filterCategory ? acc.category === filterCategory : true;
        return matchesSearch && matchesCategory;
    });
  }, [searchTerm, filterCategory, accounts]);

  const selectedAccount = useMemo(() => accounts.find(a => a.id === selectedId), [selectedId, accounts]);

  // --- Handlers ---

  const handleLogin = (role: 'admin' | 'user', name: string) => {
      setUser({ role, name });
  };

  const handleInvoiceClick = (inv: InvoiceData) => {
    // Toggle expand
    if (selectedInvoiceId === inv.id) {
        // If clicking the same one, just ensure image is shown
        setInvoiceImage(inv.imageData || null);
    } else {
        setSelectedInvoiceId(inv.id);
        setInvoiceImage(inv.imageData || null);
    }
  };

  const handleAutomaticFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (file) {
          setIsAnalyzing(true);
          setTimeout(() => {
              setIsAnalyzing(false);
              const newItem: InvoiceData = {
                  id: Date.now().toString(),
                  merchantName: "Yeni Fatura Ltd.",
                  date: new Date().toISOString().split('T')[0],
                  totalAmount: "1.250,00",
                  taxAmount: "250,00",
                  currency: "EUR",
                  invoiceNumber: "TR-2024-NEW",
                  items: [
                      { description: "Hizmet Bedeli", quantity: "1", unitPrice: "1000", total: "1000", accountCode: "0005" }
                  ],
                  imageData: URL.createObjectURL(file),
                  isExpanded: true
              };
              setInvoiceHistory(prev => [newItem, ...prev]);
              setSelectedInvoiceId(newItem.id);
              setInvoiceImage(newItem.imageData || null);
              setActiveTab('HISTORY');
          }, 1500);
      }
  };

  const handleSendMessage = async () => {
    if (!messageInput.trim() || !user) return;

    try {
        const { error } = await supabase.from('messages').insert({
            sender: user.name,
            recipient: 'Admin Support', 
            content: messageInput,
            subject: 'Destek Talebi',
            is_read: false
        });

        if (error) {
            console.error('Error sending message:', error);
            alert("Mesaj gönderilemedi.");
        } else {
            setMessageInput("");
        }
    } catch (e) {
        console.error(e);
    }
  };

  const handleAdminReply = async () => {
      if (!adminMessageInput.trim() || !selectedThreadSender) return;

      try {
          const { error } = await supabase.from('messages').insert({
              sender: 'Admin Support',
              recipient: selectedThreadSender,
              content: adminMessageInput,
              subject: 'Re: Destek',
              is_read: false
          });

          if (error) {
              console.error('Error sending reply:', error);
              alert("Cevap gönderilemedi.");
          } else {
              setAdminMessageInput("");
          }
      } catch (e) {
          console.error(e);
      }
  };

  // --- LOGIN SCREEN ---
  if (!user) {
      return (
          <div className="h-screen w-screen bg-slate-900 flex items-center justify-center p-4">
              <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl overflow-hidden flex flex-col md:flex-row min-h-[500px]">

                  {/* Left: Admin Login */}
                  <div className="flex-1 p-10 flex flex-col justify-center border-b md:border-b-0 md:border-r border-slate-100">
                      <div className="mb-8">
                          <div className="w-12 h-12 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-white text-xl mb-4">A</div>
                          <h2 className="text-2xl font-bold text-slate-800">Admin Girişi</h2>
                          <p className="text-slate-500 text-sm mt-2">Yönetici hesabınızla devam edin.</p>
                      </div>

                      <form onSubmit={(e) => { e.preventDefault(); handleLogin('admin', 'Admin User'); }} className="space-y-4">
                          <div>
                              <label className="block text-xs font-bold text-slate-600 uppercase mb-1">E-Posta</label>
                              <input 
                                  type="email" 
                                  className="w-full bg-slate-50 border border-slate-200 rounded px-3 py-2 text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-blue-500"
                                  value={adminEmail}
                                  onChange={(e) => setAdminEmail(e.target.value)}
                              />
                          </div>
                          <div>
                              <label className="block text-xs font-bold text-slate-600 uppercase mb-1">Şifre</label>
                              <input 
                                  type="password" 
                                  className="w-full bg-slate-50 border border-slate-200 rounded px-3 py-2 text-sm text-slate-800 focus:outline-none focus:ring-2 focus:ring-blue-500"
                                  value={adminPassword}
                                  onChange={(e) => setAdminPassword(e.target.value)}
                              />
                          </div>
                          <Button fullWidth className="mt-4">Giriş Yap</Button>
                      </form>
                  </div>

                  {/* Right: Quick Company Login */}
                  <div className="flex-1 p-10 bg-slate-50 flex flex-col justify-center">
                      <div className="mb-6">
                          <h2 className="text-xl font-bold text-slate-800">Hızlı Şirket Girişi</h2>
                          <p className="text-slate-500 text-sm mt-1">Aşağıdaki şirketlerden biri olarak giriş yapın:</p>
                      </div>
                      <div className="space-y-3">
                          {RANDOM_COMPANIES.map(company => (
                              <button 
                                  key={company.id}
                                  onClick={() => handleLogin('user', company.name)}
                                  className="w-full flex items-center justify-between p-4 bg-white border border-slate-200 rounded-lg shadow-sm hover:shadow-md hover:border-blue-400 transition-all group"
                              >
                                  <div className="flex items-center gap-3">
                                      <div className="w-8 h-8 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center">
                                          <BuildingOfficeIcon className="w-4 h-4" />
                                      </div>
                                      <span className="font-medium text-slate-700 group-hover:text-blue-700">{company.name}</span>
                                  </div>
                                  <ChevronRightIcon className="w-4 h-4 text-slate-400 group-hover:text-blue-500" />
                              </button>
                          ))}
                      </div>
                  </div>

              </div>
          </div>
      );
  }

  // --- MAIN APP ---
  return (
    <div className="flex h-screen w-screen bg-slate-50 overflow-hidden font-sans text-slate-800">

      {/* 1. LEFT SIDEBAR */}
      <nav className="w-64 bg-[#0f172a] flex-shrink-0 flex flex-col text-slate-300 shadow-xl z-20">
        {/* Logo Area */}
        <div className="h-16 flex items-center px-6 border-b border-slate-800 bg-[#0f172a]">
             <div className="flex items-center gap-2 text-white">
                <div className="w-8 h-8 bg-blue-600 rounded flex items-center justify-center font-bold text-lg">A</div>
                <span className="font-bold text-lg tracking-tight">{t.app_name}</span>
             </div>
        </div>

        {/* User Info (Small) */}
        <div className="px-6 py-4 border-b border-slate-800 flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center text-white font-bold">
                {user.role === 'admin' ? 'A' : user.name.charAt(0)}
            </div>
            <div className="overflow-hidden">
                <div className="text-sm font-semibold text-white truncate">{user.name}</div>
                <div className="text-[10px] text-slate-500 uppercase">{user.role === 'admin' ? 'Administrator' : 'Company User'}</div>
            </div>
        </div>

        {/* Menu Items */}
        <div className="flex-col py-6 space-y-1 px-3">
            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wider px-3 mb-2">VERİ YÖNETİMİ</div>

            <button className="w-full flex items-center px-3 py-2.5 rounded-md text-sm font-medium text-slate-400 hover:text-white hover:bg-slate-800 transition-colors">
                <PencilSquareIcon className="w-5 h-5 mr-3" />
                {t.nav_fatura_girisi}
            </button>

            <button 
                onClick={() => setActiveTab('HISTORY')}
                className={`w-full flex items-center px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'HISTORY' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
            >
                <ClipboardDocumentListIcon className="w-5 h-5 mr-3" />
                {t.nav_fatura_listesi}
            </button>

            <button 
                onClick={() => setActiveTab('IMPORT')}
                className={`w-full flex items-center px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'IMPORT' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
            >
                <DocumentArrowUpIcon className="w-5 h-5 mr-3" />
                {t.nav_import}
            </button>

            <button 
                onClick={() => setActiveTab('DATABASE')}
                className={`w-full flex items-center px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'DATABASE' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
            >
                <ArchiveBoxIcon className="w-5 h-5 mr-3" />
                {t.nav_bilgi_bankasi}
            </button>

            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wider px-3 mb-2 mt-4">İLETİŞİM</div>

            <button 
                onClick={() => setActiveTab('MESSAGES')}
                className={`w-full flex items-center px-3 py-2.5 rounded-md text-sm font-medium transition-colors ${activeTab === 'MESSAGES' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
            >
                <ChatBubbleLeftRightIcon className="w-5 h-5 mr-3" />
                {t.nav_mesajlar}
                {user.role === 'admin' && <span className="ml-auto bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">2</span>}
            </button>

        </div>

        {/* Bottom Area */}
        <div className="mt-auto p-4 border-t border-slate-800">
            <button onClick={() => setUser(null)} className="w-full flex items-center px-3 py-2 rounded text-slate-400 hover:bg-slate-800 hover:text-white mb-4 transition-colors">
                <ArrowRightOnRectangleIcon className="w-4 h-4 mr-2" />
                <span className="text-xs">Çıkış Yap</span>
            </button>

            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-2">AYARLAR</div>
            <div className="flex items-center justify-between p-2 rounded bg-slate-800/50 border border-slate-700/50">
                <span className="text-xs text-slate-400">Dil / Sprache</span>
                <div className="flex text-[10px] font-bold">
                    <span className="bg-blue-600 text-white px-1.5 py-0.5 rounded-l">TR</span>
                    <span className="bg-slate-700 text-slate-400 px-1.5 py-0.5 rounded-r">DE</span>
                </div>
            </div>
            <div className="mt-4 text-[10px] text-slate-600">v2.3 (Invoice List)</div>
        </div>
      </nav>

      {/* 2. MIDDLE PANEL (Dynamic Content) */}
      <main className="flex-1 flex flex-col min-w-0 bg-white border-r border-slate-200">

        {/* HEADER AREA */}
        <div className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 flex-shrink-0">
            <h1 className="text-xl font-bold text-slate-800">
                {activeTab === 'DATABASE' && t.nav_bilgi_bankasi}
                {activeTab === 'HISTORY' && t.nav_fatura_listesi}
                {activeTab === 'IMPORT' && t.nav_import}
                {activeTab === 'MESSAGES' && t.nav_mesajlar}
            </h1>
            {activeTab === 'HISTORY' && (
                <div className="flex items-center gap-2 text-sm text-slate-400">
                    <span>{invoiceHistory.length} Fatura</span>
                </div>
            )}
        </div>

        {/* --- CONTENT AREA --- */}

        {/* MESSAGES VIEW */}
        {activeTab === 'MESSAGES' && (
            <div className="flex-1 overflow-auto bg-slate-50 p-6">
                {user.role === 'admin' ? (
                    <div className="space-y-4">
                        {adminThreads.length > 0 ? adminThreads.map(msg => (
                            <div 
                                key={msg.id} 
                                onClick={() => setSelectedThreadSender(msg.sender)}
                                className={`bg-white p-4 rounded-lg border shadow-sm cursor-pointer hover:shadow-md transition-all ${selectedThreadSender === msg.sender ? 'border-blue-500 ring-1 ring-blue-500' : 'border-slate-200'} ${!msg.isRead ? 'border-l-4 border-l-blue-500' : ''}`}
                            >
                                <div className="flex justify-between items-start mb-2">
                                    <div className="flex items-center gap-2">
                                        <div className="font-bold text-slate-800">{msg.sender}</div>
                                        {!msg.isRead && <span className="bg-blue-100 text-blue-600 text-[10px] font-bold px-2 py-0.5 rounded">YENİ</span>}
                                    </div>
                                    <span className="text-xs text-slate-400">{msg.date}</span>
                                </div>
                                <div className="font-semibold text-sm text-slate-700 mb-1">{msg.subject}</div>
                                <p className="text-sm text-slate-500 line-clamp-2">{msg.preview}</p>
                            </div>
                        )) : (
                           <div className="text-center text-slate-400 py-10">Henüz mesaj yok.</div>
                        )}
                    </div>
                ) : (
                    <div className="flex flex-col h-full bg-white rounded-lg border border-slate-200 overflow-hidden">
                        <div className="bg-slate-100 p-4 border-b border-slate-200 flex items-center gap-2">
                            <div className="w-8 h-8 bg-blue-600 rounded-full flex items-center justify-center text-white font-bold">A</div>
                            <div>
                                <div className="font-bold text-sm text-slate-800">Admin Support</div>
                                <div className="text-xs text-green-600">● Çevrimiçi</div>
                            </div>
                        </div>
                        <div className="flex-1 p-4 overflow-y-auto space-y-4">
                            {userChatDisplay.map((msg, idx) => (
                                <div key={idx} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                                    <div className={`${msg.sender === 'user' ? 'bg-blue-600 text-white rounded-l-lg rounded-tr-lg' : 'bg-slate-100 text-slate-800 rounded-r-lg rounded-tl-lg'} p-3 max-w-[80%] text-sm`}>
                                        {msg.text}
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="p-4 border-t border-slate-200 bg-slate-50 flex gap-2">
                            <input 
                                type="text" 
                                placeholder="Mesajınızı yazın..." 
                                className="flex-1 border border-slate-300 rounded px-3 py-2 text-sm focus:outline-none focus:border-blue-500" 
                                value={messageInput}
                                onChange={(e) => setMessageInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                            />
                            <Button onClick={handleSendMessage}>Gönder</Button>
                        </div>
                    </div>
                )}
            </div>
        )}

        {/* DATABASE VIEW */}
        {activeTab === 'DATABASE' && (
           <>
             {/* Search & Filter Bar */}
             <div className="p-4 border-b border-slate-200 bg-slate-50">
                <div className="flex gap-2">
                    <div className="relative flex-1">
                        <MagnifyingGlassIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
