                    </Button>
                </div>
                {/* Filter Dropdown */}
                {showFilters && (
                    <div className="mt-3 p-3 bg-white border border-slate-200 rounded-md shadow-sm flex gap-3">
                        <select 
                            className="text-sm border-slate-300 rounded-md shadow-sm focus:border-blue-500 focus:ring-blue-500"
                            value={filterCategory}
                            onChange={(e) => setFilterCategory(e.target.value)}
                        >
                            <option value="">Tüm Kategoriler</option>
                            {uniqueCategories.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                        <button onClick={() => setFilterCategory("")} className="text-xs text-red-500 hover:underline">{t.btn_clear}</button>
                    </div>
                )}
             </div>

             {/* Table */}
             <div className="flex-1 overflow-auto bg-white">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-50 sticky top-0 z-10">
                        <tr>
                            <th className="py-3 px-6 text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-32">{t.col_code}</th>
                            <th className="py-3 px-6 text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200">{t.col_desc}</th>
                            <th className="py-3 px-6 text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200 w-1/4">{t.col_category}</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {loading ? (
                            <tr><td colSpan={3} className="py-8 text-center text-slate-500">Yükleniyor...</td></tr>
                        ) : filteredAccounts.length === 0 ? (
                            <tr><td colSpan={3} className="py-8 text-center text-slate-400">Kayıt bulunamadı.</td></tr>
                        ) : (
                            filteredAccounts.map((acc) => (
                                <tr 
                                    key={acc.id} 
                                    onClick={() => setSelectedId(acc.id)}
                                    className={`cursor-pointer transition-colors hover:bg-slate-50 ${selectedId === acc.id ? 'bg-blue-50' : ''}`}
                                >
                                    <td className="py-3 px-6 text-sm font-semibold text-slate-900">{acc.code}</td>
                                    <td className="py-3 px-6 text-sm text-slate-600">{acc.description}</td>
                                    <td className="py-3 px-6 text-xs text-slate-500">{acc.category}</td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
             </div>
           </>
        )}

        {/* IMPORT VIEW */}
        {activeTab === 'IMPORT' && (
            <div className="flex-1 flex flex-col items-center justify-center p-8 bg-slate-50">
                <div className="bg-white p-12 rounded-2xl border border-dashed border-slate-300 flex flex-col items-center text-center max-w-lg w-full shadow-sm hover:border-blue-400 transition-colors">
                    <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mb-6">
