};

export default Tasks;

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_EMPLOYEES } from '../constants';
import { Branch, Employee, Role, CalendarEvent, Task } from '../types';
import { Plus, X, Calendar as CalendarIcon, Clock, MapPin, Users, Save, Building2, CheckCircle2, AlignLeft, Trash2, ChevronLeft, ChevronRight, AlertTriangle, CheckSquare, Loader2, Rocket, ArrowRightLeft } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';

interface CalendarProps {
    currentUser: Employee;
}

// Helper interface to merge Tasks and Events for display
interface DisplayEvent extends CalendarEvent {
    isTask?: boolean; // Distinguish between standard events and tasks
    status?: string; // For tasks
}

const Calendar: React.FC<CalendarProps> = ({ currentUser }) => {
  // --- STATE MANAGEMENT ---
  const [viewDate, setViewDate] = useState(new Date()); // Tracks the currently viewed month
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const { t, formatDate, language } = useLanguage();

  // State for Events & Tasks
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);

  // Modal State
  const [showAddModal, setShowAddModal] = useState(false);

  // Selection State
  const [selectedEvent, setSelectedEvent] = useState<DisplayEvent | null>(null);
  const [selectedBranches, setSelectedBranches] = useState<Branch[]>([]);

  // TRANSFER LOGIC STATE
  const [targetBranch, setTargetBranch] = useState<Branch>(Branch.DOM);

  // Form State
  const [newEventForm, setNewEventForm] = useState<Partial<CalendarEvent>>({
      title: '',
      type: 'Toplantı',
      date: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0], 
      startTime: '09:00',
      endTime: '10:00',
      attendees: [],
      description: ''
  });

  // Fetch events and tasks from DB
  useEffect(() => {
    const fetchData = async () => {
        setIsLoading(true);
        try {
            // 1. Fetch Calendar Events
            // GÜVENLİK FİLTRESİ: Admin değilse sadece katılımcısı olduğu etkinlikleri çek
            let eventQuery = supabase.from('calendar_events').select('*');
            if (currentUser.role !== Role.ADMIN) {
                eventQuery = eventQuery.contains('attendees', [currentUser.id]);
            }

            const { data: eventData, error: eventError } = await eventQuery;

            if (eventError) {
                console.error("Calendar fetch error:", eventError);
            } else if (eventData) {
                const dbEvents: CalendarEvent[] = eventData.map((e: any) => ({
                    id: e.id,
                    title: e.title,
                    type: e.type,
                    date: e.date,
                    endDate: e.end_date || e.date,
                    startTime: e.start_time,
                    endTime: e.end_time,
                    attendees: e.attendees || [],
                    description: e.description
                }));
                setEvents(dbEvents);
            }

            // 2. Fetch Tasks for Calendar Integration
            // GÜVENLİK FİLTRESİ: Admin değilse sadece kendine atanan görevleri çek
            let taskQuery = supabase.from('tasks').select('*');
            if (currentUser.role !== Role.ADMIN) {
                taskQuery = taskQuery.contains('assigned_to', [currentUser.id]);
            }

            const { data: taskData, error: taskError } = await taskQuery;

            if (taskError) {
                 console.error("Task fetch error:", taskError);
            } else if(taskData) {
                 const dbTasks: Task[] = taskData.map((t: any) => ({
                    id: t.id,
                    title: t.title,
                    description: t.description,
                    assignedTo: t.assigned_to || [],
                    dueDate: t.due_date,
                    priority: t.priority,
                    status: t.status,
                    progress: t.progress,
                    checklist: t.checklist || []
                }));
                setTasks(dbTasks);
            }

        } catch (e) {
            console.log("Data fetch error:", e);
        } finally {
            setIsLoading(false);
        }
    };
    fetchData();
  }, [currentUser]); // Refresh when user changes to ensure permission logic is fresh

  // --- DATE HELPERS ---
  const currentYear = viewDate.getFullYear();
  const currentMonth = viewDate.getMonth();

  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
  const firstDayIndex = new Date(currentYear, currentMonth, 1).getDay(); 
  const startingSlot = firstDayIndex === 0 ? 6 : firstDayIndex - 1;

  const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const paddingDays = Array.from({ length: startingSlot }, (_, i) => i);

  const handlePrevMonth = () => {
      setViewDate(new Date(currentYear, currentMonth - 1, 1));
  };

  const handleNextMonth = () => {
      setViewDate(new Date(currentYear, currentMonth + 1, 1));
  };

  // Helper: Translate Title/Description if it's a key
  const getText = (text?: string) => {
    if (!text) return '';
    return text.startsWith('task.mock') ? t(text) : text;
  };

  // --- MERGING LOGIC (Client-side fail-safe filtering included) ---
  const combinedEvents = useMemo((): DisplayEvent[] => {

      const filteredEvents = currentUser.role === Role.ADMIN 
          ? events 
          : events.filter(evt => evt.attendees.includes(currentUser.id));

      const filteredTasks = currentUser.role === Role.ADMIN
          ? tasks
          : tasks.filter(t => t.assignedTo.includes(currentUser.id));

      // Convert Tasks to DisplayEvents
      const taskEvents: DisplayEvent[] = filteredTasks.map(t => ({
          id: t.id,
          title: t.title,
          type: 'Diğer', // Placeholder type
          date: t.dueDate, // Use Due Date
          endDate: t.dueDate,
          startTime: '09:00', // Default start
          endTime: '18:00', // Default end
          attendees: t.assignedTo,
          description: t.description,
          isTask: true,
          status: t.status
      }));

      // Return as DisplayEvent[] explicitly
      return [...(filteredEvents as DisplayEvent[]), ...taskEvents];
  }, [events, tasks, currentUser]);


  const toggleBranchSelection = (branch: Branch) => {
    setSelectedBranches(prev => 
        prev.includes(branch) ? prev.filter(b => b !== branch) : [...prev, branch]
    );
  };

  const toggleAttendee = (employeeId: string) => {
    setNewEventForm(prev => {
        const current = prev.attendees || [];
        return current.includes(employeeId) 
            ? { ...prev, attendees: current.filter(id => id !== employeeId) }
            : { ...prev, attendees: [...current, employeeId] };
    });
  };

  const handleSaveEvent = async (e: React.FormEvent) => {
      e.preventDefault();

      const isTransfer = newEventForm.type === 'Şube Transferi';

      if (!newEventForm.title && !isTransfer) {
          alert(t('cal.warnTitle'));
          return;
      }
      if (isTransfer && (!newEventForm.attendees || newEventForm.attendees.length === 0)) {
          alert(t('cal.warnTransfer'));
          return;
      }

      setIsSaving(true);
      try {
          // Eğer Transfer işlemi ise otomatik başlık oluştur
          const finalTitle = isTransfer 
            ? `${newEventForm.attendees?.length} ${language === 'de' ? 'Personal' : 'Personel'} -> ${targetBranch} Transfer` 
            : newEventForm.title!;

          const dbPayload = {
              title: finalTitle,
              type: newEventForm.type,
              date: newEventForm.date,
              end_date: newEventForm.endDate || newEventForm.date,
              start_time: newEventForm.startTime,
              end_time: newEventForm.endTime,
              attendees: newEventForm.attendees || [],
              description: newEventForm.description
          };

          // 1. Önce Etkinliği Oluştur
          const { data, error } = await supabase.from('calendar_events').insert([dbPayload]).select();
          if (error) throw error;

          // 2. Eğer Şube Transferi ise, Personellerin Profilini Güncelle
          if (isTransfer && newEventForm.attendees && newEventForm.attendees.length > 0) {
              // Seçilen tüm personellerin şubesini hedef şube yap
              if (currentUser.role === Role.ADMIN) {
                 const { error: updateError } = await supabase
                    .from('profiles')
                    .update({ branch: targetBranch })
                    .in('id', newEventForm.attendees);

                 if(updateError) console.error("Profil güncelleme hatası:", updateError);
              }
          }

          if (data) {
              const newEvent: CalendarEvent = {
                  id: data[0].id,
                  title: data[0].title,
                  type: data[0].type,
                  date: data[0].date,
                  endDate: data[0].end_date,
                  startTime: data[0].start_time,
                  endTime: data[0].end_time,
                  attendees: data[0].attendees || [],
                  description: data[0].description
              };
              setEvents(prev => [...prev, newEvent]);
              setShowAddModal(false);
              // Reset form
              setNewEventForm({
                  title: '', type: 'Toplantı', 
                  date: new Date().toISOString().split('T')[0],
                  endDate: new Date().toISOString().split('T')[0],
                  startTime: '09:00', endTime: '10:00', attendees: [], description: ''
              });
              setSelectedBranches([]);
              setTargetBranch(Branch.DOM);
              alert(t('common.success'));
          }

      } catch (err: any) {
          console.error("Etkinlik kaydetme hatası:", err);
          alert("Kaydedilirken bir hata oluştu: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const handleDeleteEvent = async () => {
      if (!selectedEvent) return;
      if (selectedEvent.isTask) {
          alert("Görevler buradan silinemez. Lütfen Görevler panelini kullanın.");
          return;
      }

      if (confirm('Bu etkinliği silmek istediğinize emin misiniz?')) {
          try {
              const { error } = await supabase.from('calendar_events').delete().eq('id', selectedEvent.id);
              if (error) throw error;
              setEvents(events.filter(e => e.id !== selectedEvent.id));
              setSelectedEvent(null);
          } catch (err) {
              console.error("Silme hatası:", err);
              alert("Silinemedi.");
          }
      }
  };

  // Helper to get translated Type Name
  const getTypeName = (type: string) => {
      switch(type) {
          case 'Toplantı': return t('cal.type.meeting');
          case 'Montaj': return t('cal.type.assembly');
          case 'Teslim Tarihi': return t('cal.type.deadline');
          case 'Şube Transferi': return t('cal.type.transfer');
          default: return t('cal.type.other');
      }
