            </div>
        )}

        {/* --- LEFT / MAIN PANEL: CALENDAR GRID --- */}
        <div className="flex-1 flex flex-col h-full overflow-hidden p-2 md:p-6 items-center justify-center">

            <div className="w-full max-w-[500px] md:max-w-full flex flex-col h-full">
                <header className="mb-2 md:mb-6 flex justify-between items-center w-full shrink-0 px-2">
                    <div className="flex items-center gap-4">
                        <h2 className="text-lg md:text-2xl font-bold text-white tracking-tight min-w-[140px]">
