              {/* Card 1: Active Personnel (STAFF ONLY) */}
              <div className="rounded-3xl border border-zinc-800 bg-zinc-900/40 p-6 flex flex-col justify-between hover:bg-zinc-900/60 transition-all cursor-pointer group" onClick={() => navigateTo('payroll')}>
                  <div className="flex justify-between items-start">
