export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_EMPLOYEES } from '../constants';
import { Branch, Employee, Role, CalendarEvent, Task } from '../types';
import { Plus, X, Calendar as CalendarIcon, Clock, MapPin, Users, Save, Building2, CheckCircle2, AlignLeft, Trash2, ChevronLeft, ChevronRight, AlertTriangle, CheckSquare, Loader2, Rocket, ArrowRightLeft, CalendarRange } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';

interface CalendarProps {
    currentUser: Employee;
}

// Helper interface to merge Tasks and Events for display
interface DisplayEvent extends CalendarEvent {
    isTask?: boolean; // Distinguish between standard events and tasks
    status?: string; // For tasks
}

const Calendar: React.FC<CalendarProps> = ({ currentUser }) => {
  // --- STATE MANAGEMENT ---
  // viewDate artık haftanın başlangıcını hesaplamak için referans noktasıdır.
  const [viewDate, setViewDate] = useState(new Date()); 
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const { t, formatDate, language } = useLanguage();

  // State for Events & Tasks
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);

  // Modal State
  const [showAddModal, setShowAddModal] = useState(false);

  // Selection State
  const [selectedEvent, setSelectedEvent] = useState<DisplayEvent | null>(null);
  const [selectedBranches, setSelectedBranches] = useState<Branch[]>([]);

  // TRANSFER LOGIC STATE
  const [targetBranch, setTargetBranch] = useState<Branch>(Branch.DOM);

  // Form State
  const [newEventForm, setNewEventForm] = useState<Partial<CalendarEvent>>({
      title: '',
      type: 'Toplantı',
      date: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0], 
      startTime: '09:00',
      endTime: '10:00',
      attendees: [],
      description: ''
  });

  // Fetch events and tasks from DB
  useEffect(() => {
    const fetchData = async () => {
        setIsLoading(true);
        try {
            // 1. Fetch Calendar Events
            let eventQuery = supabase.from('calendar_events').select('*');
            if (currentUser.role !== Role.ADMIN) {
                eventQuery = eventQuery.contains('attendees', [currentUser.id]);
            }

            const { data: eventData, error: eventError } = await eventQuery;

            if (eventError) {
                console.error("Calendar fetch error:", eventError);
            } else if (eventData) {
                const dbEvents: CalendarEvent[] = eventData.map((e: any) => ({
                    id: e.id,
                    title: e.title,
                    type: e.type,
                    date: e.date,
                    endDate: e.end_date || e.date,
                    startTime: e.start_time,
                    endTime: e.end_time,
                    attendees: e.attendees || [],
                    description: e.description
                }));
                setEvents(dbEvents);
            }

            // 2. Fetch Tasks for Calendar Integration
            let taskQuery = supabase.from('tasks').select('*');
            if (currentUser.role !== Role.ADMIN) {
                taskQuery = taskQuery.contains('assigned_to', [currentUser.id]);
            }

            const { data: taskData, error: taskError } = await taskQuery;

            if (taskError) {
                 console.error("Task fetch error:", taskError);
            } else if(taskData) {
                 const dbTasks: Task[] = taskData.map((t: any) => ({
                    id: t.id,
                    title: t.title,
                    description: t.description,
                    assignedTo: t.assigned_to || [],
                    dueDate: t.due_date,
                    priority: t.priority,
                    status: t.status,
                    progress: t.progress,
                    checklist: t.checklist || []
                }));
                setTasks(dbTasks);
            }

        } catch (e) {
            console.log("Data fetch error:", e);
        } finally {
            setIsLoading(false);
        }
    };
    fetchData();
  }, [currentUser]); 

  // --- WEEKLY DATE LOGIC ---
  const getStartOfWeek = (date: Date) => {
      const d = new Date(date);
      const day = d.getDay(); // 0 (Sun) - 6 (Sat)
      // Pazartesi'yi haftanın başı yap (0 -> -6, 1 -> 0, 2 -> 1 ...)
      // Pazar (0) ise -6 gün git, diğer günler (day-1) gün git.
      const diff = d.getDate() - day + (day === 0 ? -6 : 1);
      return new Date(d.setDate(diff));
  };

  const currentWeekStart = useMemo(() => getStartOfWeek(viewDate), [viewDate]);

  const weekDays = useMemo(() => {
      return Array.from({ length: 7 }, (_, i) => {
          const d = new Date(currentWeekStart);
          d.setDate(d.getDate() + i);
          return d;
      });
  }, [currentWeekStart]);

  const handlePrevWeek = () => {
      const d = new Date(viewDate);
      d.setDate(d.getDate() - 7);
      setViewDate(d);
  };

  const handleNextWeek = () => {
      const d = new Date(viewDate);
      d.setDate(d.getDate() + 7);
      setViewDate(d);
  };

  const isToday = (date: Date) => {
      const today = new Date();
      return date.getDate() === today.getDate() &&
             date.getMonth() === today.getMonth() &&
             date.getFullYear() === today.getFullYear();
  };

  // Helper: Translate Title/Description if it's a key
  const getText = (text?: string) => {
    if (!text) return '';
    return text.startsWith('task.mock') ? t(text) : text;
  };

  // --- MERGING LOGIC ---
  const combinedEvents = useMemo((): DisplayEvent[] => {

      const filteredEvents = currentUser.role === Role.ADMIN 
          ? events 
          : events.filter(evt => evt.attendees.includes(currentUser.id));

      const filteredTasks = currentUser.role === Role.ADMIN
          ? tasks
          : tasks.filter(t => t.assignedTo.includes(currentUser.id));

      const taskEvents: DisplayEvent[] = filteredTasks.map(t => ({
          id: t.id,
          title: t.title,
          type: 'Diğer', 
          date: t.dueDate,
          endDate: t.dueDate,
          startTime: '09:00',
          endTime: '18:00',
          attendees: t.assignedTo,
          description: t.description,
          isTask: true,
          status: t.status
      }));

      return [...(filteredEvents as DisplayEvent[]), ...taskEvents];
  }, [events, tasks, currentUser]);


  const toggleBranchSelection = (branch: Branch) => {
    setSelectedBranches(prev => 
        prev.includes(branch) ? prev.filter(b => b !== branch) : [...prev, branch]
    );
  };

  const toggleAttendee = (employeeId: string) => {
    setNewEventForm(prev => {
        const current = prev.attendees || [];
        return current.includes(employeeId) 
            ? { ...prev, attendees: current.filter(id => id !== employeeId) }
            : { ...prev, attendees: [...current, employeeId] };
    });
  };

  const handleSaveEvent = async (e: React.FormEvent) => {
      e.preventDefault();

      const isTransfer = newEventForm.type === 'Şube Transferi';

      if (!newEventForm.title && !isTransfer) {
          alert(t('cal.warnTitle'));
          return;
      }
      if (isTransfer && (!newEventForm.attendees || newEventForm.attendees.length === 0)) {
          alert(t('cal.warnTransfer'));
          return;
      }

      setIsSaving(true);
      try {
          const finalTitle = isTransfer 
            ? `${newEventForm.attendees?.length} ${language === 'de' ? 'Personal' : 'Personel'} -> ${targetBranch} Transfer` 
            : newEventForm.title!;

          const dbPayload = {
              title: finalTitle,
              type: newEventForm.type,
              date: newEventForm.date,
              end_date: newEventForm.endDate || newEventForm.date,
              start_time: newEventForm.startTime,
              end_time: newEventForm.endTime,
              attendees: newEventForm.attendees || [],
              description: newEventForm.description
          };

          const { data, error } = await supabase.from('calendar_events').insert([dbPayload]).select();
          if (error) throw error;

          if (isTransfer && newEventForm.attendees && newEventForm.attendees.length > 0) {
              if (currentUser.role === Role.ADMIN) {
                 const { error: updateError } = await supabase
                    .from('profiles')
                    .update({ branch: targetBranch })
                    .in('id', newEventForm.attendees);

                 if(updateError) console.error("Profil güncelleme hatası:", updateError);
              }
          }

          if (data) {
              const newEvent: CalendarEvent = {
                  id: data[0].id,
                  title: data[0].title,
                  type: data[0].type,
                  date: data[0].date,
                  endDate: data[0].end_date,
                  startTime: data[0].start_time,
                  endTime: data[0].end_time,
                  attendees: data[0].attendees || [],
                  description: data[0].description
              };
              setEvents(prev => [...prev, newEvent]);
              setShowAddModal(false);
              setNewEventForm({
                  title: '', type: 'Toplantı', 
                  date: new Date().toISOString().split('T')[0],
                  endDate: new Date().toISOString().split('T')[0],
                  startTime: '09:00', endTime: '10:00', attendees: [], description: ''
              });
              setSelectedBranches([]);
              setTargetBranch(Branch.DOM);
              alert(t('common.success'));
          }

      } catch (err: any) {
          console.error("Etkinlik kaydetme hatası:", err);
          alert("Kaydedilirken bir hata oluştu: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const handleDeleteEvent = async () => {
      if (!selectedEvent) return;
      if (selectedEvent.isTask) {
          alert("Görevler buradan silinemez. Lütfen Görevler panelini kullanın.");
          return;
      }

      if (confirm('Bu etkinliği silmek istediğinize emin misiniz?')) {
          try {
              const { error } = await supabase.from('calendar_events').delete().eq('id', selectedEvent.id);
              if (error) throw error;
              setEvents(events.filter(e => e.id !== selectedEvent.id));
              setSelectedEvent(null);
          } catch (err) {
              console.error("Silme hatası:", err);
              alert("Silinemedi.");
          }
      }
  };

  const getTypeName = (type: string) => {
      switch(type) {
          case 'Toplantı': return t('cal.type.meeting');
          case 'Montaj': return t('cal.type.assembly');
          case 'Teslim Tarihi': return t('cal.type.deadline');
          case 'Şube Transferi': return t('cal.type.transfer');
          default: return t('cal.type.other');
      }
  }

  const getTypeColor = (type: string, isTask?: boolean) => {
      if (isTask) {
          return 'bg-gradient-to-r from-blue-900/40 to-indigo-900/40 border-indigo-500/30 text-blue-100 hover:brightness-125 hover:border-indigo-400';
      }

      switch(type) {
          case 'Toplantı': return 'bg-indigo-900/30 border-indigo-500/30 text-indigo-200 hover:bg-indigo-900/50 hover:border-indigo-400';
          case 'Montaj': return 'bg-amber-900/30 border-amber-500/30 text-amber-200 hover:bg-amber-900/50 hover:border-amber-400';
          case 'Teslim Tarihi': return 'bg-red-900/30 border-red-500/30 text-red-200 hover:bg-red-900/50 hover:border-red-400';
          case 'Şube Transferi': return 'bg-gradient-to-r from-orange-600/60 to-red-600/60 text-white border-orange-500/50 shadow-[0_0_10px_rgba(234,88,12,0.2)]';
          default: return 'bg-zinc-800/50 border-zinc-700 text-zinc-300 hover:bg-zinc-700';
      }
  };

  const getBadgeColor = (type: string, isTask?: boolean) => {
      if (isTask) return 'bg-blue-500/20 text-blue-300 border-blue-500/30';

      switch(type) {
          case 'Toplantı': return 'bg-indigo-500/20 text-indigo-300 border-indigo-500/30';
          case 'Montaj': return 'bg-amber-500/20 text-amber-300 border-amber-500/30';
          case 'Teslim Tarihi': return 'bg-red-500/20 text-red-300 border-red-500/30';
          case 'Şube Transferi': return 'bg-orange-500/20 text-orange-300 border-orange-500/30';
          default: return 'bg-zinc-700/50 text-zinc-300 border-zinc-600';
      }
  };

  // Date Range Display for Header
  const weekRangeString = useMemo(() => {
      const start = weekDays[0];
      const end = weekDays[6];
      return `${formatDate(start, {day: 'numeric', month: 'short'})} - ${formatDate(end, {day: 'numeric', month: 'short', year: 'numeric'})}`;
  }, [weekDays, formatDate]);

  return (
    <div className="flex h-full relative overflow-hidden">

        {/* --- MODAL: NEW EVENT / TRANSFER --- */}
        {showAddModal && (
            <div className="fixed inset-0 z-[100] flex justify-center sm:items-center bg-black/80 backdrop-blur-sm p-0 sm:p-4 animate-in fade-in duration-200">
                <div className="bg-zinc-900 border-zinc-800 sm:border sm:rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col h-full sm:h-auto sm:max-h-[90dvh] animate-in slide-in-from-bottom-10 sm:zoom-in-95 ring-1 ring-white/10">

                    <div className="p-5 border-b border-zinc-800 flex justify-between items-center bg-zinc-950/80 backdrop-blur-xl shrink-0 gap-4">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2 flex-1 min-w-0">
                            {newEventForm.type === 'Şube Transferi' ? (
                                <><Rocket size={20} className="text-orange-500 shrink-0" /> <span className="truncate">{t('cal.transfer')}</span></>
                            ) : (
                                <><CalendarIcon size={20} className="text-indigo-500 shrink-0" /> <span className="truncate">{t('cal.newEvent')}</span></>
                            )}
                        </h3>
                        <button onClick={() => setShowAddModal(false)} className="p-2 bg-zinc-800/50 rounded-lg text-zinc-400 hover:text-white hover:bg-zinc-800 transition-colors"><X size={20} /></button>
                    </div>

                    <div className="p-6 overflow-y-auto custom-scrollbar flex-1 pb-32">
                        <form id="eventForm" onSubmit={handleSaveEvent} className="space-y-6">
                            {/* ... (Existing Form Fields Unchanged) ... */}
                            <div className="space-y-1.5">
                                <label className="text-xs font-medium text-zinc-400">{t('cal.type')}</label>
                                <select 
                                    value={newEventForm.type} 
                                    onChange={e => setNewEventForm({...newEventForm, type: e.target.value as any})} 
                                    className={`w-full bg-zinc-950 border rounded-lg px-3 py-2.5 text-sm text-white outline-none transition-colors ${newEventForm.type === 'Şube Transferi' ? 'border-orange-500 ring-1 ring-orange-500' : 'border-zinc-800 focus:border-indigo-500'}`}
                                >
                                    <option value="Toplantı">{t('cal.type.meeting')}</option>
                                    <option value="Montaj">{t('cal.type.assembly')}</option>
                                    <option value="Teslim Tarihi">{t('cal.type.deadline')}</option>
                                    <option value="Şube Transferi">🚀 {t('cal.type.transfer')}</option>
                                    <option value="Diğer">{t('cal.type.other')}</option>
                                </select>
                            </div>

                            {newEventForm.type !== 'Şube Transferi' && (
                                <div className="space-y-1.5">
                                    <label className="text-xs font-medium text-zinc-400">{t('cal.eventTitle')}</label>
                                    <input type="text" required value={newEventForm.title} onChange={e => setNewEventForm({...newEventForm, title: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-white focus:border-indigo-500 outline-none" placeholder="..." />
                                </div>
                            )}

                             {newEventForm.type === 'Şube Transferi' && (
                                <div className="p-4 bg-orange-950/20 border border-orange-500/30 rounded-xl space-y-3">
                                    <label className="text-xs font-bold text-orange-400 flex items-center gap-2">
                                        <ArrowRightLeft size={14} /> {t('cal.targetBranch')}
                                    </label>
                                    <div className="grid grid-cols-2 gap-2">
                                        {Object.values(Branch).map(branch => (
                                            <button 
                                                key={branch}
                                                type="button"
                                                onClick={() => setTargetBranch(branch)}
                                                className={`px-3 py-2 text-xs font-medium rounded-lg border transition-all ${targetBranch === branch ? 'bg-orange-600 text-white border-orange-500 shadow-lg' : 'bg-zinc-900 text-zinc-400 border-zinc-800 hover:border-zinc-700'}`}
                                            >
                                                {branch}
                                            </button>
                                        ))}
                                    </div>
                                    <p className="text-[10px] text-zinc-500">* {t('cal.transferNote')}</p>
                                </div>
                            )}

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5">
                                    <label className="text-xs font-medium text-zinc-400">{t('cal.startDate')}</label>
                                    <input type="date" required value={newEventForm.date} onChange={e => setNewEventForm({...newEventForm, date: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white focus:border-indigo-500 outline-none [color-scheme:dark]" />
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs font-medium text-zinc-400">{t('cal.endDate')}</label>
                                    <input type="date" required value={newEventForm.endDate || newEventForm.date} onChange={e => setNewEventForm({...newEventForm, endDate: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white focus:border-indigo-500 outline-none [color-scheme:dark]" />
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1.5">
                                    <label className="text-xs font-medium text-zinc-400">{t('cal.startTime')}</label>
                                    <input type="time" required value={newEventForm.startTime} onChange={e => setNewEventForm({...newEventForm, startTime: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white focus:border-indigo-500 outline-none [color-scheme:dark]" />
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-xs font-medium text-zinc-400">{t('cal.endTime')}</label>
                                    <input type="time" required value={newEventForm.endTime} onChange={e => setNewEventForm({...newEventForm, endTime: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white focus:border-indigo-500 outline-none [color-scheme:dark]" />
                                </div>
                            </div>

                            <div className="p-4 bg-zinc-950/50 border border-zinc-800 rounded-xl space-y-4">
                                <div className="space-y-2">
                                    <label className="text-xs font-medium text-zinc-400 flex items-center gap-2">
                                        <Building2 size={14}/> {newEventForm.type === 'Şube Transferi' ? t('cal.sourceBranch') : t('cal.branchFilter')}
                                    </label>
                                    <div className="flex flex-wrap gap-2">
                                        {Object.values(Branch).map(branch => (
                                            <button
                                                key={branch}
                                                type="button"
                                                onClick={() => toggleBranchSelection(branch)}
                                                className={`px-3 py-1.5 text-xs rounded-lg border transition-all ${selectedBranches.includes(branch) ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800 hover:border-zinc-700'}`}
                                            >
                                                {branch}
                                            </button>
                                        ))}
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-xs font-medium text-zinc-400 flex items-center gap-2">
                                        <Users size={14}/> {newEventForm.type === 'Şube Transferi' ? t('cal.transferStaff') : t('cal.attendees')}
                                    </label>
                                    {selectedBranches.length === 0 ? (
                                        <div className="text-xs text-zinc-600 italic px-2">{t('cal.warnBranchFilter')}</div>
                                    ) : (
                                        <div className="flex gap-2 overflow-x-auto pb-2 custom-scrollbar">
                                            {MOCK_EMPLOYEES.filter(e => selectedBranches.includes(e.branch)).map(emp => {
                                                const isSelected = newEventForm.attendees?.includes(emp.id);
                                                return (
                                                    <div key={emp.id} onClick={() => toggleAttendee(emp.id)} className={`cursor-pointer flex items-center gap-2 px-3 py-2 rounded-lg border transition-all min-w-[140px] flex-shrink-0 ${isSelected ? 'bg-indigo-900/30 border-indigo-500/50' : 'bg-zinc-900 border-zinc-800 hover:border-zinc-700'}`}>
                                                        <div className="relative">
                                                            <img src={emp.avatarUrl} className="w-8 h-8 rounded-full" />
                                                            {isSelected && <div className="absolute -top-1 -right-1 w-3 h-3 bg-indigo-500 rounded-full border-2 border-zinc-900"></div>}
                                                        </div>
                                                        <div className="flex flex-col overflow-hidden">
                                                            <span className={`text-xs font-medium truncate ${isSelected ? 'text-indigo-200' : 'text-zinc-300'}`}>{emp.name}</span>
                                                            <span className="text-[10px] text-zinc-500 truncate">{emp.branch}</span>
                                                        </div>
                                                    </div>
                                                )
                                            })}
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="space-y-1.5">
                                <label className="text-xs font-medium text-zinc-400">{t('cal.description')}</label>
                                <textarea value={newEventForm.description} onChange={e => setNewEventForm({...newEventForm, description: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-sm text-white focus:border-indigo-500 outline-none h-20 resize-none" placeholder="..."></textarea>
                            </div>

                            <div className="pt-6 border-t border-zinc-800/50 space-y-3">
                                 <button 
                                    type="submit" 
                                    disabled={isSaving} 
                                    className={`w-full py-4 text-white font-bold rounded-2xl shadow-xl flex items-center justify-center gap-3 active:scale-95 transition-all ${
                                        newEventForm.type === 'Şube Transferi' 
                                        ? 'bg-gradient-to-r from-orange-600 to-red-600 hover:from-orange-500 hover:to-red-500 shadow-orange-900/20' 
                                        : 'bg-indigo-600 hover:bg-indigo-500 shadow-indigo-900/20'
                                    }`}
                                >
                                    {isSaving ? <Loader2 className="animate-spin" size={24}/> : (newEventForm.type === 'Şube Transferi' ? <Rocket size={24}/> : <Save size={24} />)} 
                                    <span className="text-base">{isSaving ? '...' : (newEventForm.type === 'Şube Transferi' ? t('cal.confirmTransfer') : t('cal.saveEvent'))}</span>
                                </button>
                                <button type="button" onClick={() => setShowAddModal(false)} className="w-full py-3 bg-zinc-900 text-zinc-400 font-medium rounded-xl hover:bg-zinc-800 transition-colors">{t('tasks.cancel')}</button>
                            </div>

                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* --- LEFT / MAIN PANEL: WEEKLY SWIMLANES --- */}
        <div className="flex-1 flex flex-col h-full overflow-hidden p-2 md:p-6 items-center justify-center">

            <div className="w-full h-full flex flex-col">
                <header className="mb-6 flex flex-wrap justify-between items-center w-full shrink-0 px-2 gap-4">
                    <div className="flex items-center gap-4">
                        <div className="p-2.5 bg-zinc-900 rounded-xl border border-zinc-800 shadow-lg">
                            <CalendarRange size={24} className="text-indigo-500"/>
                        </div>
                        <div>
                            <h2 className="text-xl md:text-2xl font-bold text-white tracking-tight">
                                {weekRangeString}
                            </h2>
                            <p className="text-xs text-zinc-500">Haftalık Planlama</p>
                        </div>
                    </div>

                    <div className="flex items-center gap-2">
                        <div className="flex bg-zinc-900 rounded-lg p-1 border border-zinc-800">
                            <button onClick={handlePrevWeek} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="Önceki Hafta">
                                <ChevronLeft size={18} />
                            </button>
                            <div className="w-px bg-zinc-800 my-1 mx-1"></div>
                            <button onClick={handleNextWeek} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors" title="Sonraki Hafta">
                                <ChevronRight size={18} />
                            </button>
                        </div>

                        {currentUser.role === Role.ADMIN && (
                            <button onClick={() => setShowAddModal(true)} className="p-2 md:px-4 md:py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-bold hover:bg-indigo-500 transition-all flex items-center gap-2 shadow-lg shadow-indigo-900/20 active:scale-95">
                                <Plus size={18} /> <span className="hidden md:inline">{t('cal.newEvent')}</span>
                            </button>
                        )}
                    </div>
                </header>

                {/* WEEKLY COLUMN VIEW */}
                <div className="flex-1 min-h-0 bg-black/20 rounded-2xl border border-zinc-800 overflow-x-auto custom-scrollbar">
                    <div className="h-full min-w-[800px] grid grid-cols-7 divide-x divide-zinc-800/50">
                        {weekDays.map(day => {
                            const dateStr = day.toISOString().split('T')[0];
                            const isCurrentDay = isToday(day);

                            // Filter events for this day
                            const dayEvents = combinedEvents.filter(e => {
                                if (!e.isTask && e.endDate) return dateStr >= e.date && dateStr <= e.endDate;
                                return e.date === dateStr;
                            }).sort((a,b) => a.startTime.localeCompare(b.startTime));

                            return (
                                <div key={dateStr} className={`flex flex-col h-full relative group transition-colors ${isCurrentDay ? 'bg-indigo-900/5' : 'hover:bg-zinc-900/20'}`}>
                                    {/* Column Header */}
                                    <div className={`p-3 text-center border-b border-zinc-800 ${isCurrentDay ? 'bg-indigo-500/10 border-b-indigo-500/30' : 'bg-zinc-900/30'}`}>
                                        <span className={`block text-[10px] font-bold uppercase tracking-wider mb-1 ${isCurrentDay ? 'text-indigo-400' : 'text-zinc-500'}`}>
                                            {formatDate(day, {weekday: 'short'})}
                                        </span>
                                        <div className={`inline-flex items-center justify-center w-8 h-8 rounded-full text-sm font-bold transition-all ${isCurrentDay ? 'bg-indigo-500 text-white shadow-lg shadow-indigo-500/40 scale-110' : 'text-zinc-300 group-hover:bg-zinc-800'}`}>
                                            {day.getDate()}
                                        </div>
                                    </div>

                                    {/* Events Container */}
                                    <div className="flex-1 p-2 space-y-2 overflow-y-auto custom-scrollbar relative">
                                        {/* Today Indicator Line (if applicable) */}
                                        {isCurrentDay && (
                                            <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-indigo-500/50 to-transparent pointer-events-none"></div>
                                        )}

                                        {dayEvents.map(evt => (
                                            <div 
                                                key={evt.id}
                                                onClick={(e) => { e.stopPropagation(); setSelectedEvent(evt); }}
                                                className={`p-2.5 rounded-xl border cursor-pointer transition-all hover:scale-[1.02] active:scale-95 shadow-sm group/card ${getTypeColor(evt.type, evt.isTask)} ${selectedEvent?.id === evt.id ? 'ring-1 ring-white shadow-xl scale-[1.02]' : ''}`}
                                            >
                                                <div className="flex items-center justify-between mb-1.5">
                                                    <span className="text-[9px] font-bold opacity-80 bg-black/20 px-1.5 py-0.5 rounded">
                                                        {evt.isTask ? 'GÖREV' : evt.startTime}
                                                    </span>
                                                    {evt.type === 'Şube Transferi' && <Rocket size={10} className="text-orange-300 animate-pulse"/>}
                                                </div>
                                                <h4 className="text-[11px] font-bold leading-tight line-clamp-2 mb-1">
                                                    {getText(evt.title)}
                                                </h4>
                                                {!evt.isTask && (
                                                    <div className="flex items-center gap-1 text-[9px] opacity-70 truncate">
                                                        <Users size={8} />
                                                        <span>{evt.attendees.length} Kişi</span>
                                                    </div>
                                                )}
                                            </div>
                                        ))}

                                        {dayEvents.length === 0 && (
                                            <div className="h-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button 
                                                    onClick={() => { setNewEventForm(prev => ({...prev, date: dateStr, endDate: dateStr})); setShowAddModal(true); }}
                                                    className="p-2 rounded-full bg-zinc-800 text-zinc-500 hover:text-white hover:bg-zinc-700"
                                                >
                                                    <Plus size={16} />
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )
                        })}
                    </div>
                </div>
            </div>
        </div>

        {/* --- RIGHT PANEL: DETAILS --- */}
        {selectedEvent && (
            <div className="fixed md:static inset-0 z-[200] md:z-auto bg-zinc-950 md:bg-transparent flex md:block flex-col md:flex-row">
                <div className="w-full md:w-[400px] border-l border-zinc-800 bg-zinc-950 flex flex-col h-full md:h-full animate-in slide-in-from-bottom-10 md:slide-in-from-right-10 duration-200 shadow-2xl">
                    {/* Panel Header */}
                    <div className="p-6 border-b border-zinc-800 bg-zinc-900/20 flex justify-between items-start">
                        <div>
                            <span className={`inline-block px-2.5 py-0.5 rounded text-[10px] font-medium border mb-3 ${getBadgeColor(selectedEvent.type, selectedEvent.isTask)}`}>
                                {selectedEvent.isTask ? 'Atanan Görev' : getTypeName(selectedEvent.type)}
                            </span>
                            <h2 className="text-xl font-bold text-white leading-tight">{getText(selectedEvent.title)}</h2>
                            {selectedEvent.isTask && (
                                <div className="mt-2 text-xs text-zinc-400">
                                    Durum: <span className="uppercase font-bold text-white">{selectedEvent.status}</span>
                                </div>
                            )}
                        </div>
                        <button onClick={() => setSelectedEvent(null)} className="p-2 bg-zinc-900 rounded-lg text-zinc-500 hover:text-white transition-colors border border-zinc-800">
                            <X size={20} />
                        </button>
                    </div>

                    {/* Panel Content */}
                    <div className="flex-1 overflow-y-auto p-6 space-y-8">
                        {/* Date & Time */}
                        <div className="space-y-4">
                            <div className="flex items-center gap-3 text-zinc-300">
                                <div className="p-2 bg-zinc-900 rounded-lg border border-zinc-800"><CalendarIcon size={18} /></div>
                                <div>
                                    <p className="text-xs text-zinc-500">{selectedEvent.isTask ? t('tasks.dueDate') : t('cal.startDate')}</p>
                                    <p className="text-sm font-medium">
                                        {formatDate(selectedEvent.date, { day: 'numeric', month: 'long', year: 'numeric' })}
                                        {!selectedEvent.isTask && selectedEvent.endDate && selectedEvent.endDate !== selectedEvent.date ? ` - ${formatDate(selectedEvent.endDate, { day: 'numeric', month: 'long', year: 'numeric' })}` : ''}
                                    </p>
                                </div>
                            </div>
                            {!selectedEvent.isTask && (
                                <div className="flex items-center gap-3 text-zinc-300">
                                    <div className="p-2 bg-zinc-900 rounded-lg border border-zinc-800"><Clock size={18} /></div>
                                    <div>
                                        <p className="text-xs text-zinc-500">{t('cal.startTime')}</p>
                                        <p className="text-sm font-medium">{selectedEvent.startTime} - {selectedEvent.endTime}</p>
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* Description */}
                        <div>
                            <h4 className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-3 flex items-center gap-2">
                                <AlignLeft size={14} /> {t('cal.description')}
                            </h4>
                            <div className="p-4 bg-zinc-900/50 border border-zinc-800 rounded-xl">
                                <p className="text-sm text-zinc-300 leading-relaxed">
                                    {getText(selectedEvent.description) || '...'}
                                </p>
                            </div>
                        </div>

                        {/* Attendees */}
                        <div>
                            <h4 className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-3 flex items-center gap-2">
                                <Users size={14} /> {selectedEvent.isTask ? 'Sorumlu Personel' : `${t('cal.attendees')} (${selectedEvent.attendees.length})`}
                            </h4>
                            <div className="space-y-2">
                                {selectedEvent.attendees.length > 0 ? (
                                    selectedEvent.attendees.map(empId => {
                                        const emp = MOCK_EMPLOYEES.find(e => e.id === empId);
                                        return emp ? (
                                            <div key={empId} className="flex items-center gap-3 p-2 rounded-lg hover:bg-zinc-900/50 transition-colors border border-transparent hover:border-zinc-800">
                                                <img src={emp.avatarUrl} alt={emp.name} className="w-8 h-8 rounded-full border border-zinc-800" />
                                                <div>
                                                    <p className="text-sm font-medium text-zinc-200">{emp.name}</p>
                                                    <p className="text-[10px] text-zinc-500">{emp.branch} • {emp.role}</p>
                                                </div>
                                            </div>
                                        ) : null;
                                    })
                                ) : (
                                    <p className="text-sm text-zinc-600 italic">--</p>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Footer Actions */}
                    <div className="p-4 border-t border-zinc-800 bg-zinc-900/20 pb-safe">
                        {selectedEvent.isTask ? (
                            <div className="text-center text-xs text-zinc-500">
                                {language === 'de' ? 'Aufgaben können hier nicht gelöscht werden.' : 'Görevler takvimden silinemez.'}
                            </div>
                        ) : (
                            <button 
                                onClick={handleDeleteEvent}
                                className="w-full flex items-center justify-center gap-2 py-3 border border-red-900/30 text-red-400 hover:bg-red-900/10 rounded-xl text-sm font-medium transition-colors"
                            >
                                <Trash2 size={16} /> {t('cal.deleteEvent')}
                            </button>
                        )}
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

export default Calendar;

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_EMPLOYEES } from '../constants';
import { Branch, Employee, Role, CalendarEvent, Task } from '../types';
import { Plus, X, Calendar as CalendarIcon, Clock, MapPin, Users, Save, Building2, CheckCircle2, AlignLeft, Trash2, ChevronLeft, ChevronRight, AlertTriangle, CheckSquare, Loader2, Rocket, ArrowRightLeft, CalendarRange, MoreHorizontal } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';

interface CalendarProps {
    currentUser: Employee;
}

interface DisplayEvent extends CalendarEvent {
    isTask?: boolean;
    status?: string;
}

const Calendar: React.FC<CalendarProps> = ({ currentUser }) => {
  // --- STATE ---
  const [currentMonth, setCurrentMonth] = useState(new Date()); // Ay gezintisi için
  const [selectedDate, setSelectedDate] = useState(new Date()); // Seçili gün

  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const { t, formatDate, language } = useLanguage();

  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);

  // Modal & Selection
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<DisplayEvent | null>(null);
  const [selectedBranches, setSelectedBranches] = useState<Branch[]>([]);
  const [targetBranch, setTargetBranch] = useState<Branch>(Branch.DOM);

  // Form
  const [newEventForm, setNewEventForm] = useState<Partial<CalendarEvent>>({
      title: '',
      type: 'Toplantı',
      date: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0], 
      startTime: '09:00',
      endTime: '10:00',
      attendees: [],
      description: ''
  });

  // --- DATA FETCHING ---
  useEffect(() => {
    const fetchData = async () => {
        setIsLoading(true);
        try {
            // Events
            let eventQuery = supabase.from('calendar_events').select('*');
            if (currentUser.role !== Role.ADMIN) {
                eventQuery = eventQuery.contains('attendees', [currentUser.id]);
            }
            const { data: eventData } = await eventQuery;
            if (eventData) {
                const dbEvents: CalendarEvent[] = eventData.map((e: any) => ({
                    id: e.id, title: e.title, type: e.type, date: e.date,
                    endDate: e.end_date || e.date, startTime: e.start_time, endTime: e.end_time,
                    attendees: e.attendees || [], description: e.description
                }));
                setEvents(dbEvents);
            }

            // Tasks
            let taskQuery = supabase.from('tasks').select('*');
            if (currentUser.role !== Role.ADMIN) {
                taskQuery = taskQuery.contains('assigned_to', [currentUser.id]);
            }
            const { data: taskData } = await taskQuery;
            if(taskData) {
                 const dbTasks: Task[] = taskData.map((t: any) => ({
                    id: t.id, title: t.title, description: t.description,
                    assignedTo: t.assigned_to || [], dueDate: t.due_date,
                    priority: t.priority, status: t.status, progress: t.progress, checklist: t.checklist || []
                }));
                setTasks(dbTasks);
            }
        } catch (e) {
            console.log("Error:", e);
        } finally {
            setIsLoading(false);
        }
    };
    fetchData();
  }, [currentUser]); 

  // --- LOGIC ---
  const combinedEvents = useMemo((): DisplayEvent[] => {
      const filteredEvents = currentUser.role === Role.ADMIN ? events : events.filter(evt => evt.attendees.includes(currentUser.id));
      const filteredTasks = currentUser.role === Role.ADMIN ? tasks : tasks.filter(t => t.assignedTo.includes(currentUser.id));

      const taskEvents: DisplayEvent[] = filteredTasks.map(t => ({
          id: t.id, title: t.title, type: 'Diğer', date: t.dueDate, endDate: t.dueDate,
          startTime: '09:00', endTime: '18:00', attendees: t.assignedTo, description: t.description,
          isTask: true, status: t.status
      }));

      return [...(filteredEvents as DisplayEvent[]), ...taskEvents];
  }, [events, tasks, currentUser]);

  // Mini Calendar Logic
  const getDaysInMonth = (date: Date) => {
      const year = date.getFullYear();
      const month = date.getMonth();
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);
      const days = [];

      // Empty slots for start of week (Monday start)
      let startDay = firstDay.getDay(); // 0=Sun
      if (startDay === 0) startDay = 7; // Make Sun=7
      for (let i = 1; i < startDay; i++) {
          days.push(null);
      }

      for (let i = 1; i <= lastDay.getDate(); i++) {
          days.push(new Date(year, month, i));
      }
      return days;
  };

  const daysInMonth = useMemo(() => getDaysInMonth(currentMonth), [currentMonth]);

  const changeMonth = (delta: number) => {
      const newDate = new Date(currentMonth);
      newDate.setMonth(newDate.getMonth() + delta);
      setCurrentMonth(newDate);
  };

  const isSameDay = (d1: Date, d2: Date) => {
      return d1.getDate() === d2.getDate() && d1.getMonth() === d2.getMonth() && d1.getFullYear() === d2.getFullYear();
  };

  const getText = (text?: string) => {
    if (!text) return '';
    return text.startsWith('task.mock') ? t(text) : text;
  };

  // Filter events for SELECTED DATE
  const dailyEvents = useMemo(() => {
      const targetStr = selectedDate.toISOString().split('T')[0];
      return combinedEvents.filter(e => {
          if (!e.isTask && e.endDate) return targetStr >= e.date && targetStr <= e.endDate;
          return e.date === targetStr;
      }).sort((a,b) => a.startTime.localeCompare(b.startTime));
  }, [selectedDate, combinedEvents]);

  // Handlers
  const handleSaveEvent = async (e: React.FormEvent) => {
      e.preventDefault();
      // ... (Same logic as before, just compact)
      const isTransfer = newEventForm.type === 'Şube Transferi';
      if (!newEventForm.title && !isTransfer) return alert(t('cal.warnTitle'));

      setIsSaving(true);
      try {
          const finalTitle = isTransfer ? `${newEventForm.attendees?.length} Personel -> ${targetBranch}` : newEventForm.title!;
          const dbPayload = {
              title: finalTitle, type: newEventForm.type, date: newEventForm.date,
              end_date: newEventForm.endDate || newEventForm.date, start_time: newEventForm.startTime,
              end_time: newEventForm.endTime, attendees: newEventForm.attendees || [], description: newEventForm.description
          };
          const { data, error } = await supabase.from('calendar_events').insert([dbPayload]).select();
          if (error) throw error;

          if(isTransfer && currentUser.role === Role.ADMIN) {
               await supabase.from('profiles').update({ branch: targetBranch }).in('id', newEventForm.attendees || []);
          }

          if (data) {
              setEvents(prev => [...prev, { ...data[0], attendees: data[0].attendees || [] } as CalendarEvent]);
              setShowAddModal(false);
              alert(t('common.success'));
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const handleDeleteEvent = async () => {
      if (!selectedEvent || selectedEvent.isTask) return;
      if (confirm('Silmek istediğinize emin misiniz?')) {
          const { error } = await supabase.from('calendar_events').delete().eq('id', selectedEvent.id);
          if (!error) {
              setEvents(events.filter(e => e.id !== selectedEvent.id));
              setSelectedEvent(null);
          }
      }
  };

  const toggleBranchSelection = (branch: Branch) => {
    setSelectedBranches(prev => prev.includes(branch) ? prev.filter(b => b !== branch) : [...prev, branch]);
  };

  const toggleAttendee = (id: string) => {
    setNewEventForm(prev => {
        const cur = prev.attendees || [];
        return cur.includes(id) ? { ...prev, attendees: cur.filter(x => x !== id) } : { ...prev, attendees: [...cur, id] };
    });
  };

  return (
    <div className="flex h-full relative overflow-hidden bg-zinc-950">

        {/* ADD EVENT MODAL (UNCHANGED LOGIC, JUST RE-INSERTED) */}
        {showAddModal && (
            <div className="fixed inset-0 z-[100] flex justify-center items-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in">
                <div className="bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
                    <div className="p-5 border-b border-zinc-800 flex justify-between items-center">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            {newEventForm.type === 'Şube Transferi' ? <Rocket size={20} className="text-orange-500"/> : <CalendarIcon size={20} className="text-indigo-500"/>}
                            {t('cal.newEvent')}
                        </h3>
                        <button onClick={() => setShowAddModal(false)}><X size={20} className="text-zinc-500 hover:text-white"/></button>
                    </div>
                    <div className="p-6 overflow-y-auto custom-scrollbar flex-1">
                        <form onSubmit={handleSaveEvent} className="space-y-5">
                            {/* Type */}
                            <div>
                                <label className="text-xs text-zinc-400 block mb-1.5">{t('cal.type')}</label>
                                <div className="flex gap-2 overflow-x-auto pb-1">
                                    {['Toplantı', 'Montaj', 'Teslim Tarihi', 'Şube Transferi', 'Diğer'].map(type => (
                                        <button key={type} type="button" onClick={() => setNewEventForm({...newEventForm, type: type as any})}
                                            className={`px-3 py-1.5 rounded-lg text-xs font-medium border whitespace-nowrap transition-all ${newEventForm.type === type ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800'}`}>
                                            {type === 'Şube Transferi' ? t('cal.type.transfer') : type}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Title (If not transfer) */}
                            {newEventForm.type !== 'Şube Transferi' && (
                                <div>
                                    <label className="text-xs text-zinc-400 block mb-1.5">{t('cal.eventTitle')}</label>
                                    <input type="text" required value={newEventForm.title} onChange={e => setNewEventForm({...newEventForm, title: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-white focus:border-indigo-500 outline-none" />
                                </div>
                            )}

                            {/* Transfer Logic */}
                            {newEventForm.type === 'Şube Transferi' && (
                                <div className="p-3 bg-orange-950/20 border border-orange-500/20 rounded-lg">
                                    <label className="text-xs font-bold text-orange-400 block mb-2">{t('cal.targetBranch')}</label>
                                    <div className="flex flex-wrap gap-2">
                                        {Object.values(Branch).map(branch => (
                                            <button key={branch} type="button" onClick={() => setTargetBranch(branch)} className={`px-2 py-1 text-xs rounded border ${targetBranch === branch ? 'bg-orange-600 text-white border-orange-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800'}`}>{branch}</button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Dates */}
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="text-xs text-zinc-400 block mb-1.5">{t('cal.startDate')}</label><input type="date" value={newEventForm.date} onChange={e => setNewEventForm({...newEventForm, date: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-white text-sm"/></div>
                                <div><label className="text-xs text-zinc-400 block mb-1.5">{t('cal.startTime')}</label><input type="time" value={newEventForm.startTime} onChange={e => setNewEventForm({...newEventForm, startTime: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-white text-sm"/></div>
                            </div>

                            {/* Attendees Selector */}
                            <div className="p-4 bg-zinc-950/50 border border-zinc-800 rounded-xl space-y-3">
                                <label className="text-xs font-medium text-zinc-400 block">{t('cal.branchFilter')}</label>
                                <div className="flex gap-2 flex-wrap">
                                    {Object.values(Branch).map(b => (
                                        <button key={b} type="button" onClick={() => toggleBranchSelection(b)} className={`px-2 py-1 text-[10px] rounded border ${selectedBranches.includes(b) ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-500 border-zinc-800'}`}>{b}</button>
                                    ))}
                                </div>
                                <div className="h-px bg-zinc-800"></div>
                                <label className="text-xs font-medium text-zinc-400 block">{t('cal.attendees')}</label>
                                <div className="flex gap-2 overflow-x-auto pb-1">
                                    {MOCK_EMPLOYEES.filter(e => selectedBranches.length === 0 || selectedBranches.includes(e.branch)).map(emp => (
                                        <div key={emp.id} onClick={() => toggleAttendee(emp.id)} className={`cursor-pointer flex flex-col items-center gap-1 min-w-[50px] p-2 rounded-lg border transition-all ${newEventForm.attendees?.includes(emp.id) ? 'bg-indigo-500/20 border-indigo-500' : 'bg-zinc-900 border-zinc-800'}`}>
                                            <img src={emp.avatarUrl} className="w-8 h-8 rounded-full"/>
                                            <span className="text-[9px] text-zinc-400 truncate w-full text-center">{emp.name.split(' ')[0]}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Footer */}
                            <div className="pt-4 flex gap-3">
                                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-3 bg-zinc-800 text-zinc-400 rounded-xl text-sm">{t('tasks.cancel')}</button>
                                <button type="submit" disabled={isSaving} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg">
                                    {isSaving ? '...' : t('cal.saveEvent')}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* --- MAIN LAYOUT (2 PANELS) --- */}
        <div className="flex-1 flex flex-col lg:flex-row h-full overflow-hidden">

            {/* LEFT PANEL: MINI CALENDAR & STATS */}
            <div className="w-full lg:w-[320px] bg-zinc-900/30 border-b lg:border-b-0 lg:border-r border-zinc-800 flex flex-col p-6 overflow-y-auto">
                {/* Header */}
                <div className="flex items-center justify-between mb-8">
                    <h2 className="text-xl font-bold text-white tracking-tight">{t('nav.calendar')}</h2>
                    {currentUser.role === Role.ADMIN && (
                        <button onClick={() => { setNewEventForm(p => ({...p, date: selectedDate.toISOString().split('T')[0]})); setShowAddModal(true); }} className="w-8 h-8 flex items-center justify-center bg-indigo-600 rounded-full text-white hover:bg-indigo-500 shadow-lg transition-transform active:scale-95">
                            <Plus size={18} />
                        </button>
                    )}
                </div>

                {/* Mini Calendar */}
                <div className="mb-8">
                    <div className="flex items-center justify-between mb-4 px-1">
                        <button onClick={() => changeMonth(-1)} className="p-1 hover:bg-zinc-800 rounded text-zinc-400"><ChevronLeft size={16}/></button>
                        <span className="text-sm font-bold text-zinc-200">{formatDate(currentMonth, {month: 'long', year: 'numeric'})}</span>
                        <button onClick={() => changeMonth(1)} className="p-1 hover:bg-zinc-800 rounded text-zinc-400"><ChevronRight size={16}/></button>
                    </div>
                    <div className="grid grid-cols-7 gap-1 text-center mb-2">
                        {['Pt','Sa','Ça','Pe','Cu','Ct','Pa'].map(d => <span key={d} className="text-[10px] font-bold text-zinc-500 uppercase">{d}</span>)}
                    </div>
                    <div className="grid grid-cols-7 gap-1">
                        {daysInMonth.map((day, idx) => {
                            if (!day) return <div key={`empty-${idx}`} className="h-8"></div>;
                            const isSelected = isSameDay(day, selectedDate);
                            const isTodayDate = isSameDay(day, new Date());
                            // Check for events
                            const dayStr = day.toISOString().split('T')[0];
                            const hasEvents = combinedEvents.some(e => e.date === dayStr || (e.endDate && dayStr >= e.date && dayStr <= e.endDate));

                            return (
                                <button 
                                    key={dayStr}
                                    onClick={() => setSelectedDate(day)}
                                    className={`h-8 w-8 mx-auto flex items-center justify-center rounded-full text-xs transition-all relative
                                        ${isSelected ? 'bg-indigo-600 text-white shadow-lg font-bold' : 'text-zinc-400 hover:bg-zinc-800 hover:text-white'}
                                        ${isTodayDate && !isSelected ? 'text-indigo-400 font-bold border border-indigo-500/30' : ''}
                                    `}
                                >
                                    {day.getDate()}
                                    {hasEvents && !isSelected && <div className="absolute bottom-1 w-1 h-1 rounded-full bg-indigo-500"></div>}
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* Info / Legend */}
                <div className="flex-1">
                    <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-wider mb-4">Özet</h3>
                    <div className="space-y-3">
                        <div className="flex items-center gap-3 p-3 bg-zinc-900 rounded-xl border border-zinc-800/50">
                            <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
                            <div className="flex-1 text-xs text-zinc-300">Toplantı</div>
                            <span className="text-xs font-bold text-zinc-500">{events.filter(e => e.type === 'Toplantı').length}</span>
                        </div>
                        <div className="flex items-center gap-3 p-3 bg-zinc-900 rounded-xl border border-zinc-800/50">
                            <div className="w-2 h-2 rounded-full bg-orange-500"></div>
                            <div className="flex-1 text-xs text-zinc-300">Transfer</div>
                            <span className="text-xs font-bold text-zinc-500">{events.filter(e => e.type === 'Şube Transferi').length}</span>
                        </div>
                        <div className="flex items-center gap-3 p-3 bg-zinc-900 rounded-xl border border-zinc-800/50">
                            <div className="w-2 h-2 rounded-full bg-blue-500"></div>
                            <div className="flex-1 text-xs text-zinc-300">Görev</div>
                            <span className="text-xs font-bold text-zinc-500">{tasks.length}</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* RIGHT PANEL: AGENDA / TIMELINE */}
            <div className="flex-1 bg-zinc-950 flex flex-col h-full overflow-hidden relative">
                {/* Decorative BG */}
                <div className="absolute top-0 right-0 w-[400px] h-[400px] bg-indigo-900/5 rounded-full blur-[100px] pointer-events-none"></div>

                {/* Header for Selected Day */}
                <div className="p-6 md:p-8 flex items-end gap-4 shrink-0 relative z-10">
                    <div className="w-16 h-16 rounded-2xl bg-zinc-900 border border-zinc-800 flex flex-col items-center justify-center shadow-xl">
                        <span className="text-xs font-bold text-zinc-500 uppercase">{formatDate(selectedDate, {weekday: 'short'})}</span>
                        <span className="text-2xl font-bold text-white">{selectedDate.getDate()}</span>
                    </div>
                    <div className="flex-1 pb-1">
                        <h1 className="text-2xl font-bold text-white tracking-tight">
                            {isSameDay(selectedDate, new Date()) ? t('dash.welcome') : formatDate(selectedDate, { day: 'numeric', month: 'long' })}
                        </h1>
                        <p className="text-sm text-zinc-500">
                            {dailyEvents.length} Etkinlik Planlandı
                        </p>
                    </div>
                </div>

                {/* Timeline Content */}
                <div className="flex-1 overflow-y-auto px-6 md:px-8 pb-10 custom-scrollbar relative z-10">
                    {dailyEvents.length === 0 ? (
                        <div className="h-full flex flex-col items-center justify-center text-zinc-600 space-y-4 opacity-60">
                            <div className="w-16 h-16 rounded-full bg-zinc-900 border border-zinc-800 flex items-center justify-center">
                                <CalendarIcon size={24} />
                            </div>
                            <p className="text-sm">Bugün için planlanmış etkinlik yok.</p>
                            {currentUser.role === Role.ADMIN && (
                                <button onClick={() => { setNewEventForm(p => ({...p, date: selectedDate.toISOString().split('T')[0]})); setShowAddModal(true); }} className="text-indigo-400 text-xs font-bold hover:underline">
                                    + Etkinlik Ekle
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className="space-y-6 relative ml-4">
                            {/* Vertical Line */}
                            <div className="absolute top-2 bottom-2 left-[7px] w-px bg-zinc-800"></div>

                            {dailyEvents.map((evt, idx) => (
                                <div key={evt.id} 
                                     onClick={() => setSelectedEvent(evt)}
                                     className="relative pl-8 group cursor-pointer"
                                >
                                    {/* Timeline Dot */}
                                    <div className={`absolute left-0 top-1.5 w-4 h-4 rounded-full border-2 border-zinc-950 z-10 transition-colors 
                                        ${evt.isTask ? 'bg-blue-500' : evt.type === 'Şube Transferi' ? 'bg-orange-500' : 'bg-indigo-500'}
                                        group-hover:scale-125
                                    `}></div>

                                    {/* Time Label */}
                                    <div className="absolute -left-16 top-1 text-right w-12">
                                        <span className="text-xs font-mono text-zinc-500 group-hover:text-white transition-colors">{evt.startTime}</span>
                                    </div>

                                    {/* Card */}
                                    <div className="bg-zinc-900/50 border border-zinc-800/60 rounded-xl p-4 transition-all hover:bg-zinc-900 hover:border-zinc-700 hover:shadow-lg hover:translate-x-1">
                                        <div className="flex justify-between items-start mb-2">
                                            <div>
                                                <span className={`inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase mb-1.5
                                                    ${evt.isTask ? 'bg-blue-900/20 text-blue-400' : evt.type === 'Şube Transferi' ? 'bg-orange-900/20 text-orange-400' : 'bg-indigo-900/20 text-indigo-400'}
                                                `}>
                                                    {evt.isTask ? 'GÖREV' : evt.type}
                                                </span>
                                                <h3 className="text-base font-bold text-zinc-200 group-hover:text-white transition-colors">
                                                    {getText(evt.title)}
                                                </h3>
                                            </div>
                                            {/* Avatars */}
                                            <div className="flex -space-x-2">
                                                {evt.attendees.slice(0,3).map(id => {
                                                    const emp = MOCK_EMPLOYEES.find(e => e.id === id);
                                                    return emp ? <img key={id} src={emp.avatarUrl} className="w-6 h-6 rounded-full border border-zinc-900" /> : null;
                                                })}
                                            </div>
                                        </div>

                                        <div className="flex items-center gap-4 text-xs text-zinc-500">
                                            <span className="flex items-center gap-1"><Clock size={12}/> {evt.endTime}</span>
                                            {evt.description && <span className="flex items-center gap-1 max-w-[200px] truncate"><AlignLeft size={12}/> {getText(evt.description)}</span>}
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </div>

        {/* --- DETAIL PANEL (SLIDE OVER) --- */}
        {selectedEvent && (
            <div className="fixed inset-0 z-[200] flex justify-end bg-black/50 backdrop-blur-sm animate-in fade-in" onClick={() => setSelectedEvent(null)}>
                <div className="w-full md:w-[400px] h-full bg-zinc-950 border-l border-zinc-800 p-6 flex flex-col shadow-2xl animate-in slide-in-from-right duration-300" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-start mb-8">
                        <div>
                            <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest">{selectedEvent.isTask ? 'Görev Detayı' : 'Etkinlik Detayı'}</span>
                            <h2 className="text-2xl font-bold text-white mt-2 leading-tight">{getText(selectedEvent.title)}</h2>
                        </div>
                        <button onClick={() => setSelectedEvent(null)} className="p-2 bg-zinc-900 rounded-lg text-zinc-400 hover:text-white"><X size={20}/></button>
                    </div>

                    <div className="space-y-6 flex-1 overflow-y-auto">
                        <div className="flex items-center gap-4 text-zinc-300">
                            <div className="w-10 h-10 rounded-lg bg-zinc-900 flex items-center justify-center border border-zinc-800"><CalendarIcon size={20}/></div>
                            <div>
                                <p className="text-xs text-zinc-500">Tarih</p>
                                <p className="font-medium">{formatDate(selectedEvent.date, {day:'numeric', month:'long', year: 'numeric'})}</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-4 text-zinc-300">
                            <div className="w-10 h-10 rounded-lg bg-zinc-900 flex items-center justify-center border border-zinc-800"><Clock size={20}/></div>
                            <div>
                                <p className="text-xs text-zinc-500">Saat</p>
                                <p className="font-medium">{selectedEvent.startTime} - {selectedEvent.endTime}</p>
                            </div>
                        </div>

                        <div className="p-4 bg-zinc-900/50 rounded-xl border border-zinc-800">
                            <h4 className="text-xs font-bold text-zinc-500 uppercase mb-2">Açıklama</h4>
                            <p className="text-sm text-zinc-300 leading-relaxed">{getText(selectedEvent.description) || 'Açıklama yok.'}</p>
                        </div>

                        <div>
                            <h4 className="text-xs font-bold text-zinc-500 uppercase mb-3">Katılımcılar ({selectedEvent.attendees.length})</h4>
                            <div className="space-y-2">
                                {selectedEvent.attendees.map(id => {
                                    const emp = MOCK_EMPLOYEES.find(e => e.id === id);
                                    return emp ? (
                                        <div key={id} className="flex items-center gap-3 p-2 rounded-lg bg-zinc-900/30 border border-zinc-800/50">
                                            <img src={emp.avatarUrl} className="w-8 h-8 rounded-full"/>
                                            <div>
                                                <p className="text-sm font-bold text-zinc-200">{emp.name}</p>
                                                <p className="text-[10px] text-zinc-500">{emp.branch}</p>
                                            </div>
                                        </div>
                                    ) : null;
                                })}
                            </div>
                        </div>
                    </div>

                    {!selectedEvent.isTask && (
                        <div className="pt-6 border-t border-zinc-800">
                            <button onClick={handleDeleteEvent} className="w-full py-3 bg-red-900/20 text-red-400 border border-red-900/30 rounded-xl text-sm font-bold hover:bg-red-900/40 transition-colors flex items-center justify-center gap-2">
                                <Trash2 size={16}/> {t('cal.deleteEvent')}
                            </button>
                        </div>
                    )}
                </div>
            </div>
        )}
    </div>
  );
};

export default Calendar;

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_EMPLOYEES } from '../constants';
import { Branch, Employee, Role, CalendarEvent, Task } from '../types';
import { Plus, X, Calendar as CalendarIcon, Clock, MapPin, Users, Save, Building2, CheckCircle2, AlignLeft, Trash2, ChevronLeft, ChevronRight, AlertTriangle, CheckSquare, Loader2, Rocket, ArrowRightLeft, CalendarRange, MoreHorizontal, Filter, List } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';

interface CalendarProps {
    currentUser: Employee;
}

interface DisplayEvent extends CalendarEvent {
    isTask?: boolean;
    status?: string;
}

const Calendar: React.FC<CalendarProps> = ({ currentUser }) => {
  // --- STATE ---
  const [viewDate, setViewDate] = useState(new Date()); // Haftanın referans günü

  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const { t, formatDate, language } = useLanguage();

  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);

  // Modal & Selection
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<DisplayEvent | null>(null);

  // Filters
  const [selectedBranches, setSelectedBranches] = useState<Branch[]>([]);
  const [targetBranch, setTargetBranch] = useState<Branch>(Branch.DOM);

  // Form
  const [newEventForm, setNewEventForm] = useState<Partial<CalendarEvent>>({
      title: '',
      type: 'Toplantı',
      date: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0], 
      startTime: '09:00',
      endTime: '10:00',
      attendees: [],
      description: ''
  });

  // --- DATA FETCHING ---
  useEffect(() => {
    const fetchData = async () => {
        setIsLoading(true);
        try {
            // Events
            let eventQuery = supabase.from('calendar_events').select('*');
            if (currentUser.role !== Role.ADMIN) {
                eventQuery = eventQuery.contains('attendees', [currentUser.id]);
            }
            const { data: eventData } = await eventQuery;
            if (eventData) {
                const dbEvents: CalendarEvent[] = eventData.map((e: any) => ({
                    id: e.id, title: e.title, type: e.type, date: e.date,
                    endDate: e.end_date || e.date, startTime: e.start_time, endTime: e.end_time,
                    attendees: e.attendees || [], description: e.description
                }));
                setEvents(dbEvents);
            }

            // Tasks
            let taskQuery = supabase.from('tasks').select('*');
            if (currentUser.role !== Role.ADMIN) {
                taskQuery = taskQuery.contains('assigned_to', [currentUser.id]);
            }
            const { data: taskData } = await taskQuery;
            if(taskData) {
                 const dbTasks: Task[] = taskData.map((t: any) => ({
                    id: t.id, title: t.title, description: t.description,
                    assignedTo: t.assigned_to || [], dueDate: t.due_date,
                    priority: t.priority, status: t.status, progress: t.progress, checklist: t.checklist || []
                }));
                setTasks(dbTasks);
            }
        } catch (e) {
            console.log("Error:", e);
        } finally {
            setIsLoading(false);
        }
    };
    fetchData();
  }, [currentUser]); 

  // --- LOGIC ---
  const combinedEvents = useMemo((): DisplayEvent[] => {
      const filteredEvents = currentUser.role === Role.ADMIN ? events : events.filter(evt => evt.attendees.includes(currentUser.id));
      const filteredTasks = currentUser.role === Role.ADMIN ? tasks : tasks.filter(t => t.assignedTo.includes(currentUser.id));

      const taskEvents: DisplayEvent[] = filteredTasks.map(t => ({
          id: t.id, title: t.title, type: 'Diğer', date: t.dueDate, endDate: t.dueDate,
          startTime: '09:00', endTime: '18:00', attendees: t.assignedTo, description: t.description,
          isTask: true, status: t.status
      }));

      return [...(filteredEvents as DisplayEvent[]), ...taskEvents];
  }, [events, tasks, currentUser]);

  // WEEK LOGIC
  const getStartOfWeek = (d: Date) => {
      const date = new Date(d);
      const day = date.getDay(); 
      const diff = date.getDate() - day + (day === 0 ? -6 : 1); // Adjust when day is Sunday
      return new Date(date.setDate(diff));
  };

  const currentWeekStart = useMemo(() => getStartOfWeek(viewDate), [viewDate]);

  const weekDays = useMemo(() => {
      const days = [];
      for (let i = 0; i < 7; i++) {
          const d = new Date(currentWeekStart);
          d.setDate(d.getDate() + i);
          days.push(d);
      }
      return days;
  }, [currentWeekStart]);

  const changeWeek = (direction: 'prev' | 'next') => {
      const newDate = new Date(viewDate);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setViewDate(newDate);
  };

  const isToday = (d: Date) => {
      const today = new Date();
      return d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
  };

  const getText = (text?: string) => {
    if (!text) return '';
    return text.startsWith('task.mock') ? t(text) : text;
  };

  // Handlers
  const handleSaveEvent = async (e: React.FormEvent) => {
      e.preventDefault();
      const isTransfer = newEventForm.type === 'Şube Transferi';
      if (!newEventForm.title && !isTransfer) return alert(t('cal.warnTitle'));

      setIsSaving(true);
      try {
          const finalTitle = isTransfer ? `${newEventForm.attendees?.length} Personel -> ${targetBranch}` : newEventForm.title!;
          const dbPayload = {
              title: finalTitle, type: newEventForm.type, date: newEventForm.date,
              end_date: newEventForm.endDate || newEventForm.date, start_time: newEventForm.startTime,
              end_time: newEventForm.endTime, attendees: newEventForm.attendees || [], description: newEventForm.description
          };
          const { data, error } = await supabase.from('calendar_events').insert([dbPayload]).select();
          if (error) throw error;

          if(isTransfer && currentUser.role === Role.ADMIN) {
               await supabase.from('profiles').update({ branch: targetBranch }).in('id', newEventForm.attendees || []);
          }

          if (data) {
              setEvents(prev => [...prev, { ...data[0], attendees: data[0].attendees || [] } as CalendarEvent]);
              setShowAddModal(false);
              alert(t('common.success'));
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const handleDeleteEvent = async () => {
      if (!selectedEvent || selectedEvent.isTask) return;
      if (confirm('Silmek istediğinize emin misiniz?')) {
          const { error } = await supabase.from('calendar_events').delete().eq('id', selectedEvent.id);
          if (!error) {
              setEvents(events.filter(e => e.id !== selectedEvent.id));
              setSelectedEvent(null);
          }
      }
  };

  const toggleBranchSelection = (branch: Branch) => {
    setSelectedBranches(prev => prev.includes(branch) ? prev.filter(b => b !== branch) : [...prev, branch]);
  };

  const toggleAttendee = (id: string) => {
    setNewEventForm(prev => {
        const cur = prev.attendees || [];
        return cur.includes(id) ? { ...prev, attendees: cur.filter(x => x !== id) } : { ...prev, attendees: [...cur, id] };
    });
  };

  // --- WEEK STATS ---
  const weekStats = useMemo(() => {
      const startStr = weekDays[0].toISOString().split('T')[0];
      const endStr = weekDays[6].toISOString().split('T')[0];

      const eventsInWeek = combinedEvents.filter(e => e.date >= startStr && e.date <= endStr);

      return {
          total: eventsInWeek.length,
          meetings: eventsInWeek.filter(e => e.type === 'Toplantı').length,
          transfers: eventsInWeek.filter(e => e.type === 'Şube Transferi').length,
          tasks: eventsInWeek.filter(e => e.isTask).length
      };
  }, [combinedEvents, weekDays]);

  return (
    <div className="flex h-full relative overflow-hidden bg-zinc-950">

        {/* ADD EVENT MODAL */}
        {showAddModal && (
            <div className="fixed inset-0 z-[100] flex justify-center items-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in">
                <div className="bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
                    <div className="p-5 border-b border-zinc-800 flex justify-between items-center bg-zinc-950/80 backdrop-blur">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            {newEventForm.type === 'Şube Transferi' ? <Rocket size={20} className="text-orange-500"/> : <CalendarIcon size={20} className="text-indigo-500"/>}
                            {t('cal.newEvent')}
                        </h3>
                        <button onClick={() => setShowAddModal(false)}><X size={20} className="text-zinc-500 hover:text-white"/></button>
                    </div>
                    <div className="p-6 overflow-y-auto custom-scrollbar flex-1">
                        <form onSubmit={handleSaveEvent} className="space-y-5">
                            {/* Type */}
                            <div>
                                <label className="text-xs text-zinc-400 block mb-1.5">{t('cal.type')}</label>
                                <div className="flex gap-2 overflow-x-auto pb-1">
                                    {['Toplantı', 'Montaj', 'Teslim Tarihi', 'Şube Transferi', 'Diğer'].map(type => (
                                        <button key={type} type="button" onClick={() => setNewEventForm({...newEventForm, type: type as any})}
                                            className={`px-3 py-1.5 rounded-lg text-xs font-medium border whitespace-nowrap transition-all ${newEventForm.type === type ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800'}`}>
                                            {type === 'Şube Transferi' ? t('cal.type.transfer') : type}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Title (If not transfer) */}
                            {newEventForm.type !== 'Şube Transferi' && (
                                <div>
                                    <label className="text-xs text-zinc-400 block mb-1.5">{t('cal.eventTitle')}</label>
                                    <input type="text" required value={newEventForm.title} onChange={e => setNewEventForm({...newEventForm, title: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-white focus:border-indigo-500 outline-none" />
                                </div>
                            )}

                            {/* Transfer Logic */}
                            {newEventForm.type === 'Şube Transferi' && (
                                <div className="p-3 bg-orange-950/20 border border-orange-500/20 rounded-lg">
                                    <label className="text-xs font-bold text-orange-400 block mb-2">{t('cal.targetBranch')}</label>
                                    <div className="flex flex-wrap gap-2">
                                        {Object.values(Branch).map(branch => (
                                            <button key={branch} type="button" onClick={() => setTargetBranch(branch)} className={`px-2 py-1 text-xs rounded border ${targetBranch === branch ? 'bg-orange-600 text-white border-orange-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800'}`}>{branch}</button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Dates */}
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="text-xs text-zinc-400 block mb-1.5">{t('cal.startDate')}</label><input type="date" value={newEventForm.date} onChange={e => setNewEventForm({...newEventForm, date: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-white text-sm"/></div>
                                <div><label className="text-xs text-zinc-400 block mb-1.5">{t('cal.startTime')}</label><input type="time" value={newEventForm.startTime} onChange={e => setNewEventForm({...newEventForm, startTime: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-white text-sm"/></div>
                            </div>

                            {/* Attendees Selector */}
                            <div className="p-4 bg-zinc-950/50 border border-zinc-800 rounded-xl space-y-3">
                                <label className="text-xs font-medium text-zinc-400 block">{t('cal.branchFilter')}</label>
                                <div className="flex gap-2 flex-wrap">
                                    {Object.values(Branch).map(b => (
                                        <button key={b} type="button" onClick={() => toggleBranchSelection(b)} className={`px-2 py-1 text-[10px] rounded border ${selectedBranches.includes(b) ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-500 border-zinc-800'}`}>{b}</button>
                                    ))}
                                </div>
                                <div className="h-px bg-zinc-800"></div>
                                <label className="text-xs font-medium text-zinc-400 block">{t('cal.attendees')}</label>
                                <div className="flex gap-2 overflow-x-auto pb-1">
                                    {MOCK_EMPLOYEES.filter(e => selectedBranches.length === 0 || selectedBranches.includes(e.branch)).map(emp => (
                                        <div key={emp.id} onClick={() => toggleAttendee(emp.id)} className={`cursor-pointer flex flex-col items-center gap-1 min-w-[50px] p-2 rounded-lg border transition-all ${newEventForm.attendees?.includes(emp.id) ? 'bg-indigo-500/20 border-indigo-500' : 'bg-zinc-900 border-zinc-800'}`}>
                                            <img src={emp.avatarUrl} className="w-8 h-8 rounded-full"/>
                                            <span className="text-[9px] text-zinc-400 truncate w-full text-center">{emp.name.split(' ')[0]}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Footer */}
                            <div className="pt-4 flex gap-3">
                                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-3 bg-zinc-800 text-zinc-400 rounded-xl text-sm">{t('tasks.cancel')}</button>
                                <button type="submit" disabled={isSaving} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg">
                                    {isSaving ? '...' : t('cal.saveEvent')}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* --- LEFT PANEL: SUMMARY & NAV (HIDDEN ON MOBILE) --- */}
        <div className="w-full md:w-80 bg-zinc-950 border-b md:border-b-0 md:border-r border-zinc-800 flex-col hidden md:flex">
            <div className="p-6 border-b border-zinc-900">
                <h2 className="text-xl font-bold text-white mb-1">Ajanda</h2>
                <p className="text-xs text-zinc-500">Haftalık Planlama</p>
            </div>

            <div className="p-6 space-y-6 flex-1 overflow-y-auto">
                {/* Stats Card */}
                <div className="bg-zinc-900/50 rounded-xl border border-zinc-800 p-4 space-y-4">
                    <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-widest">Bu Hafta</h3>
                    <div className="grid grid-cols-2 gap-3">
                        <div className="p-3 bg-zinc-950 rounded-lg border border-zinc-800">
                            <span className="text-2xl font-bold text-white block">{weekStats.total}</span>
                            <span className="text-[10px] text-zinc-500">Toplam Etkinlik</span>
                        </div>
                        <div className="p-3 bg-indigo-950/30 rounded-lg border border-indigo-500/20">
                            <span className="text-2xl font-bold text-indigo-400 block">{weekStats.meetings}</span>
                            <span className="text-[10px] text-indigo-300/70">Toplantı</span>
                        </div>
                        <div className="p-3 bg-orange-950/30 rounded-lg border border-orange-500/20">
                            <span className="text-2xl font-bold text-orange-400 block">{weekStats.transfers}</span>
                            <span className="text-[10px] text-orange-300/70">Transfer</span>
                        </div>
                        <div className="p-3 bg-blue-950/30 rounded-lg border border-blue-500/20">
                            <span className="text-2xl font-bold text-blue-400 block">{weekStats.tasks}</span>
                            <span className="text-[10px] text-blue-300/70">Görev</span>
                        </div>
                    </div>
                </div>

                <div className="p-4 rounded-xl border border-zinc-800 bg-zinc-900/30">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="w-2 h-2 rounded-full bg-green-500"></div>
                        <span className="text-xs text-zinc-300">Bugün</span>
                    </div>
                    <div className="text-sm font-medium text-white">{formatDate(new Date(), { weekday: 'long', day: 'numeric', month: 'long' })}</div>
                </div>
            </div>

            {currentUser.role === Role.ADMIN && (
                <div className="p-6 border-t border-zinc-900">
                    <button 
                        onClick={() => { setNewEventForm(p => ({...p, date: new Date().toISOString().split('T')[0]})); setShowAddModal(true); }}
                        className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold shadow-lg flex items-center justify-center gap-2 transition-all active:scale-95"
                    >
                        <Plus size={18} /> {t('cal.newEvent')}
                    </button>
                </div>
            )}
        </div>

        {/* --- MAIN CONTENT: WEEKLY AGENDA LIST --- */}
        <div className="flex-1 flex flex-col h-full bg-zinc-950 relative">

            {/* Header / Week Nav */}
            <div className="p-4 md:p-6 border-b border-zinc-800 flex items-center justify-between bg-zinc-950/90 backdrop-blur z-20 sticky top-0">
                <div className="flex items-center gap-4">
                    <button onClick={() => changeWeek('prev')} className="p-2 hover:bg-zinc-900 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronLeft size={20}/></button>
                    <div>
                        <h2 className="text-lg md:text-xl font-bold text-white text-center min-w-[150px]">
                            {formatDate(weekDays[0], {day: 'numeric', month: 'short'})} - {formatDate(weekDays[6], {day: 'numeric', month: 'short', year: 'numeric'})}
                        </h2>
                    </div>
                    <button onClick={() => changeWeek('next')} className="p-2 hover:bg-zinc-900 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronRight size={20}/></button>
                </div>

                {/* Mobile Add Button */}
                <button 
                    onClick={() => { setNewEventForm(p => ({...p, date: new Date().toISOString().split('T')[0]})); setShowAddModal(true); }}
                    className="md:hidden w-10 h-10 flex items-center justify-center bg-indigo-600 rounded-full text-white shadow-lg"
                >
                    <Plus size={20} />
                </button>
            </div>

            {/* Scrollable Content */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 md:p-8 space-y-6">
                {weekDays.map(day => {
                    const dateStr = day.toISOString().split('T')[0];
                    const isCurrentDay = isToday(day);

                    // Filter events for this day
                    const dayEvents = combinedEvents.filter(e => {
                        if (!e.isTask && e.endDate) return dateStr >= e.date && dateStr <= e.endDate;
                        return e.date === dateStr;
                    }).sort((a,b) => a.startTime.localeCompare(b.startTime));

                    return (
                        <div key={dateStr} className={`flex flex-col md:flex-row gap-4 md:gap-8 group ${dayEvents.length === 0 ? 'opacity-50 hover:opacity-80 transition-opacity' : ''}`}>
                            {/* Date Column */}
                            <div className="md:w-32 flex-shrink-0 pt-2 flex md:flex-col items-center md:items-start gap-2 md:gap-0">
                                <span className={`text-xs font-bold uppercase tracking-wider ${isCurrentDay ? 'text-indigo-400' : 'text-zinc-500'}`}>
                                    {formatDate(day, {weekday: 'long'})}
                                </span>
                                <div className={`text-2xl font-light ${isCurrentDay ? 'text-white' : 'text-zinc-400'}`}>
                                    {day.getDate()}
                                </div>
                                {isCurrentDay && <div className="text-[10px] bg-indigo-500/20 text-indigo-300 px-2 py-0.5 rounded mt-1 hidden md:block">Bugün</div>}
                            </div>

                            {/* Events List */}
                            <div className="flex-1 space-y-3 pb-6 border-b border-zinc-800/50 group-last:border-none">
                                {dayEvents.length === 0 ? (
                                    <div className="py-2 text-sm text-zinc-600 italic">Planlanmış etkinlik yok.</div>
                                ) : (
                                    dayEvents.map(evt => (
                                        <div 
                                            key={evt.id}
                                            onClick={() => setSelectedEvent(evt)}
                                            className="bg-zinc-900/40 hover:bg-zinc-900 border border-zinc-800/60 hover:border-zinc-700 rounded-xl p-4 cursor-pointer transition-all hover:translate-x-1 group/card relative overflow-hidden"
                                        >
                                            {/* Left Colored Strip */}
                                            <div className={`absolute top-0 bottom-0 left-0 w-1 ${
                                                evt.isTask ? 'bg-blue-500' : 
                                                evt.type === 'Şube Transferi' ? 'bg-orange-500' : 
                                                evt.type === 'Toplantı' ? 'bg-indigo-500' : 'bg-zinc-500'
                                            }`}></div>

                                            <div className="flex justify-between items-start pl-3">
                                                <div className="flex-1">
                                                    <div className="flex items-center gap-2 mb-1">
                                                        <span className="text-xs font-mono text-zinc-500 flex items-center gap-1">
                                                            <Clock size={12}/> {evt.startTime} - {evt.endTime}
                                                        </span>
                                                        {evt.type === 'Şube Transferi' && <span className="text-[10px] bg-orange-500/20 text-orange-400 px-1.5 rounded font-bold">TRANSFER</span>}
                                                    </div>
                                                    <h4 className="text-base font-bold text-zinc-200 group-hover/card:text-white transition-colors">{getText(evt.title)}</h4>
                                                    {evt.description && <p className="text-xs text-zinc-500 mt-1 line-clamp-1">{getText(evt.description)}</p>}
                                                </div>

                                                {/* Avatars */}
                                                <div className="flex -space-x-2 pl-2">
                                                    {evt.attendees.slice(0, 3).map(id => {
                                                        const emp = MOCK_EMPLOYEES.find(e => e.id === id);
                                                        return emp ? <img key={id} src={emp.avatarUrl} className="w-8 h-8 rounded-full border-2 border-zinc-900 bg-zinc-800" title={emp.name}/> : null;
                                                    })}
                                                    {evt.attendees.length > 3 && <div className="w-8 h-8 rounded-full bg-zinc-800 border-2 border-zinc-900 flex items-center justify-center text-[10px] text-zinc-400">+{evt.attendees.length-3}</div>}
                                                </div>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    );
                })}

                <div className="h-20"></div> {/* Bottom Spacer */}
            </div>
        </div>

        {/* --- DETAIL PANEL (SLIDE OVER) --- */}
        {selectedEvent && (
            <div className="fixed inset-0 z-[200] flex justify-end bg-black/50 backdrop-blur-sm animate-in fade-in" onClick={() => setSelectedEvent(null)}>
                <div className="w-full md:w-[400px] h-full bg-zinc-950 border-l border-zinc-800 p-6 flex flex-col shadow-2xl animate-in slide-in-from-right duration-300" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-start mb-8">
                        <div>
                            <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest">{selectedEvent.isTask ? 'Görev Detayı' : 'Etkinlik Detayı'}</span>
                            <h2 className="text-2xl font-bold text-white mt-2 leading-tight">{getText(selectedEvent.title)}</h2>
                        </div>
                        <button onClick={() => setSelectedEvent(null)} className="p-2 bg-zinc-900 rounded-lg text-zinc-400 hover:text-white"><X size={20}/></button>
                    </div>

                    <div className="space-y-6 flex-1 overflow-y-auto">
                        <div className="flex items-center gap-4 text-zinc-300">
                            <div className="w-10 h-10 rounded-lg bg-zinc-900 flex items-center justify-center border border-zinc-800"><CalendarIcon size={20}/></div>
                            <div>
                                <p className="text-xs text-zinc-500">Tarih</p>
                                <p className="font-medium">{formatDate(selectedEvent.date, {day:'numeric', month:'long', year: 'numeric'})}</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-4 text-zinc-300">
                            <div className="w-10 h-10 rounded-lg bg-zinc-900 flex items-center justify-center border border-zinc-800"><Clock size={20}/></div>
                            <div>
                                <p className="text-xs text-zinc-500">Saat</p>
                                <p className="font-medium">{selectedEvent.startTime} - {selectedEvent.endTime}</p>
                            </div>
                        </div>

                        <div className="p-4 bg-zinc-900/50 rounded-xl border border-zinc-800">
                            <h4 className="text-xs font-bold text-zinc-500 uppercase mb-2">Açıklama</h4>
                            <p className="text-sm text-zinc-300 leading-relaxed">{getText(selectedEvent.description) || 'Açıklama yok.'}</p>
                        </div>

                        <div>
                            <h4 className="text-xs font-bold text-zinc-500 uppercase mb-3">Katılımcılar ({selectedEvent.attendees.length})</h4>
                            <div className="space-y-2">
                                {selectedEvent.attendees.map(id => {
                                    const emp = MOCK_EMPLOYEES.find(e => e.id === id);
                                    return emp ? (
                                        <div key={id} className="flex items-center gap-3 p-2 rounded-lg bg-zinc-900/30 border border-zinc-800/50">
                                            <img src={emp.avatarUrl} className="w-8 h-8 rounded-full"/>
                                            <div>
                                                <p className="text-sm font-bold text-zinc-200">{emp.name}</p>
                                                <p className="text-[10px] text-zinc-500">{emp.branch}</p>
                                            </div>
                                        </div>
                                    ) : null;
                                })}
                            </div>
                        </div>
                    </div>

                    {!selectedEvent.isTask && (
                        <div className="pt-6 border-t border-zinc-800">
                            <button onClick={handleDeleteEvent} className="w-full py-3 bg-red-900/20 text-red-400 border border-red-900/30 rounded-xl text-sm font-bold hover:bg-red-900/40 transition-colors flex items-center justify-center gap-2">
                                <Trash2 size={16}/> {t('cal.deleteEvent')}
                            </button>
                        </div>
                    )}
                </div>
            </div>
        )}
    </div>
  );
};

export default Calendar;

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_EMPLOYEES } from '../constants';
import { Branch, Employee, Role, CalendarEvent, Task } from '../types';
import { Plus, X, Calendar as CalendarIcon, Clock, MapPin, Users, Save, Building2, CheckCircle2, AlignLeft, Trash2, ChevronLeft, ChevronRight, AlertTriangle, CheckSquare, Loader2, Rocket, ArrowRightLeft, CalendarRange, MoreHorizontal, Filter, List } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';

interface CalendarProps {
    currentUser: Employee;
}

interface DisplayEvent extends CalendarEvent {
    isTask?: boolean;
    status?: string;
}

const Calendar: React.FC<CalendarProps> = ({ currentUser }) => {
  // --- STATE ---
  const [viewDate, setViewDate] = useState(new Date()); // Haftanın referans günü

  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const { t, formatDate, language } = useLanguage();

  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);

  // Modal & Selection
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<DisplayEvent | null>(null);

  // Filters
  const [selectedBranches, setSelectedBranches] = useState<Branch[]>([]);
  const [targetBranch, setTargetBranch] = useState<Branch>(Branch.DOM);

  // Form
  const [newEventForm, setNewEventForm] = useState<Partial<CalendarEvent>>({
      title: '',
      type: 'Toplantı',
      date: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0], 
      startTime: '09:00',
      endTime: '10:00',
      attendees: [],
      description: ''
  });

  // --- DATA FETCHING ---
  useEffect(() => {
    const fetchData = async () => {
        setIsLoading(true);
        try {
            // Events
            let eventQuery = supabase.from('calendar_events').select('*');
            if (currentUser.role !== Role.ADMIN) {
                eventQuery = eventQuery.contains('attendees', [currentUser.id]);
            }
            const { data: eventData } = await eventQuery;
            if (eventData) {
                const dbEvents: CalendarEvent[] = eventData.map((e: any) => ({
                    id: e.id, title: e.title, type: e.type, date: e.date,
                    endDate: e.end_date || e.date, startTime: e.start_time, endTime: e.end_time,
                    attendees: e.attendees || [], description: e.description
                }));
                setEvents(dbEvents);
            }

            // Tasks
            let taskQuery = supabase.from('tasks').select('*');
            if (currentUser.role !== Role.ADMIN) {
                taskQuery = taskQuery.contains('assigned_to', [currentUser.id]);
            }
            const { data: taskData } = await taskQuery;
            if(taskData) {
                 const dbTasks: Task[] = taskData.map((t: any) => ({
                    id: t.id, title: t.title, description: t.description,
                    assignedTo: t.assigned_to || [], dueDate: t.due_date,
                    priority: t.priority, status: t.status, progress: t.progress, checklist: t.checklist || []
                }));
                setTasks(dbTasks);
            }
        } catch (e) {
            console.log("Error:", e);
        } finally {
            setIsLoading(false);
        }
    };
    fetchData();
  }, [currentUser]); 

  // --- LOGIC ---
  const combinedEvents = useMemo((): DisplayEvent[] => {
      const filteredEvents = currentUser.role === Role.ADMIN ? events : events.filter(evt => evt.attendees.includes(currentUser.id));
      const filteredTasks = currentUser.role === Role.ADMIN ? tasks : tasks.filter(t => t.assignedTo.includes(currentUser.id));

      const taskEvents: DisplayEvent[] = filteredTasks.map(t => ({
          id: t.id, title: t.title, type: 'Diğer', date: t.dueDate, endDate: t.dueDate,
          startTime: '09:00', endTime: '18:00', attendees: t.assignedTo, description: t.description,
          isTask: true, status: t.status
      }));

      return [...(filteredEvents as DisplayEvent[]), ...taskEvents];
  }, [events, tasks, currentUser]);

  // WEEK LOGIC
  const getStartOfWeek = (d: Date) => {
      const date = new Date(d);
      const day = date.getDay(); 
      const diff = date.getDate() - day + (day === 0 ? -6 : 1); // Adjust when day is Sunday
      return new Date(date.setDate(diff));
  };

  const currentWeekStart = useMemo(() => getStartOfWeek(viewDate), [viewDate]);

  const weekDays = useMemo(() => {
      const days = [];
      for (let i = 0; i < 7; i++) {
          const d = new Date(currentWeekStart);
          d.setDate(d.getDate() + i);
          days.push(d);
      }
      return days;
  }, [currentWeekStart]);

  const changeWeek = (direction: 'prev' | 'next') => {
      const newDate = new Date(viewDate);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setViewDate(newDate);
  };

  const isToday = (d: Date) => {
      const today = new Date();
      return d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
  };

  const getText = (text?: string) => {
    if (!text) return '';
    return text.startsWith('task.mock') ? t(text) : text;
  };

  // Color Helper
  const getEventColor = (type: string, isTask?: boolean) => {
      if (isTask) return 'bg-blue-900/30 border-blue-500/30 text-blue-200 hover:border-blue-400';
      switch(type) {
          case 'Toplantı': return 'bg-indigo-900/30 border-indigo-500/30 text-indigo-200 hover:border-indigo-400';
          case 'Şube Transferi': return 'bg-orange-900/30 border-orange-500/30 text-orange-200 hover:border-orange-400';
          case 'Teslim Tarihi': return 'bg-red-900/30 border-red-500/30 text-red-200 hover:border-red-400';
          case 'Montaj': return 'bg-emerald-900/30 border-emerald-500/30 text-emerald-200 hover:border-emerald-400';
          default: return 'bg-zinc-800/50 border-zinc-700 text-zinc-300 hover:border-zinc-500';
      }
  };

  // Handlers
  const handleSaveEvent = async (e: React.FormEvent) => {
      e.preventDefault();
      const isTransfer = newEventForm.type === 'Şube Transferi';
      if (!newEventForm.title && !isTransfer) return alert(t('cal.warnTitle'));

      setIsSaving(true);
      try {
          const finalTitle = isTransfer ? `${newEventForm.attendees?.length} Personel -> ${targetBranch}` : newEventForm.title!;
          const dbPayload = {
              title: finalTitle, type: newEventForm.type, date: newEventForm.date,
              end_date: newEventForm.endDate || newEventForm.date, start_time: newEventForm.startTime,
              end_time: newEventForm.endTime, attendees: newEventForm.attendees || [], description: newEventForm.description
          };
          const { data, error } = await supabase.from('calendar_events').insert([dbPayload]).select();
          if (error) throw error;

          if(isTransfer && currentUser.role === Role.ADMIN) {
               await supabase.from('profiles').update({ branch: targetBranch }).in('id', newEventForm.attendees || []);
          }

          if (data) {
              setEvents(prev => [...prev, { ...data[0], attendees: data[0].attendees || [] } as CalendarEvent]);
              setShowAddModal(false);
              alert(t('common.success'));
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const handleDeleteEvent = async () => {
      if (!selectedEvent || selectedEvent.isTask) return;
      if (confirm('Silmek istediğinize emin misiniz?')) {
          const { error } = await supabase.from('calendar_events').delete().eq('id', selectedEvent.id);
          if (!error) {
              setEvents(events.filter(e => e.id !== selectedEvent.id));
              setSelectedEvent(null);
          }
      }
  };

  const toggleBranchSelection = (branch: Branch) => {
    setSelectedBranches(prev => prev.includes(branch) ? prev.filter(b => b !== branch) : [...prev, branch]);
  };

  const toggleAttendee = (id: string) => {
    setNewEventForm(prev => {
        const cur = prev.attendees || [];
        return cur.includes(id) ? { ...prev, attendees: cur.filter(x => x !== id) } : { ...prev, attendees: [...cur, id] };
    });
  };

  // --- WEEK STATS ---
  const weekStats = useMemo(() => {
      const startStr = weekDays[0].toISOString().split('T')[0];
      const endStr = weekDays[6].toISOString().split('T')[0];

      const eventsInWeek = combinedEvents.filter(e => e.date >= startStr && e.date <= endStr);

      return {
          total: eventsInWeek.length,
          meetings: eventsInWeek.filter(e => e.type === 'Toplantı').length,
          transfers: eventsInWeek.filter(e => e.type === 'Şube Transferi').length,
          tasks: eventsInWeek.filter(e => e.isTask).length
      };
  }, [combinedEvents, weekDays]);

  return (
    <div className="flex h-full relative overflow-hidden bg-zinc-950">

        {/* ADD EVENT MODAL */}
        {showAddModal && (
            <div className="fixed inset-0 z-[100] flex justify-center items-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in">
                <div className="bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
                    <div className="p-5 border-b border-zinc-800 flex justify-between items-center bg-zinc-950/80 backdrop-blur">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            {newEventForm.type === 'Şube Transferi' ? <Rocket size={20} className="text-orange-500"/> : <CalendarIcon size={20} className="text-indigo-500"/>}
                            {t('cal.newEvent')}
                        </h3>
                        <button onClick={() => setShowAddModal(false)}><X size={20} className="text-zinc-500 hover:text-white"/></button>
                    </div>
                    <div className="p-6 overflow-y-auto custom-scrollbar flex-1">
                        <form onSubmit={handleSaveEvent} className="space-y-5">
                            {/* Type */}
                            <div>
                                <label className="text-xs text-zinc-400 block mb-1.5">{t('cal.type')}</label>
                                <div className="flex gap-2 overflow-x-auto pb-1">
                                    {['Toplantı', 'Montaj', 'Teslim Tarihi', 'Şube Transferi', 'Diğer'].map(type => (
                                        <button key={type} type="button" onClick={() => setNewEventForm({...newEventForm, type: type as any})}
                                            className={`px-3 py-1.5 rounded-lg text-xs font-medium border whitespace-nowrap transition-all ${newEventForm.type === type ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800'}`}>
                                            {type === 'Şube Transferi' ? t('cal.type.transfer') : type}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Title (If not transfer) */}
                            {newEventForm.type !== 'Şube Transferi' && (
                                <div>
                                    <label className="text-xs text-zinc-400 block mb-1.5">{t('cal.eventTitle')}</label>
                                    <input type="text" required value={newEventForm.title} onChange={e => setNewEventForm({...newEventForm, title: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-white focus:border-indigo-500 outline-none" />
                                </div>
                            )}

                            {/* Transfer Logic */}
                            {newEventForm.type === 'Şube Transferi' && (
                                <div className="p-3 bg-orange-950/20 border border-orange-500/20 rounded-lg">
                                    <label className="text-xs font-bold text-orange-400 block mb-2">{t('cal.targetBranch')}</label>
                                    <div className="flex flex-wrap gap-2">
                                        {Object.values(Branch).map(branch => (
                                            <button key={branch} type="button" onClick={() => setTargetBranch(branch)} className={`px-2 py-1 text-xs rounded border ${targetBranch === branch ? 'bg-orange-600 text-white border-orange-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800'}`}>{branch}</button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Dates */}
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="text-xs text-zinc-400 block mb-1.5">{t('cal.startDate')}</label><input type="date" value={newEventForm.date} onChange={e => setNewEventForm({...newEventForm, date: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-white text-sm"/></div>
                                <div><label className="text-xs text-zinc-400 block mb-1.5">{t('cal.startTime')}</label><input type="time" value={newEventForm.startTime} onChange={e => setNewEventForm({...newEventForm, startTime: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-white text-sm"/></div>
                            </div>

                            {/* Attendees Selector */}
                            <div className="p-4 bg-zinc-950/50 border border-zinc-800 rounded-xl space-y-3">
                                <label className="text-xs font-medium text-zinc-400 block">{t('cal.branchFilter')}</label>
                                <div className="flex gap-2 flex-wrap">
                                    {Object.values(Branch).map(b => (
                                        <button key={b} type="button" onClick={() => toggleBranchSelection(b)} className={`px-2 py-1 text-[10px] rounded border ${selectedBranches.includes(b) ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-500 border-zinc-800'}`}>{b}</button>
                                    ))}
                                </div>
                                <div className="h-px bg-zinc-800"></div>
                                <label className="text-xs font-medium text-zinc-400 block">{t('cal.attendees')}</label>
                                <div className="flex gap-2 overflow-x-auto pb-1">
                                    {MOCK_EMPLOYEES.filter(e => selectedBranches.length === 0 || selectedBranches.includes(e.branch)).map(emp => (
                                        <div key={emp.id} onClick={() => toggleAttendee(emp.id)} className={`cursor-pointer flex flex-col items-center gap-1 min-w-[50px] p-2 rounded-lg border transition-all ${newEventForm.attendees?.includes(emp.id) ? 'bg-indigo-500/20 border-indigo-500' : 'bg-zinc-900 border-zinc-800'}`}>
                                            <img src={emp.avatarUrl} className="w-8 h-8 rounded-full"/>
                                            <span className="text-[9px] text-zinc-400 truncate w-full text-center">{emp.name.split(' ')[0]}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Footer */}
                            <div className="pt-4 flex gap-3">
                                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-3 bg-zinc-800 text-zinc-400 rounded-xl text-sm">{t('tasks.cancel')}</button>
                                <button type="submit" disabled={isSaving} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg">
                                    {isSaving ? '...' : t('cal.saveEvent')}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* --- LEFT PANEL: SUMMARY & NAV (HIDDEN ON MOBILE) --- */}
        <div className="w-full md:w-80 bg-zinc-950 border-b md:border-b-0 md:border-r border-zinc-800 flex-col hidden md:flex">
            <div className="p-6 border-b border-zinc-900">
                <h2 className="text-xl font-bold text-white mb-1">Ajanda</h2>
                <p className="text-xs text-zinc-500">Haftalık Planlama</p>
            </div>

            <div className="p-6 space-y-6 flex-1 overflow-y-auto">
                {/* Stats Card */}
                <div className="bg-zinc-900/50 rounded-xl border border-zinc-800 p-4 space-y-4">
                    <h3 className="text-xs font-bold text-zinc-500 uppercase tracking-widest">Bu Hafta</h3>
                    <div className="grid grid-cols-2 gap-3">
                        <div className="p-3 bg-zinc-950 rounded-lg border border-zinc-800">
                            <span className="text-2xl font-bold text-white block">{weekStats.total}</span>
                            <span className="text-[10px] text-zinc-500">Toplam Etkinlik</span>
                        </div>
                        <div className="p-3 bg-indigo-950/30 rounded-lg border border-indigo-500/20">
                            <span className="text-2xl font-bold text-indigo-400 block">{weekStats.meetings}</span>
                            <span className="text-[10px] text-indigo-300/70">Toplantı</span>
                        </div>
                        <div className="p-3 bg-orange-950/30 rounded-lg border border-orange-500/20">
                            <span className="text-2xl font-bold text-orange-400 block">{weekStats.transfers}</span>
                            <span className="text-[10px] text-orange-300/70">Transfer</span>
                        </div>
                        <div className="p-3 bg-blue-950/30 rounded-lg border border-blue-500/20">
                            <span className="text-2xl font-bold text-blue-400 block">{weekStats.tasks}</span>
                            <span className="text-[10px] text-blue-300/70">Görev</span>
                        </div>
                    </div>
                </div>

                <div className="p-4 rounded-xl border border-zinc-800 bg-zinc-900/30">
                    <div className="flex items-center gap-3 mb-2">
                        <div className="w-2 h-2 rounded-full bg-green-500"></div>
                        <span className="text-xs text-zinc-300">Bugün</span>
                    </div>
                    <div className="text-sm font-medium text-white">{formatDate(new Date(), { weekday: 'long', day: 'numeric', month: 'long' })}</div>
                </div>
            </div>

            {currentUser.role === Role.ADMIN && (
                <div className="p-6 border-t border-zinc-900">
                    <button 
                        onClick={() => { setNewEventForm(p => ({...p, date: new Date().toISOString().split('T')[0]})); setShowAddModal(true); }}
                        className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold shadow-lg flex items-center justify-center gap-2 transition-all active:scale-95"
                    >
                        <Plus size={18} /> {t('cal.newEvent')}
                    </button>
                </div>
            )}
        </div>

        {/* --- MAIN CONTENT: WEEKLY SWIMLANE VIEW (CREATIVE) --- */}
        <div className="flex-1 flex flex-col h-full bg-zinc-950 relative">

            {/* Header / Week Nav */}
            <div className="p-4 border-b border-zinc-800 flex items-center justify-between bg-zinc-950/90 backdrop-blur z-20 shrink-0">
                <div className="flex items-center gap-4">
                    <div className="flex items-center bg-zinc-900 rounded-lg border border-zinc-800">
                        <button onClick={() => changeWeek('prev')} className="p-2 hover:bg-zinc-800 text-zinc-400 hover:text-white transition-colors rounded-l-lg"><ChevronLeft size={18}/></button>
                        <div className="w-px h-6 bg-zinc-800"></div>
                        <button onClick={() => changeWeek('next')} className="p-2 hover:bg-zinc-800 text-zinc-400 hover:text-white transition-colors rounded-r-lg"><ChevronRight size={18}/></button>
                    </div>
                    <div>
                        <h2 className="text-lg font-bold text-white flex items-center gap-2">
                            <CalendarRange size={18} className="text-indigo-500"/>
                            {formatDate(weekDays[0], {day: 'numeric', month: 'short'})} - {formatDate(weekDays[6], {day: 'numeric', month: 'short', year: 'numeric'})}
                        </h2>
                    </div>
                </div>

                {/* Mobile Add Button */}
                <button 
                    onClick={() => { setNewEventForm(p => ({...p, date: new Date().toISOString().split('T')[0]})); setShowAddModal(true); }}
                    className="md:hidden w-8 h-8 flex items-center justify-center bg-indigo-600 rounded-lg text-white shadow-lg"
                >
                    <Plus size={18} />
                </button>
            </div>

            {/* CREATIVE SWIMLANE LAYOUT */}
            <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar">
                <div className="h-full min-w-[800px] grid grid-cols-7 divide-x divide-zinc-800/50">
                    {weekDays.map(day => {
                        const dateStr = day.toISOString().split('T')[0];
                        const isCurrentDay = isToday(day);

                        // Filter events for this day
                        const dayEvents = combinedEvents.filter(e => {
                            if (!e.isTask && e.endDate) return dateStr >= e.date && dateStr <= e.endDate;
                            return e.date === dateStr;
                        }).sort((a,b) => a.startTime.localeCompare(b.startTime));

                        return (
                            <div key={dateStr} className={`flex flex-col h-full relative group/col transition-colors ${isCurrentDay ? 'bg-indigo-900/5' : 'hover:bg-zinc-900/30'}`}>
                                {/* Column Header */}
                                <div className={`p-3 text-center border-b border-zinc-800 sticky top-0 z-10 ${isCurrentDay ? 'bg-indigo-500/10 backdrop-blur border-b-indigo-500/20' : 'bg-zinc-950/80 backdrop-blur'}`}>
                                    <span className={`text-[10px] font-bold uppercase tracking-widest block mb-1 ${isCurrentDay ? 'text-indigo-400' : 'text-zinc-500'}`}>
                                        {formatDate(day, {weekday: 'short'})}
                                    </span>
                                    <div className={`inline-flex items-center justify-center w-8 h-8 rounded-full text-sm font-bold transition-all ${isCurrentDay ? 'bg-indigo-500 text-white shadow-lg shadow-indigo-500/40 scale-110' : 'text-zinc-300 group-hover/col:bg-zinc-800'}`}>
                                        {day.getDate()}
                                    </div>
                                </div>

                                {/* Events Stack */}
                                <div className="flex-1 p-2 space-y-2 overflow-y-auto custom-scrollbar relative">
                                    {/* Today Indicator Line */}
                                    {isCurrentDay && <div className="absolute top-0 left-0 w-full h-1 bg-indigo-500/20"></div>}

                                    {dayEvents.map(evt => (
                                        <div 
                                            key={evt.id}
                                            onClick={() => setSelectedEvent(evt)}
                                            className={`p-3 rounded-xl border cursor-pointer transition-all hover:scale-[1.02] active:scale-95 shadow-sm group/card relative overflow-hidden ${getEventColor(evt.type, evt.isTask)}`}
                                        >
                                            {/* Top Strip */}
                                            <div className={`absolute top-0 left-0 w-1 h-full ${evt.isTask ? 'bg-blue-500' : evt.type === 'Şube Transferi' ? 'bg-orange-500' : 'bg-indigo-500'}`}></div>

                                            <div className="pl-2">
                                                <div className="flex items-center justify-between mb-1">
                                                    <span className="text-[9px] font-mono opacity-80 flex items-center gap-1">
                                                        <Clock size={10} /> {evt.startTime}
                                                    </span>
                                                    {evt.type === 'Şube Transferi' && <Rocket size={10} className="text-orange-400"/>}
                                                </div>
                                                <h4 className="text-xs font-bold leading-tight mb-1 text-zinc-100 line-clamp-2">
                                                    {getText(evt.title)}
                                                </h4>

                                                {/* Mini Avatars */}
                                                <div className="flex -space-x-1.5 pt-1">
                                                    {evt.attendees.slice(0, 3).map(id => {
                                                        const emp = MOCK_EMPLOYEES.find(e => e.id === id);
                                                        return emp ? <img key={id} src={emp.avatarUrl} className="w-4 h-4 rounded-full border border-zinc-900 bg-zinc-800" title={emp.name}/> : null;
                                                    })}
                                                </div>
                                            </div>
                                        </div>
                                    ))}

                                    {/* Add Button (Hover) */}
                                    <div className="opacity-0 group-hover/col:opacity-100 transition-opacity absolute inset-x-0 bottom-0 p-2 pointer-events-none flex justify-center pb-4">
                                        <button 
                                            onClick={() => { setNewEventForm(p => ({...p, date: dateStr, endDate: dateStr})); setShowAddModal(true); }}
                                            className="pointer-events-auto w-8 h-8 rounded-full bg-zinc-800 hover:bg-indigo-600 text-zinc-400 hover:text-white flex items-center justify-center shadow-lg transition-colors"
                                        >
                                            <Plus size={16} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        )
                    })}
                </div>
            </div>
        </div>

        {/* --- DETAIL PANEL (SLIDE OVER) --- */}
        {selectedEvent && (
            <div className="fixed inset-0 z-[200] flex justify-end bg-black/50 backdrop-blur-sm animate-in fade-in" onClick={() => setSelectedEvent(null)}>
                <div className="w-full md:w-[400px] h-full bg-zinc-950 border-l border-zinc-800 p-6 flex flex-col shadow-2xl animate-in slide-in-from-right duration-300" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-start mb-8">
                        <div>
                            <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest">{selectedEvent.isTask ? 'Görev Detayı' : 'Etkinlik Detayı'}</span>
                            <h2 className="text-2xl font-bold text-white mt-2 leading-tight">{getText(selectedEvent.title)}</h2>
                        </div>
                        <button onClick={() => setSelectedEvent(null)} className="p-2 bg-zinc-900 rounded-lg text-zinc-400 hover:text-white"><X size={20}/></button>
                    </div>

                    <div className="space-y-6 flex-1 overflow-y-auto">
                        <div className="flex items-center gap-4 text-zinc-300">
                            <div className="w-10 h-10 rounded-lg bg-zinc-900 flex items-center justify-center border border-zinc-800"><CalendarIcon size={20}/></div>
                            <div>
                                <p className="text-xs text-zinc-500">Tarih</p>
                                <p className="font-medium">{formatDate(selectedEvent.date, {day:'numeric', month:'long', year: 'numeric'})}</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-4 text-zinc-300">
                            <div className="w-10 h-10 rounded-lg bg-zinc-900 flex items-center justify-center border border-zinc-800"><Clock size={20}/></div>
                            <div>
                                <p className="text-xs text-zinc-500">Saat</p>
                                <p className="font-medium">{selectedEvent.startTime} - {selectedEvent.endTime}</p>
                            </div>
                        </div>

                        <div className="p-4 bg-zinc-900/50 rounded-xl border border-zinc-800">
                            <h4 className="text-xs font-bold text-zinc-500 uppercase mb-2">Açıklama</h4>
                            <p className="text-sm text-zinc-300 leading-relaxed">{getText(selectedEvent.description) || 'Açıklama yok.'}</p>
                        </div>

                        <div>
                            <h4 className="text-xs font-bold text-zinc-500 uppercase mb-3">Katılımcılar ({selectedEvent.attendees.length})</h4>
                            <div className="space-y-2">
                                {selectedEvent.attendees.map(id => {
                                    const emp = MOCK_EMPLOYEES.find(e => e.id === id);
                                    return emp ? (
                                        <div key={id} className="flex items-center gap-3 p-2 rounded-lg bg-zinc-900/30 border border-zinc-800/50">
                                            <img src={emp.avatarUrl} className="w-8 h-8 rounded-full"/>
                                            <div>
                                                <p className="text-sm font-bold text-zinc-200">{emp.name}</p>
                                                <p className="text-[10px] text-zinc-500">{emp.branch}</p>
                                            </div>
                                        </div>
                                    ) : null;
                                })}
                            </div>
                        </div>
                    </div>

                    {!selectedEvent.isTask && (
                        <div className="pt-6 border-t border-zinc-800">
                            <button onClick={handleDeleteEvent} className="w-full py-3 bg-red-900/20 text-red-400 border border-red-900/30 rounded-xl text-sm font-bold hover:bg-red-900/40 transition-colors flex items-center justify-center gap-2">
                                <Trash2 size={16}/> {t('cal.deleteEvent')}
                            </button>
                        </div>
                    )}
                </div>
            </div>
        )}
    </div>
  );
};

export default Calendar;

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_EMPLOYEES } from '../constants';
import { Branch, Employee, Role, CalendarEvent, Task } from '../types';
import { Plus, X, Calendar as CalendarIcon, Clock, MapPin, Users, Save, Building2, CheckCircle2, AlignLeft, Trash2, ChevronLeft, ChevronRight, AlertTriangle, CheckSquare, Loader2, Rocket, ArrowRightLeft, CalendarRange, MoreHorizontal, Filter, List } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';

interface CalendarProps {
    currentUser: Employee;
}

interface DisplayEvent extends CalendarEvent {
    isTask?: boolean;
    status?: string;
}

const Calendar: React.FC<CalendarProps> = ({ currentUser }) => {
  // --- STATE ---
  const [viewDate, setViewDate] = useState(new Date()); // Haftanın referans günü

  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const { t, formatDate, language } = useLanguage();

  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);

  // Modal & Selection
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<DisplayEvent | null>(null);

  // Filters
  const [selectedBranches, setSelectedBranches] = useState<Branch[]>([]);
  const [targetBranch, setTargetBranch] = useState<Branch>(Branch.DOM);

  // Form
  const [newEventForm, setNewEventForm] = useState<Partial<CalendarEvent>>({
      title: '',
      type: 'Toplantı',
      date: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0], 
      startTime: '09:00',
      endTime: '10:00',
      attendees: [],
      description: ''
  });

  // --- DATA FETCHING ---
  useEffect(() => {
    const fetchData = async () => {
        setIsLoading(true);
        try {
            // Events
            let eventQuery = supabase.from('calendar_events').select('*');
            if (currentUser.role !== Role.ADMIN) {
                eventQuery = eventQuery.contains('attendees', [currentUser.id]);
            }
            const { data: eventData } = await eventQuery;
            if (eventData) {
                const dbEvents: CalendarEvent[] = eventData.map((e: any) => ({
                    id: e.id, title: e.title, type: e.type, date: e.date,
                    endDate: e.end_date || e.date, startTime: e.start_time, endTime: e.end_time,
                    attendees: e.attendees || [], description: e.description
                }));
                setEvents(dbEvents);
            }

            // Tasks
            let taskQuery = supabase.from('tasks').select('*');
            if (currentUser.role !== Role.ADMIN) {
                taskQuery = taskQuery.contains('assigned_to', [currentUser.id]);
            }
            const { data: taskData } = await taskQuery;
            if(taskData) {
                 const dbTasks: Task[] = taskData.map((t: any) => ({
                    id: t.id, title: t.title, description: t.description,
                    assignedTo: t.assigned_to || [], dueDate: t.due_date,
                    priority: t.priority, status: t.status, progress: t.progress, checklist: t.checklist || []
                }));
                setTasks(dbTasks);
            }
        } catch (e) {
            console.log("Error:", e);
        } finally {
            setIsLoading(false);
        }
    };
    fetchData();
  }, [currentUser]); 

  // --- LOGIC ---
  const combinedEvents = useMemo((): DisplayEvent[] => {
      const filteredEvents = currentUser.role === Role.ADMIN ? events : events.filter(evt => evt.attendees.includes(currentUser.id));
      const filteredTasks = currentUser.role === Role.ADMIN ? tasks : tasks.filter(t => t.assignedTo.includes(currentUser.id));

      const taskEvents: DisplayEvent[] = filteredTasks.map(t => ({
          id: t.id, title: t.title, type: 'Diğer', date: t.dueDate, endDate: t.dueDate,
          startTime: '09:00', endTime: '18:00', attendees: t.assignedTo, description: t.description,
          isTask: true, status: t.status
      }));

      return [...(filteredEvents as DisplayEvent[]), ...taskEvents];
  }, [events, tasks, currentUser]);

  // WEEK LOGIC
  const getStartOfWeek = (d: Date) => {
      const date = new Date(d);
      const day = date.getDay(); 
      const diff = date.getDate() - day + (day === 0 ? -6 : 1); // Adjust when day is Sunday
      return new Date(date.setDate(diff));
  };

  const currentWeekStart = useMemo(() => getStartOfWeek(viewDate), [viewDate]);

  const weekDays = useMemo(() => {
      const days = [];
      for (let i = 0; i < 7; i++) {
          const d = new Date(currentWeekStart);
          d.setDate(d.getDate() + i);
          days.push(d);
      }
      return days;
  }, [currentWeekStart]);

  const changeWeek = (direction: 'prev' | 'next') => {
      const newDate = new Date(viewDate);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setViewDate(newDate);
  };

  const isToday = (d: Date) => {
      const today = new Date();
      return d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
  };

  const getText = (text?: string) => {
    if (!text) return '';
    return text.startsWith('task.mock') ? t(text) : text;
  };

  // Color Helper
  const getEventColor = (type: string, isTask?: boolean) => {
      if (isTask) return 'bg-blue-900/30 border-blue-500/30 text-blue-200 hover:border-blue-400';
      switch(type) {
          case 'Toplantı': return 'bg-indigo-900/30 border-indigo-500/30 text-indigo-200 hover:border-indigo-400';
          case 'Şube Transferi': return 'bg-orange-900/30 border-orange-500/30 text-orange-200 hover:border-orange-400';
          case 'Teslim Tarihi': return 'bg-red-900/30 border-red-500/30 text-red-200 hover:border-red-400';
          case 'Montaj': return 'bg-emerald-900/30 border-emerald-500/30 text-emerald-200 hover:border-emerald-400';
          default: return 'bg-zinc-800/50 border-zinc-700 text-zinc-300 hover:border-zinc-500';
      }
  };

  // Handlers
  const handleSaveEvent = async (e: React.FormEvent) => {
      e.preventDefault();
      const isTransfer = newEventForm.type === 'Şube Transferi';
      if (!newEventForm.title && !isTransfer) return alert(t('cal.warnTitle'));

      setIsSaving(true);
      try {
          const finalTitle = isTransfer ? `${newEventForm.attendees?.length} Personel -> ${targetBranch}` : newEventForm.title!;
          const dbPayload = {
              title: finalTitle, type: newEventForm.type, date: newEventForm.date,
              end_date: newEventForm.endDate || newEventForm.date, start_time: newEventForm.startTime,
              end_time: newEventForm.endTime, attendees: newEventForm.attendees || [], description: newEventForm.description
          };
          const { data, error } = await supabase.from('calendar_events').insert([dbPayload]).select();
          if (error) throw error;

          if(isTransfer && currentUser.role === Role.ADMIN) {
               await supabase.from('profiles').update({ branch: targetBranch }).in('id', newEventForm.attendees || []);
          }

          if (data) {
              setEvents(prev => [...prev, { ...data[0], attendees: data[0].attendees || [] } as CalendarEvent]);
              setShowAddModal(false);
              alert(t('common.success'));
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const handleDeleteEvent = async () => {
      if (!selectedEvent || selectedEvent.isTask) return;
      if (confirm('Silmek istediğinize emin misiniz?')) {
          const { error } = await supabase.from('calendar_events').delete().eq('id', selectedEvent.id);
          if (!error) {
              setEvents(events.filter(e => e.id !== selectedEvent.id));
              setSelectedEvent(null);
          }
      }
  };

  const toggleBranchSelection = (branch: Branch) => {
    setSelectedBranches(prev => prev.includes(branch) ? prev.filter(b => b !== branch) : [...prev, branch]);
  };

  const toggleAttendee = (id: string) => {
    setNewEventForm(prev => {
        const cur = prev.attendees || [];
        return cur.includes(id) ? { ...prev, attendees: cur.filter(x => x !== id) } : { ...prev, attendees: [...cur, id] };
    });
  };

  // --- WEEK STATS ---
  const weekStats = useMemo(() => {
      const startStr = weekDays[0].toISOString().split('T')[0];
      const endStr = weekDays[6].toISOString().split('T')[0];

      const eventsInWeek = combinedEvents.filter(e => e.date >= startStr && e.date <= endStr);

      return {
          total: eventsInWeek.length,
          meetings: eventsInWeek.filter(e => e.type === 'Toplantı').length,
          transfers: eventsInWeek.filter(e => e.type === 'Şube Transferi').length,
          tasks: eventsInWeek.filter(e => e.isTask).length
      };
  }, [combinedEvents, weekDays]);

  return (
    <div className="flex h-full relative overflow-hidden bg-zinc-950">

        {/* ADD EVENT MODAL */}
        {showAddModal && (
            <div className="fixed inset-0 z-[100] flex justify-center items-center bg-black/80 backdrop-blur-sm p-4 animate-in fade-in">
                <div className="bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col max-h-[90vh]">
                    <div className="p-5 border-b border-zinc-800 flex justify-between items-center bg-zinc-950/80 backdrop-blur">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            {newEventForm.type === 'Şube Transferi' ? <Rocket size={20} className="text-orange-500"/> : <CalendarIcon size={20} className="text-indigo-500"/>}
                            {t('cal.newEvent')}
                        </h3>
                        <button onClick={() => setShowAddModal(false)}><X size={20} className="text-zinc-500 hover:text-white"/></button>
                    </div>
                    <div className="p-6 overflow-y-auto custom-scrollbar flex-1">
                        <form onSubmit={handleSaveEvent} className="space-y-5">
                            {/* Type */}
                            <div>
                                <label className="text-xs text-zinc-400 block mb-1.5">{t('cal.type')}</label>
                                <div className="flex gap-2 overflow-x-auto pb-1">
                                    {['Toplantı', 'Montaj', 'Teslim Tarihi', 'Şube Transferi', 'Diğer'].map(type => (
                                        <button key={type} type="button" onClick={() => setNewEventForm({...newEventForm, type: type as any})}
                                            className={`px-3 py-1.5 rounded-lg text-xs font-medium border whitespace-nowrap transition-all ${newEventForm.type === type ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800'}`}>
                                            {type === 'Şube Transferi' ? t('cal.type.transfer') : type}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Title (If not transfer) */}
                            {newEventForm.type !== 'Şube Transferi' && (
                                <div>
                                    <label className="text-xs text-zinc-400 block mb-1.5">{t('cal.eventTitle')}</label>
                                    <input type="text" required value={newEventForm.title} onChange={e => setNewEventForm({...newEventForm, title: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-white focus:border-indigo-500 outline-none" />
                                </div>
                            )}

                            {/* Transfer Logic */}
                            {newEventForm.type === 'Şube Transferi' && (
                                <div className="p-3 bg-orange-950/20 border border-orange-500/20 rounded-lg">
                                    <label className="text-xs font-bold text-orange-400 block mb-2">{t('cal.targetBranch')}</label>
                                    <div className="flex flex-wrap gap-2">
                                        {Object.values(Branch).map(branch => (
                                            <button key={branch} type="button" onClick={() => setTargetBranch(branch)} className={`px-2 py-1 text-xs rounded border ${targetBranch === branch ? 'bg-orange-600 text-white border-orange-500' : 'bg-zinc-900 text-zinc-400 border-zinc-800'}`}>{branch}</button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Dates */}
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="text-xs text-zinc-400 block mb-1.5">{t('cal.startDate')}</label><input type="date" value={newEventForm.date} onChange={e => setNewEventForm({...newEventForm, date: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-white text-sm"/></div>
                                <div><label className="text-xs text-zinc-400 block mb-1.5">{t('cal.startTime')}</label><input type="time" value={newEventForm.startTime} onChange={e => setNewEventForm({...newEventForm, startTime: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-2 text-white text-sm"/></div>
                            </div>

                            {/* Attendees Selector */}
                            <div className="p-4 bg-zinc-950/50 border border-zinc-800 rounded-xl space-y-3">
                                <label className="text-xs font-medium text-zinc-400 block">{t('cal.branchFilter')}</label>
                                <div className="flex gap-2 flex-wrap">
                                    {Object.values(Branch).map(b => (
                                        <button key={b} type="button" onClick={() => toggleBranchSelection(b)} className={`px-2 py-1 text-[10px] rounded border ${selectedBranches.includes(b) ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-zinc-900 text-zinc-500 border-zinc-800'}`}>{b}</button>
                                    ))}
                                </div>
                                <div className="h-px bg-zinc-800"></div>
                                <label className="text-xs font-medium text-zinc-400 block">{t('cal.attendees')}</label>
                                <div className="flex gap-2 overflow-x-auto pb-1">
                                    {MOCK_EMPLOYEES.filter(e => selectedBranches.length === 0 || selectedBranches.includes(e.branch)).map(emp => (
                                        <div key={emp.id} onClick={() => toggleAttendee(emp.id)} className={`cursor-pointer flex flex-col items-center gap-1 min-w-[50px] p-2 rounded-lg border transition-all ${newEventForm.attendees?.includes(emp.id) ? 'bg-indigo-500/20 border-indigo-500' : 'bg-zinc-900 border-zinc-800'}`}>
                                            <img src={emp.avatarUrl} className="w-8 h-8 rounded-full"/>
                                            <span className="text-[9px] text-zinc-400 truncate w-full text-center">{emp.name.split(' ')[0]}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Footer */}
                            <div className="pt-4 flex gap-3">
                                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-3 bg-zinc-800 text-zinc-400 rounded-xl text-sm">{t('tasks.cancel')}</button>
                                <button type="submit" disabled={isSaving} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg">
                                    {isSaving ? '...' : t('cal.saveEvent')}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        )}

        {/* --- LEFT PANEL: SUMMARY & NAV (HIDDEN ON MOBILE) --- */}
        <div className="w-full md:w-80 bg-zinc-950 border-b md:border-b-0 md:border-r border-zinc-800 flex-col hidden md:flex">
            <div className="p-6 border-b border-zinc-900">
                <h2 className="text-xl font-bold text-white mb-1">Ajanda</h2>
