const DAYS = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];

interface ShiftRow {
    id: string;
    time: string;
    days: string[]; // İsimleri tutar
}

// Hafta formatı: YYYY-MM-DD (Pazartesi günü)
const getMonday = (d: Date) => {
  const date = new Date(d);
  const day = date.getDay();
  const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
  return new Date(date.setDate(diff));
};

// Ana Bileşen
const ShiftSchedule: React.FC = () => {
  const { t, formatDate } = useLanguage();

  // State
  const [activeBranch, setActiveBranch] = useState<Branch>(Branch.MULHEIM);
  const [currentWeekStart, setCurrentWeekStart] = useState<Date>(getMonday(new Date()));
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Veri Yapısı: { "YYYY-MM-DD": { "BranchName": [rows...] } }
  // Not: Artık sadece UI state'i olarak kullanılıyor, veriler DB'den geliyor.
  const [currentRows, setCurrentRows] = useState<ShiftRow[]>([]);

  // Current Helpers
  const weekKey = currentWeekStart.toISOString().split('T')[0];
  const currentWeekEnd = new Date(currentWeekStart);
  currentWeekEnd.setDate(currentWeekEnd.getDate() + 6);

  // Personel Listesi (Şubeye göre filtrelenmiş)
  const branchEmployees = MOCK_EMPLOYEES.filter(e => e.branch === activeBranch);

  // --- EFFECT: FETCH DATA ---
  useEffect(() => {
      fetchWeekData();
  }, [currentWeekStart, activeBranch]);

  const fetchWeekData = async () => {
      setIsLoading(true);
      try {
          const { data, error } = await supabase
              .from('shift_schedules')
              .select('*')
              .eq('week_start_date', weekKey)
              .eq('branch', activeBranch)
              .order('created_at', { ascending: true });

          if (error) throw error;

          if (data && data.length > 0) {
              const formattedRows: ShiftRow[] = data.map((item: any) => ({
                  id: item.id,
                  time: item.time_slot || '',
                  days: item.days || Array(7).fill('')
              }));
              setCurrentRows(formattedRows);
          } else {
              setCurrentRows([]);
          }
      } catch (err) {
          console.error("Vardiya verisi çekilemedi:", err);
      } finally {
          setIsLoading(false);
      }
  };

  // --- HANDLERS ---

  const handleWeekChange = (direction: 'prev' | 'next') => {
      const newDate = new Date(currentWeekStart);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setCurrentWeekStart(newDate);
  };

  const handleAddRow = async () => {
      // Optimistic UI update
      const tempId = `temp-${Date.now()}`;
      const newRow: ShiftRow = {
          id: tempId,
          time: '',
          days: Array(7).fill('')
      };
      setCurrentRows([...currentRows, newRow]);

      try {
          const { data, error } = await supabase
              .from('shift_schedules')
              .insert([{
                  week_start_date: weekKey,
                  branch: activeBranch,
                  time_slot: '',
                  days: Array(7).fill('')
              }])
              .select()
              .single();

          if (error) throw error;

          // Replace temp ID with real DB ID
          setCurrentRows(prev => prev.map(row => row.id === tempId ? { ...row, id: data.id } : row));

      } catch (err) {
          console.error("Satır eklenemedi:", err);
          alert("Satır eklenirken hata oluştu.");
          // Revert optimistic update
          setCurrentRows(prev => prev.filter(row => row.id !== tempId));
      }
  };

  const handleRemoveRow = async (rowId: string) => {
      if(!confirm('Bu satırı silmek istediğinize emin misiniz?')) return;

      // Optimistic Delete
      const backupRows = [...currentRows];
      setCurrentRows(prev => prev.filter(r => r.id !== rowId));

      try {
          const { error } = await supabase
              .from('shift_schedules')
              .delete()
              .eq('id', rowId);

          if (error) throw error;
      } catch (err) {
          console.error("Silme hatası:", err);
          alert("Satır silinemedi.");
          setCurrentRows(backupRows);
      }
  };

  // Debounced Save Logic için yardımcı fonksiyon
  const saveRowToDb = async (row: ShiftRow) => {
      setIsSaving(true);
      try {
          const { error } = await supabase
              .from('shift_schedules')
              .update({
                  time_slot: row.time,
                  days: row.days
              })
              .eq('id', row.id);

          if (error) throw error;
      } catch (err) {
          console.error("Kayıt hatası:", err);
      } finally {
          setIsSaving(false);
      }
  };

  // Debounce ref to prevent too many DB calls
  const debounceTimeout = useRef<any>(null);

  const handleUpdateCell = (rowId: string, dayIndex: number | 'time', value: string) => {
      // 1. Update UI State Immediately
      const updatedRows = currentRows.map(row => {
          if (row.id !== rowId) return row;

          if (dayIndex === 'time') {
              return { ...row, time: value };
          } else {
              const newDays = [...row.days];
              newDays[dayIndex as number] = value;
              return { ...row, days: newDays };
          }
      });
      setCurrentRows(updatedRows);

      // 2. Find the updated row
      const rowToSave = updatedRows.find(r => r.id === rowId);

      // 3. Debounced DB Save
      if (rowToSave) {
          if (debounceTimeout.current) clearTimeout(debounceTimeout.current);

          debounceTimeout.current = setTimeout(() => {
              saveRowToDb(rowToSave);
          }, 1000); // 1 saniye bekle ve kaydet
      }
  };

  const handleCopyNextWeek = async () => {
      if (currentRows.length === 0) return alert("Kopyalanacak veri yok.");

      const nextWeekDate = new Date(currentWeekStart);
      nextWeekDate.setDate(nextWeekDate.getDate() + 7);
      const nextWeekKey = nextWeekDate.toISOString().split('T')[0];

      if (confirm(`Bu planı ${formatDate(nextWeekDate)} haftasına kopyalamak istiyor musunuz?`)) {
          setIsLoading(true);
          try {
              // Prepare payload
              const payload = currentRows.map(row => ({
                  week_start_date: nextWeekKey,
                  branch: activeBranch,
                  time_slot: row.time,
                  days: row.days
              }));

              const { error } = await supabase
                  .from('shift_schedules')
                  .insert(payload);

              if (error) throw error;

              alert("Başarıyla kopyalandı.");
              setCurrentWeekStart(nextWeekDate); // Otomatik geçiş yap ve yükle

          } catch (err) {
              console.error("Kopyalama hatası:", err);
              alert("Kopyalama başarısız.");
              setIsLoading(false); // Sadece hata durumunda kapat, başarılıysa useEffect kapatacak
          }
      }
  };

  return (
    <div className="h-full w-full flex flex-col bg-[#09090b] relative overflow-hidden">

      {/* --- HEADER & CONTROLS --- */}
      <div className="p-4 md:p-6 border-b border-zinc-800 bg-zinc-950/80 backdrop-blur-md sticky top-0 z-20 shrink-0">
          <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">

              {/* BRANCH TABS */}
              <div className="flex items-center gap-2 overflow-x-auto max-w-full pb-2 xl:pb-0 custom-scrollbar w-full xl:w-auto">
                  {Object.values(Branch).map(branch => (
                      <button
                          key={branch}
                          onClick={() => setActiveBranch(branch)}
                          className={`px-4 md:px-6 py-2 md:py-3 rounded-xl text-xs md:text-sm font-bold transition-all whitespace-nowrap border ${
                              activeBranch === branch 
                              ? 'bg-zinc-100 text-black border-white shadow-[0_0_15px_rgba(255,255,255,0.2)] scale-105' 
                              : 'bg-zinc-900 text-zinc-500 border-zinc-800 hover:text-zinc-300 hover:border-zinc-700'
                          }`}
                      >
                          {branch}
                      </button>
                  ))}
              </div>

              {/* RIGHT SIDE: WEEK INFO & CONTROLS */}
              <div className="flex flex-col md:flex-row items-center gap-4 w-full xl:w-auto justify-between xl:justify-end">

                  {/* Hafta Navigasyon */}
                  <div className="flex items-center bg-zinc-900 rounded-xl border border-zinc-800 p-1">
                        <button onClick={() => handleWeekChange('prev')} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronLeft size={20}/></button>
                        <div className="px-4 text-center">
                            <span className="block text-[10px] text-zinc-500 uppercase font-bold tracking-wider">Hafta</span>
                            <span className="block text-xs md:text-sm font-bold text-white whitespace-nowrap">
                                {formatDate(currentWeekStart, { day: 'numeric', month: 'short' })} - {formatDate(currentWeekEnd, { day: 'numeric', month: 'short' })}
                            </span>
                        </div>
                        <button onClick={() => handleWeekChange('next')} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronRight size={20}/></button>
                  </div>

                  <div className="flex items-center gap-2 w-full md:w-auto">
                        <button 
                            onClick={handleCopyNextWeek}
                            title="Gelecek haftaya kopyala"
                            className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-3 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 rounded-xl font-bold transition-all border border-zinc-700"
                        >
                            <Copy size={18} />
                            <span className="hidden md:inline">Kopyala</span>
                        </button>

                        <button 
                            onClick={handleAddRow}
                            className="flex-1 md:flex-none flex items-center justify-center gap-2 px-4 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold shadow-lg shadow-indigo-900/20 transition-all active:scale-95"
                        >
                            <Plus size={18} />
                            <span className="hidden md:inline">Saat Ekle</span>
                            <span className="md:hidden">Ekle</span>
                        </button>
                  </div>
              </div>
          </div>
      </div>

      {/* --- SCROLLABLE TABLE AREA --- */}
      <div className="flex-1 overflow-auto custom-scrollbar p-4 md:p-6">
        <div className="w-full min-w-[1000px] pb-20">
            <div className="rounded-xl shadow-2xl border border-zinc-800 overflow-visible bg-zinc-900 relative min-h-[300px]">

                {isLoading && (
                    <div className="absolute inset-0 z-50 bg-zinc-900/80 backdrop-blur-sm flex items-center justify-center rounded-xl">
                        <Loader2 size={40} className="text-indigo-500 animate-spin" />
                    </div>
                )}

                <table className="w-full border-collapse text-center table-fixed">
                <thead>
                    <tr className="text-white">
                        {/* Time Column Header - Purple */}
                        <th className="w-32 p-4 bg-[#8e7cc3] text-black font-bold text-lg border border-zinc-700/50 sticky left-0 z-10 shadow-[2px_0_5px_rgba(0,0,0,0.5)]">
                            Uhrzeit
                        </th>
                        {/* Days Headers - Dark Red/Burgundy */}
                        {DAYS.map((day) => (
                            <th key={day} className="p-4 bg-[#660000] text-white font-bold text-lg border border-zinc-700/50">
                            {day}
                            </th>
                        ))}
                        <th className="w-16 p-4 bg-zinc-900 border border-zinc-700/50"></th>
                    </tr>
                </thead>
                <tbody className="text-zinc-300">
                    {currentRows.length === 0 && !isLoading ? (
                        <tr>
                            <td colSpan={9} className="p-12 text-center text-zinc-500 italic bg-zinc-900/50">
                                Bu hafta için planlama yapılmamış. Yukarıdan "Saat Ekle" veya "Kopyala" kullanın.
                            </td>
                        </tr>
                    ) : (
                        currentRows.map((row) => (
                        <tr key={row.id} className="hover:bg-zinc-800/30 transition-colors group">
                            {/* Time Slot Cell (Editable Text) */}
                            <td className="p-0 border border-zinc-700/50 bg-zinc-900 sticky left-0 z-10 shadow-[2px_0_5px_rgba(0,0,0,0.5)]">
                                <div className="relative w-full h-full flex items-center justify-center p-2">
                                    <Clock size={14} className="absolute left-2 text-zinc-600 pointer-events-none" />
                                    <input 
                                        type="text" 
                                        value={row.time}
                                        onChange={(e) => handleUpdateCell(row.id, 'time', e.target.value)}
                                        placeholder="00 - 00"
                                        className="w-full h-12 bg-transparent text-center font-bold text-zinc-100 text-lg outline-none focus:bg-zinc-800 transition-colors rounded pl-4 placeholder:text-zinc-700"
                                    />
                                </div>
                            </td>
                            {/* Employee Cells (Dropdown Selector) */}
                            {row.days.map((employeeName, cellIndex) => (
                                <ShiftCell 
                                    key={`${row.id}-${cellIndex}`}
                                    currentValue={employeeName}
                                    employees={branchEmployees}
                                    onChange={(val) => handleUpdateCell(row.id, cellIndex, val)}
                                />
                            ))}
                            {/* Delete Action */}
                            <td className="p-0 border border-zinc-700/50 bg-zinc-900/40 text-center align-middle">
                                <button 
                                    onClick={() => handleRemoveRow(row.id)}
                                    className="p-3 text-zinc-600 hover:text-red-500 transition-colors hover:bg-zinc-800 rounded-lg mx-auto"
                                    title="Satırı Sil"
                                >
                                    <Eraser size={20} />
                                </button>
                            </td>
                        </tr>
                        ))
                    )}
                </tbody>
                </table>
            </div>

            {/* Status Hint */}
            <div className="mt-4 flex justify-end">
                {isSaving ? (
                    <div className="flex items-center gap-2 text-xs text-indigo-400 animate-pulse">
                        <Loader2 size={14} className="animate-spin" /> Kaydediliyor...
                    </div>
                ) : (
                    <div className="flex items-center gap-2 text-xs text-zinc-500">
                        <Check size={14} /> Tüm değişiklikler güncel
                    </div>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

// --- SUB-COMPONENT: Cell Dropdown ---
const ShiftCell: React.FC<{ currentValue: string, employees: Employee[], onChange: (val: string) => void }> = ({ currentValue, employees, onChange }) => {
    const [isOpen, setIsOpen] = useState(false);
    const containerRef = useRef<HTMLTableDataCellElement>(null);

    // Click outside to close
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    return (
        <td ref={containerRef} className="p-0 border border-zinc-700/50 bg-zinc-900/40 relative h-16 w-full">
            <div 
                onClick={() => setIsOpen(!isOpen)}
                className={`w-full h-full flex items-center justify-center cursor-pointer hover:bg-zinc-800/50 transition-colors group ${isOpen ? 'bg-zinc-800' : ''}`}
            >
                <span className={`text-center font-medium text-base md:text-lg select-none truncate px-2 ${currentValue ? 'text-zinc-200' : 'text-zinc-700'}`}>
                    {currentValue || "-"}
                </span>
                <ChevronDown size={12} className="absolute bottom-1 right-1 text-zinc-600 opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>

            {/* DROPDOWN MENU */}
            {isOpen && (
                <div className="absolute top-full left-0 z-50 w-[180px] bg-zinc-900 border border-zinc-700 rounded-xl shadow-2xl max-h-60 overflow-y-auto custom-scrollbar p-1 animate-in fade-in zoom-in-95 origin-top-left">
                    {/* Clear Option */}
                    <button 
                        onClick={() => { onChange(""); setIsOpen(false); }}
                        className="w-full text-left px-3 py-2 text-zinc-500 hover:text-red-400 hover:bg-zinc-800 rounded-lg text-sm flex items-center gap-2"
                    >
                        <Eraser size={14}/> Temizle
                    </button>

                    <div className="h-px bg-zinc-800 my-1"></div>

                    {employees.map(emp => (
                        <button
                            key={emp.id}
                            onClick={() => { onChange(emp.name.split(' ')[0]); setIsOpen(false); }}
                            className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentValue === emp.name.split(' ')[0] ? 'bg-indigo-600 text-white' : 'text-zinc-300 hover:bg-zinc-800'}`}
                        >
                            <img src={emp.avatarUrl} className="w-5 h-5 rounded-full bg-zinc-800" />
                            <span className="truncate">{emp.name.split(' ')[0]}</span>
                            {currentValue === emp.name.split(' ')[0] && <Check size={14} className="ml-auto"/>}
                        </button>
                    ))}

                    {employees.length === 0 && <div className="p-2 text-xs text-zinc-500 text-center">Bu şubede personel yok.</div>}
                </div>
            )}
        </td>
    );
};

