                  <div className="flex items-center gap-2 w-full md:w-auto">
                        <button onClick={handleCopyNextWeek} title="Kopyala" className="p-3 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 rounded-xl font-bold transition-all border border-zinc-700">
