                        {/* MANUEL KAYDET - GÜÇLENDİRİLMİŞ (RENK GÜNCELLENDİ) */}
                        <button 
                            onClick={handleManualSave}
                            disabled={isSaving}
                            className="flex items-center justify-center gap-2 px-6 py-3 bg-blue-600 hover:bg-blue-500 text-white rounded-xl font-bold transition-all border border-blue-500 shadow-lg shadow-blue-900/20 active:scale-95"
                        >
                            {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
                            <span>Kaydet</span>
                        </button>

                        <button onClick={handleAddRow} className="flex items-center justify-center gap-2 px-4 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold shadow-lg shadow-indigo-900/20 transition-all active:scale-95">
                            <Plus size={18} />
                            <span className="hidden md:inline">Ekle</span>
                        </button>
                  </div>
              </div>
          </div>
      </div>

      {/* TABLE */}
      <div className="flex-1 overflow-auto custom-scrollbar p-4 md:p-6">
        <div className="w-full min-w-[1000px] pb-20">
            <div className="rounded-xl shadow-2xl border border-zinc-800 overflow-visible bg-zinc-900 relative min-h-[300px]">

                {isLoading && (
                    <div className="absolute inset-0 z-50 bg-zinc-900/80 backdrop-blur-sm flex items-center justify-center rounded-xl">
                        <Loader2 size={40} className="text-indigo-500 animate-spin" />
                    </div>
                )}

                <table className="w-full border-collapse text-center table-fixed">
                <thead>
                    <tr className="text-white">
                        {/* Time Column Header - Soft Dark Zinc */}
                        <th className="w-32 p-4 bg-zinc-800 text-zinc-300 font-bold text-lg border border-zinc-700/50 sticky left-0 z-10 shadow-[2px_0_5px_rgba(0,0,0,0.5)]">
                            Uhrzeit
                        </th>
                        {/* Days Headers - Soft Dark Zinc (Distinct) */}
                        {DAYS.map((day) => (
                            <th key={day} className="p-4 bg-zinc-900 text-zinc-400 font-bold text-lg border border-zinc-700/50">
                            {day}
                            </th>
                        ))}
                        <th className="w-16 p-4 bg-zinc-900 border border-zinc-700/50"></th>
                    </tr>
                </thead>
                <tbody className="text-zinc-300">
                    {currentRows.length === 0 && !isLoading ? (
                        <tr>
                            <td colSpan={9} className="p-12 text-center text-zinc-500 italic bg-zinc-900/50">
                                Bu hafta için planlama yapılmamış. Yukarıdan "Ekle" veya "Kopyala" kullanın.
                            </td>
                        </tr>
                    ) : (
                        currentRows.map((row) => (
                        <tr key={row.id} className="hover:bg-zinc-800/30 transition-colors group">
                            <td className="p-0 border border-zinc-700/50 bg-zinc-900 sticky left-0 z-10 shadow-[2px_0_5px_rgba(0,0,0,0.5)]">
                                <div className="relative w-full h-full flex items-center justify-center p-2">
                                    <Clock size={14} className="absolute left-2 text-zinc-600 pointer-events-none" />
                                    <input 
                                        type="text" 
                                        value={row.time}
                                        onChange={(e) => handleUpdateCell(row.id, 'time', e.target.value)}
                                        placeholder="00 - 00"
                                        className="w-full h-12 bg-transparent text-center font-bold text-zinc-100 text-lg outline-none focus:bg-zinc-800 transition-colors rounded pl-4 placeholder:text-zinc-700"
                                    />
                                </div>
                            </td>
                            {row.days.map((employeeName, cellIndex) => (
                                <ShiftCell 
                                    key={`${row.id}-${cellIndex}`}
                                    currentValue={employeeName}
                                    employees={branchEmployees}
                                    onChange={(val) => handleUpdateCell(row.id, cellIndex, val)}
                                />
                            ))}
                            <td className="p-0 border border-zinc-700/50 bg-zinc-900/40 text-center align-middle">
                                <button 
                                    onClick={() => handleRemoveRow(row.id)}
                                    className="p-3 text-zinc-600 hover:text-red-500 transition-colors hover:bg-zinc-800 rounded-lg mx-auto"
                                    title="Satırı Sil"
                                >
                                    <Eraser size={20} />
                                </button>
                            </td>
                        </tr>
                        ))
                    )}
                </tbody>
                </table>
            </div>

            <div className="mt-4 flex justify-end">
                {isSaving ? (
                    <div className="flex items-center gap-2 text-xs text-indigo-400 animate-pulse">
                        <Loader2 size={14} className="animate-spin" /> Kaydediliyor...
                    </div>
                ) : (
                    <div className="flex items-center gap-2 text-xs text-zinc-500">
                        <Check size={14} /> Otomatik kaydedildi
                    </div>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

// --- SUB-COMPONENT: Cell Dropdown ---
const ShiftCell: React.FC<{ currentValue: string, employees: Employee[], onChange: (val: string) => void }> = ({ currentValue, employees, onChange }) => {
    const [isOpen, setIsOpen] = useState(false);
    const containerRef = useRef<HTMLTableDataCellElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    return (
        <td ref={containerRef} className="p-0 border border-zinc-700/50 bg-zinc-900/40 relative h-16 w-full">
            <div 
                onClick={() => setIsOpen(!isOpen)}
                className={`w-full h-full flex items-center justify-center cursor-pointer hover:bg-zinc-800/50 transition-colors group ${isOpen ? 'bg-zinc-800' : ''}`}
            >
                <span className={`text-center font-medium text-base md:text-lg select-none truncate px-2 ${currentValue ? 'text-zinc-200' : 'text-zinc-700'}`}>
                    {currentValue || "-"}
                </span>
                <ChevronDown size={12} className="absolute bottom-1 right-1 text-zinc-600 opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>

            {isOpen && (
                <div className="absolute top-full left-0 z-50 w-[180px] bg-zinc-900 border border-zinc-700 rounded-xl shadow-2xl max-h-60 overflow-y-auto custom-scrollbar p-1 animate-in fade-in zoom-in-95 origin-top-left">
                    <button 
                        onClick={() => { onChange(""); setIsOpen(false); }}
                        className="w-full text-left px-3 py-2 text-zinc-500 hover:text-red-400 hover:bg-zinc-800 rounded-lg text-sm flex items-center gap-2"
                    >
                        <Eraser size={14}/> Temizle
                    </button>
                    <div className="h-px bg-zinc-800 my-1"></div>
                    {employees.map(emp => (
                        <button
                            key={emp.id}
                            onClick={() => { onChange(emp.name.split(' ')[0]); setIsOpen(false); }}
                            className={`w-full text-left px-3 py-2 rounded-lg text-sm flex items-center gap-2 transition-colors ${currentValue === emp.name.split(' ')[0] ? 'bg-indigo-600 text-white' : 'text-zinc-300 hover:bg-zinc-800'}`}
                        >
                            <img src={emp.avatarUrl} className="w-5 h-5 rounded-full bg-zinc-800" />
                            <span className="truncate">{emp.name.split(' ')[0]}</span>
                            {currentValue === emp.name.split(' ')[0] && <Check size={14} className="ml-auto"/>}
                        </button>
                    ))}
                    {employees.length === 0 && <div className="p-2 text-xs text-zinc-500 text-center">Bu şubede personel yok.</div>}
                </div>
            )}
        </td>
    );
};

export default ShiftSchedule;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLanguage } from '../lib/i18n';
import { Branch, Employee } from '../types';
import { CalendarRange, Save, Clock, Eraser, ChevronLeft, ChevronRight, Copy, Check, User, Loader2, Filter, Download } from 'lucide-react';
import { MOCK_EMPLOYEES } from '../constants';
import { supabase } from '../lib/supabase';

const DAYS = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];

// Yeni Yapı: Row ID artık Employee ID olacak.
interface RosterRow {
    employeeId: string;
    shifts: string[]; // 7 günlük vardiya saatleri (Örn: "09:00-17:00")
    dbId?: string; // Varsa DB'deki kayıt ID'si (Update için)
}

const getMonday = (d: Date) => {
  const date = new Date(d);
  const day = date.getDay();
  const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
  return new Date(date.setDate(diff));
};

const ShiftSchedule: React.FC = () => {
  const { t, formatDate } = useLanguage();

  // State
  const [activeBranch, setActiveBranch] = useState<Branch>(Branch.MULHEIM);
  const [currentWeekStart, setCurrentWeekStart] = useState<Date>(getMonday(new Date()));
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Roster Data
  const [rosterData, setRosterData] = useState<RosterRow[]>([]);

  const weekKey = `${currentWeekStart.getFullYear()}-${String(currentWeekStart.getMonth() + 1).padStart(2, '0')}-${String(currentWeekStart.getDate()).padStart(2, '0')}`;

  const currentWeekEnd = new Date(currentWeekStart);
  currentWeekEnd.setDate(currentWeekEnd.getDate() + 6);

  const branchEmployees = MOCK_EMPLOYEES.filter(e => e.branch === activeBranch);

  useEffect(() => {
      fetchWeekData();

      const channel = supabase.channel('shift-realtime')
          .on('postgres_changes', { event: '*', schema: 'public', table: 'shift_schedules' }, (payload) => {
                  const newData = payload.new as any;
                  if ((newData && newData.branch === activeBranch && newData.week_start_date === weekKey) || payload.eventType === 'DELETE') {
                      if (!debounceTimeout.current) fetchWeekData();
                  }
              }
          )
          .subscribe();

      return () => { supabase.removeChannel(channel); };
  }, [currentWeekStart, activeBranch, weekKey]);

  const fetchWeekData = async () => {
      if (!debounceTimeout.current) setIsLoading(true);

      try {
          // Bu hafta ve bu şube için kayıtları çek
          const { data, error } = await supabase
              .from('shift_schedules')
              .select('*')
              .eq('week_start_date', weekKey)
              .eq('branch', activeBranch);

          if (error) throw error;

          // Şubedeki her personel için bir satır oluştur
          const rows: RosterRow[] = branchEmployees.map(emp => {
              // DB'de bu personel için kayıt var mı?
              // NOT: time_slot sütununu "Employee ID" olarak kullanıyoruz (Migration yapmadan yapıyı değiştirdik)
              const existingRecord = data?.find((r: any) => r.time_slot === emp.id);

              return {
                  employeeId: emp.id,
                  shifts: existingRecord?.days || Array(7).fill(''),
                  dbId: existingRecord?.id
              };
          });

          setRosterData(rows);

      } catch (err: any) {
          console.error("Vardiya verisi çekilemedi:", err);
      } finally {
          setIsLoading(false);
      }
  };

  const handleWeekChange = (direction: 'prev' | 'next') => {
      const newDate = new Date(currentWeekStart);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setCurrentWeekStart(newDate);
  };

  const debounceTimeout = useRef<any>(null);

  // Otomatik Kayıt
  const saveRowToDb = async (row: RosterRow) => {
      setIsSaving(true);
      try {
          const payload = {
              week_start_date: weekKey,
              branch: String(activeBranch),
              time_slot: row.employeeId, // ID'yi time_slot kolonuna saklıyoruz
              days: row.shifts
          };

          if (row.dbId) {
              await supabase.from('shift_schedules').update(payload).eq('id', row.dbId);
          } else {
              const { data, error } = await supabase.from('shift_schedules').insert([payload]).select().single();
              if(!error && data) {
                  setRosterData(prev => prev.map(r => r.employeeId === row.employeeId ? { ...r, dbId: data.id } : r));
              }
          }
      } catch (err) {
          console.error("Otomatik kayıt hatası:", err);
      } finally {
          setIsSaving(false);
      }
  };

  const handleShiftChange = (employeeId: string, dayIndex: number, value: string) => {
      const updatedRows = rosterData.map(row => {
          if (row.employeeId !== employeeId) return row;
          const newShifts = [...row.shifts];
          newShifts[dayIndex] = value;
          return { ...row, shifts: newShifts };
      });
      setRosterData(updatedRows);

      const rowToSave = updatedRows.find(r => r.employeeId === employeeId);
      if (rowToSave) {
          if (debounceTimeout.current) clearTimeout(debounceTimeout.current);
          debounceTimeout.current = setTimeout(() => {
              saveRowToDb(rowToSave);
          }, 800); 
      }
  };

  const handleManualSave = async () => {
      setIsSaving(true);
      try {
          const promises = rosterData.map(row => saveRowToDb(row));
          await Promise.all(promises);
          alert("Tüm değişiklikler kaydedildi.");
      } catch (err) {
          console.error(err);
      } finally {
          setIsSaving(false);
      }
  };

  const handleCopyNextWeek = async () => {
      if (rosterData.every(r => r.shifts.every(s => !s))) return alert("Kopyalanacak veri yok.");

      const nextWeekDate = new Date(currentWeekStart);
      nextWeekDate.setDate(nextWeekDate.getDate() + 7);
      const nextWeekKey = `${nextWeekDate.getFullYear()}-${String(nextWeekDate.getMonth() + 1).padStart(2, '0')}-${String(nextWeekDate.getDate()).padStart(2, '0')}`;

      if (confirm(`Bu planı ${formatDate(nextWeekDate)} haftasına kopyalamak istiyor musunuz?`)) {
          setIsLoading(true);
          try {
              const payload = rosterData.map(row => ({
                  week_start_date: nextWeekKey,
                  branch: String(activeBranch),
                  time_slot: row.employeeId,
                  days: row.shifts
              })).filter(p => p.days.some(d => d !== "")); // Sadece dolu olanları kopyala

              if(payload.length > 0) {
                  const { error } = await supabase.from('shift_schedules').insert(payload);
                  if (error) throw error;
                  alert("Başarıyla kopyalandı.");
                  setCurrentWeekStart(nextWeekDate);
              }
          } catch (err: any) {
              console.error(err);
              alert(`Hata: ${err.message}`);
          } finally {
              setIsLoading(false);
          }
      }
  };

  const clearRow = (employeeId: string) => {
      if(!confirm("Bu personelin vardiyalarını temizlemek istiyor musunuz?")) return;
      const emptyShifts = Array(7).fill('');
      const updatedRows = rosterData.map(r => r.employeeId === employeeId ? { ...r, shifts: emptyShifts } : r);
      setRosterData(updatedRows);

      const row = updatedRows.find(r => r.employeeId === employeeId);
      if(row) saveRowToDb(row);
  };

  return (
    <div className="h-full w-full flex flex-col bg-[#09090b] relative overflow-hidden">

      {/* HEADER CONTROLS */}
      <div className="p-4 border-b border-zinc-800 bg-zinc-950/80 backdrop-blur-md sticky top-0 z-30 shrink-0">
          <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">

              {/* Branch Selector */}
              <div className="flex items-center gap-2 overflow-x-auto max-w-full pb-1 xl:pb-0 custom-scrollbar">
                  {Object.values(Branch).map(branch => (
                      <button
                          key={branch}
                          onClick={() => setActiveBranch(branch)}
                          className={`px-5 py-2.5 rounded-xl text-sm font-bold transition-all whitespace-nowrap border ${
                              activeBranch === branch 
                              ? 'bg-zinc-100 text-black border-white shadow-[0_0_15px_rgba(255,255,255,0.2)]' 
                              : 'bg-zinc-900 text-zinc-500 border-zinc-800 hover:text-zinc-300 hover:border-zinc-700'
                          }`}
                      >
                          {branch}
                      </button>
                  ))}
              </div>

              {/* Actions */}
              <div className="flex flex-col md:flex-row items-center gap-4 w-full xl:w-auto justify-between xl:justify-end">

                  {/* Week Nav */}
                  <div className="flex items-center bg-zinc-900 rounded-xl border border-zinc-800 p-1 shadow-sm">
                        <button onClick={() => handleWeekChange('prev')} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronLeft size={20}/></button>
                        <div className="px-4 text-center min-w-[140px]">
                            <span className="block text-[10px] text-zinc-500 uppercase font-bold tracking-wider">Hafta</span>
                            <span className="block text-sm font-bold text-white whitespace-nowrap">
                                {formatDate(currentWeekStart, { day: 'numeric', month: 'short' })} - {formatDate(currentWeekEnd, { day: 'numeric', month: 'short' })}
                            </span>
                        </div>
                        <button onClick={() => handleWeekChange('next')} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronRight size={20}/></button>
                  </div>

                  <div className="flex items-center gap-3 w-full md:w-auto">
                        <button onClick={handleCopyNextWeek} title="Sonraki Haftaya Kopyala" className="p-3 bg-zinc-900 hover:bg-zinc-800 text-zinc-400 hover:text-white rounded-xl font-bold transition-all border border-zinc-800">
                            <Copy size={18} />
                        </button>

                        <button 
                            onClick={handleManualSave}
                            disabled={isSaving}
                            className="flex items-center justify-center gap-2 px-6 py-3 bg-blue-600 hover:bg-blue-500 text-white rounded-xl font-bold transition-all border border-blue-500 shadow-lg shadow-blue-900/20 active:scale-95 min-w-[120px]"
                        >
                            {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
                            <span>{isSaving ? '...' : 'Kaydet'}</span>
                        </button>
                  </div>
              </div>
          </div>
      </div>

      {/* ROSTER TABLE (Horizontal Layout) */}
      <div className="flex-1 overflow-auto custom-scrollbar bg-zinc-950 p-0 md:p-4">
        <div className="min-w-[1200px] h-full pb-20"> {/* Fixed min-width for horizontal scroll on small screens */}
            <div className="rounded-xl border border-zinc-800 bg-zinc-900 overflow-hidden shadow-2xl relative">

                {isLoading && (
                    <div className="absolute inset-0 z-50 bg-zinc-950/80 backdrop-blur-sm flex items-center justify-center">
                        <Loader2 size={40} className="text-blue-500 animate-spin" />
                    </div>
                )}

                <table className="w-full border-collapse table-fixed">
                    <thead>
                        <tr>
                            {/* Sticky Employee Column Header */}
                            <th className="w-64 p-4 bg-zinc-900 text-left text-zinc-400 font-bold text-sm border-b border-r border-zinc-800 sticky left-0 z-20 shadow-[4px_0_10px_rgba(0,0,0,0.3)] uppercase tracking-wider">
                                <div className="flex items-center gap-2">
                                    <User size={16} /> Personel
                                </div>
                            </th>

                            {/* Days Headers */}
                            {DAYS.map((day, idx) => {
                                const d = new Date(currentWeekStart);
                                d.setDate(d.getDate() + idx);
                                const isToday = new Date().toDateString() === d.toDateString();

                                return (
                                    <th key={day} className={`p-4 text-center border-b border-r border-zinc-800/50 last:border-r-0 ${isToday ? 'bg-blue-900/20 text-blue-200' : 'bg-zinc-900 text-zinc-400'}`}>
                                        <div className="flex flex-col items-center">
                                            <span className="text-xs font-bold uppercase tracking-wider mb-1">{day.slice(0,3)}</span>
                                            <span className={`text-lg font-light ${isToday ? 'text-white' : 'text-zinc-500'}`}>{d.getDate()}</span>
                                        </div>
                                    </th>
                                );
                            })}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-800/50">
                        {rosterData.length === 0 ? (
                            <tr>
                                <td colSpan={8} className="p-12 text-center text-zinc-500 italic bg-zinc-950">
                                    Bu şubede görüntülenecek personel bulunamadı.
                                </td>
                            </tr>
                        ) : (
                            rosterData.map((row) => {
                                const emp = branchEmployees.find(e => e.id === row.employeeId);
                                if(!emp) return null;

                                return (
                                    <tr key={row.employeeId} className="group hover:bg-zinc-800/30 transition-colors">
                                        {/* Employee Cell (Sticky) */}
                                        <td className="p-3 bg-zinc-950 border-r border-zinc-800 sticky left-0 z-10 shadow-[4px_0_10px_rgba(0,0,0,0.3)] group-hover:bg-zinc-900 transition-colors">
                                            <div className="flex items-center gap-3">
                                                <div className="relative">
                                                    <img src={emp.avatarUrl} className="w-10 h-10 rounded-full border border-zinc-800 bg-zinc-900 object-cover" />
                                                    <div className="absolute -bottom-1 -right-1 bg-zinc-900 rounded-full p-0.5">
                                                        <div className="w-2.5 h-2.5 rounded-full bg-green-500 border border-zinc-900"></div>
                                                    </div>
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <div className="text-sm font-bold text-zinc-200 truncate">{emp.name}</div>
                                                    <div className="text-[10px] text-zinc-500 truncate flex justify-between items-center">
                                                        <span>{emp.role}</span>
                                                        <button onClick={() => clearRow(emp.id)} className="opacity-0 group-hover:opacity-100 hover:text-red-400 transition-opacity" title="Temizle">
                                                            <Eraser size={12}/>
                                                        </button>
                                                    </div>
                                                </div>
                                            </div>
                                        </td>

                                        {/* Shift Inputs */}
                                        {row.shifts.map((shift, dayIdx) => (
                                            <td key={dayIdx} className="p-0 border-r border-zinc-800/30 last:border-r-0 relative">
                                                <input
                                                    type="text"
                                                    value={shift}
                                                    onChange={(e) => handleShiftChange(emp.id, dayIdx, e.target.value)}
                                                    placeholder="-"
                                                    className={`w-full h-14 bg-transparent text-center text-sm font-medium focus:bg-zinc-800 focus:text-white outline-none transition-colors placeholder:text-zinc-700 ${shift ? 'text-zinc-200' : 'text-zinc-600'}`}
                                                />
                                                {/* Visual Indicator for Filled Shifts */}
                                                {shift && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-blue-600/50"></div>}
                                            </td>
                                        ))}
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>

            {/* Quick Status Bar */}
            <div className="mt-4 flex items-center justify-between px-2 text-xs text-zinc-500">
                <div className="flex gap-4">
                    <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-green-500"></div> Aktif</span>
                    <span className="flex items-center gap-1"><Clock size={12}/> Otomatik Kayıt</span>
                </div>
                <div>Top. {rosterData.length} Personel</div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default ShiftSchedule;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLanguage } from '../lib/i18n';
import { Branch, Employee, Role } from '../types';
import { CalendarRange, Save, Clock, Eraser, ChevronLeft, ChevronRight, Copy, Check, User, Loader2, Filter, Download } from 'lucide-react';
import { MOCK_EMPLOYEES } from '../constants';
import { supabase } from '../lib/supabase';

const DAYS = ['Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag', 'Sonntag'];

// Yeni Yapı: Row ID artık Employee ID olacak.
interface RosterRow {
    employeeId: string;
    shifts: string[]; // 7 günlük vardiya saatleri (Örn: "09:00-17:00")
    dbId?: string; // Varsa DB'deki kayıt ID'si (Update için)
}

interface ShiftScheduleProps {
    currentUser: Employee;
}

const getMonday = (d: Date) => {
  const date = new Date(d);
  const day = date.getDay();
  const diff = date.getDate() - day + (day === 0 ? -6 : 1); 
  return new Date(date.setDate(diff));
};

const ShiftSchedule: React.FC<ShiftScheduleProps> = ({ currentUser }) => {
  const { t, formatDate } = useLanguage();

  // State
  const [activeBranch, setActiveBranch] = useState<Branch>(Branch.MULHEIM);
  const [currentWeekStart, setCurrentWeekStart] = useState<Date>(getMonday(new Date()));
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Roster Data
  const [rosterData, setRosterData] = useState<RosterRow[]>([]);

  const weekKey = `${currentWeekStart.getFullYear()}-${String(currentWeekStart.getMonth() + 1).padStart(2, '0')}-${String(currentWeekStart.getDate()).padStart(2, '0')}`;

  const currentWeekEnd = new Date(currentWeekStart);
  currentWeekEnd.setDate(currentWeekEnd.getDate() + 6);

  // LOGIC CHANGE: Filtreleme
  // Eğer Admin ise şubedeki herkesi gör, Personel ise sadece kendini gör (eğer o şubedeyse)
  const branchEmployees = MOCK_EMPLOYEES.filter(e => {
      const isInBranch = e.branch === activeBranch;
      if (currentUser.role === Role.ADMIN) {
          return isInBranch;
      }
      return isInBranch && e.id === currentUser.id;
  });

  useEffect(() => {
      fetchWeekData();

      const channel = supabase.channel('shift-realtime')
          .on('postgres_changes', { event: '*', schema: 'public', table: 'shift_schedules' }, (payload) => {
                  const newData = payload.new as any;
                  if ((newData && newData.branch === activeBranch && newData.week_start_date === weekKey) || payload.eventType === 'DELETE') {
                      if (!debounceTimeout.current) fetchWeekData();
                  }
              }
          )
          .subscribe();

      return () => { supabase.removeChannel(channel); };
  }, [currentWeekStart, activeBranch, weekKey, currentUser]);

  const fetchWeekData = async () => {
      if (!debounceTimeout.current) setIsLoading(true);

      try {
          // Bu hafta ve bu şube için kayıtları çek
          const { data, error } = await supabase
              .from('shift_schedules')
              .select('*')
              .eq('week_start_date', weekKey)
              .eq('branch', activeBranch);

          if (error) throw error;

          // Şubedeki her personel için bir satır oluştur
          const rows: RosterRow[] = branchEmployees.map(emp => {
              // DB'de bu personel için kayıt var mı?
              // NOT: time_slot sütununu "Employee ID" olarak kullanıyoruz
              const existingRecord = data?.find((r: any) => r.time_slot === emp.id);

              return {
                  employeeId: emp.id,
                  shifts: existingRecord?.days || Array(7).fill(''),
                  dbId: existingRecord?.id
              };
          });

          setRosterData(rows);

      } catch (err: any) {
          console.error("Vardiya verisi çekilemedi:", err);
      } finally {
          setIsLoading(false);
      }
  };

  const handleWeekChange = (direction: 'prev' | 'next') => {
      const newDate = new Date(currentWeekStart);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setCurrentWeekStart(newDate);
  };

  const debounceTimeout = useRef<any>(null);

  // Otomatik Kayıt
  const saveRowToDb = async (row: RosterRow) => {
      setIsSaving(true);
      try {
          const payload = {
              week_start_date: weekKey,
              branch: String(activeBranch),
              time_slot: row.employeeId, // ID'yi time_slot kolonuna saklıyoruz
              days: row.shifts
          };

          if (row.dbId) {
              await supabase.from('shift_schedules').update(payload).eq('id', row.dbId);
          } else {
              const { data, error } = await supabase.from('shift_schedules').insert([payload]).select().single();
              if(!error && data) {
                  setRosterData(prev => prev.map(r => r.employeeId === row.employeeId ? { ...r, dbId: data.id } : r));
              }
          }
      } catch (err) {
          console.error("Otomatik kayıt hatası:", err);
      } finally {
          setIsSaving(false);
      }
  };

  const handleShiftChange = (employeeId: string, dayIndex: number, value: string) => {
      const updatedRows = rosterData.map(row => {
          if (row.employeeId !== employeeId) return row;
          const newShifts = [...row.shifts];
          newShifts[dayIndex] = value;
          return { ...row, shifts: newShifts };
      });
      setRosterData(updatedRows);

      const rowToSave = updatedRows.find(r => r.employeeId === employeeId);
      if (rowToSave) {
          if (debounceTimeout.current) clearTimeout(debounceTimeout.current);
          debounceTimeout.current = setTimeout(() => {
              saveRowToDb(rowToSave);
          }, 800); 
      }
  };

  const handleManualSave = async () => {
      setIsSaving(true);
      try {
          const promises = rosterData.map(row => saveRowToDb(row));
          await Promise.all(promises);
          alert("Tüm değişiklikler kaydedildi.");
      } catch (err) {
          console.error(err);
      } finally {
          setIsSaving(false);
      }
  };

  const handleCopyNextWeek = async () => {
      if (rosterData.every(r => r.shifts.every(s => !s))) return alert("Kopyalanacak veri yok.");

      const nextWeekDate = new Date(currentWeekStart);
      nextWeekDate.setDate(nextWeekDate.getDate() + 7);
      const nextWeekKey = `${nextWeekDate.getFullYear()}-${String(nextWeekDate.getMonth() + 1).padStart(2, '0')}-${String(nextWeekDate.getDate()).padStart(2, '0')}`;

      if (confirm(`Bu planı ${formatDate(nextWeekDate)} haftasına kopyalamak istiyor musunuz?`)) {
          setIsLoading(true);
          try {
              const payload = rosterData.map(row => ({
                  week_start_date: nextWeekKey,
                  branch: String(activeBranch),
                  time_slot: row.employeeId,
                  days: row.shifts
              })).filter(p => p.days.some(d => d !== "")); // Sadece dolu olanları kopyala

              if(payload.length > 0) {
                  const { error } = await supabase.from('shift_schedules').insert(payload);
                  if (error) throw error;
                  alert("Başarıyla kopyalandı.");
                  setCurrentWeekStart(nextWeekDate);
              }
          } catch (err: any) {
              console.error(err);
              alert(`Hata: ${err.message}`);
          } finally {
              setIsLoading(false);
          }
      }
  };

  const clearRow = (employeeId: string) => {
      if(!confirm("Bu personelin vardiyalarını temizlemek istiyor musunuz?")) return;
      const emptyShifts = Array(7).fill('');
      const updatedRows = rosterData.map(r => r.employeeId === employeeId ? { ...r, shifts: emptyShifts } : r);
      setRosterData(updatedRows);

      const row = updatedRows.find(r => r.employeeId === employeeId);
      if(row) saveRowToDb(row);
  };

  return (
    <div className="h-full w-full flex flex-col bg-[#09090b] relative overflow-hidden">

      {/* HEADER CONTROLS */}
      <div className="p-4 border-b border-zinc-800 bg-zinc-950/80 backdrop-blur-md sticky top-0 z-30 shrink-0">
          <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-6">

              {/* Branch Selector */}
              <div className="flex items-center gap-2 overflow-x-auto max-w-full pb-1 xl:pb-0 custom-scrollbar">
                  {Object.values(Branch).map(branch => (
                      <button
                          key={branch}
                          onClick={() => setActiveBranch(branch)}
                          className={`px-5 py-2.5 rounded-xl text-sm font-bold transition-all whitespace-nowrap border ${
                              activeBranch === branch 
                              ? 'bg-zinc-100 text-black border-white shadow-[0_0_15px_rgba(255,255,255,0.2)]' 
                              : 'bg-zinc-900 text-zinc-500 border-zinc-800 hover:text-zinc-300 hover:border-zinc-700'
                          }`}
                      >
                          {branch}
                      </button>
                  ))}
              </div>

              {/* Actions */}
              <div className="flex flex-col md:flex-row items-center gap-4 w-full xl:w-auto justify-between xl:justify-end">

                  {/* Week Nav */}
                  <div className="flex items-center bg-zinc-900 rounded-xl border border-zinc-800 p-1 shadow-sm">
                        <button onClick={() => handleWeekChange('prev')} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronLeft size={20}/></button>
                        <div className="px-4 text-center min-w-[140px]">
                            <span className="block text-[10px] text-zinc-500 uppercase font-bold tracking-wider">Hafta</span>
                            <span className="block text-sm font-bold text-white whitespace-nowrap">
                                {formatDate(currentWeekStart, { day: 'numeric', month: 'short' })} - {formatDate(currentWeekEnd, { day: 'numeric', month: 'short' })}
                            </span>
                        </div>
                        <button onClick={() => handleWeekChange('next')} className="p-2 hover:bg-zinc-800 rounded-lg text-zinc-400 hover:text-white transition-colors"><ChevronRight size={20}/></button>
                  </div>

                  <div className="flex items-center gap-3 w-full md:w-auto">
                        <button onClick={handleCopyNextWeek} title="Sonraki Haftaya Kopyala" className="p-3 bg-zinc-900 hover:bg-zinc-800 text-zinc-400 hover:text-white rounded-xl font-bold transition-all border border-zinc-800">
                            <Copy size={18} />
                        </button>

                        <button 
                            onClick={handleManualSave}
                            disabled={isSaving}
                            className="flex items-center justify-center gap-2 px-6 py-3 bg-blue-600 hover:bg-blue-500 text-white rounded-xl font-bold transition-all border border-blue-500 shadow-lg shadow-blue-900/20 active:scale-95 min-w-[120px]"
                        >
                            {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
                            <span>{isSaving ? '...' : 'Kaydet'}</span>
                        </button>
                  </div>
              </div>
          </div>
      </div>

      {/* ROSTER TABLE (Horizontal Layout) */}
      <div className="flex-1 overflow-auto custom-scrollbar bg-zinc-950 p-0 md:p-4">
        <div className="min-w-[1200px] h-full pb-20"> {/* Fixed min-width for horizontal scroll on small screens */}
            <div className="rounded-xl border border-zinc-800 bg-zinc-900 overflow-hidden shadow-2xl relative">

                {isLoading && (
                    <div className="absolute inset-0 z-50 bg-zinc-950/80 backdrop-blur-sm flex items-center justify-center">
                        <Loader2 size={40} className="text-blue-500 animate-spin" />
                    </div>
                )}

                <table className="w-full border-collapse table-fixed">
                    <thead>
                        <tr>
                            {/* Sticky Employee Column Header */}
                            <th className="w-64 p-4 bg-zinc-900 text-left text-zinc-400 font-bold text-sm border-b border-r border-zinc-800 sticky left-0 z-20 shadow-[4px_0_10px_rgba(0,0,0,0.3)] uppercase tracking-wider">
                                <div className="flex items-center gap-2">
                                    <User size={16} /> Personel
                                </div>
                            </th>

                            {/* Days Headers */}
                            {DAYS.map((day, idx) => {
                                const d = new Date(currentWeekStart);
                                d.setDate(d.getDate() + idx);
                                const isToday = new Date().toDateString() === d.toDateString();

                                return (
                                    <th key={day} className={`p-4 text-center border-b border-r border-zinc-800/50 last:border-r-0 ${isToday ? 'bg-blue-900/20 text-blue-200' : 'bg-zinc-900 text-zinc-400'}`}>
                                        <div className="flex flex-col items-center">
                                            <span className="text-xs font-bold uppercase tracking-wider mb-1">{day.slice(0,3)}</span>
                                            <span className={`text-lg font-light ${isToday ? 'text-white' : 'text-zinc-500'}`}>{d.getDate()}</span>
                                        </div>
                                    </th>
                                );
                            })}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-800/50">
                        {rosterData.length === 0 ? (
                            <tr>
                                <td colSpan={8} className="p-12 text-center text-zinc-500 italic bg-zinc-950">
                                    Bu şubede görüntülenecek personel bulunamadı.
                                </td>
                            </tr>
                        ) : (
                            rosterData.map((row) => {
                                const emp = branchEmployees.find(e => e.id === row.employeeId);
                                if(!emp) return null;

                                return (
                                    <tr key={row.employeeId} className="group hover:bg-zinc-800/30 transition-colors">
                                        {/* Employee Cell (Sticky) */}
                                        <td className="p-3 bg-zinc-950 border-r border-zinc-800 sticky left-0 z-10 shadow-[4px_0_10px_rgba(0,0,0,0.3)] group-hover:bg-zinc-900 transition-colors">
                                            <div className="flex items-center gap-3">
                                                <div className="relative">
                                                    <img src={emp.avatarUrl} className="w-10 h-10 rounded-full border border-zinc-800 bg-zinc-900 object-cover" />
                                                    <div className="absolute -bottom-1 -right-1 bg-zinc-900 rounded-full p-0.5">
                                                        <div className="w-2.5 h-2.5 rounded-full bg-green-500 border border-zinc-900"></div>
                                                    </div>
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    <div className="text-sm font-bold text-zinc-200 truncate">{emp.name}</div>
                                                    <div className="text-[10px] text-zinc-500 truncate flex justify-between items-center">
                                                        <span>{emp.role}</span>
                                                        <button onClick={() => clearRow(emp.id)} className="opacity-0 group-hover:opacity-100 hover:text-red-400 transition-opacity" title="Temizle">
                                                            <Eraser size={12}/>
                                                        </button>
                                                    </div>
                                                </div>
                                            </div>
                                        </td>

                                        {/* Shift Inputs */}
                                        {row.shifts.map((shift, dayIdx) => (
                                            <td key={dayIdx} className="p-0 border-r border-zinc-800/30 last:border-r-0 relative">
                                                <input
                                                    type="text"
                                                    value={shift}
                                                    onChange={(e) => handleShiftChange(emp.id, dayIdx, e.target.value)}
                                                    placeholder="-"
                                                    className={`w-full h-14 bg-transparent text-center text-sm font-medium focus:bg-zinc-800 focus:text-white outline-none transition-colors placeholder:text-zinc-700 ${shift ? 'text-zinc-200' : 'text-zinc-600'}`}
                                                />
                                                {/* Visual Indicator for Filled Shifts */}
                                                {shift && <div className="absolute bottom-0 left-0 w-full h-0.5 bg-blue-600/50"></div>}
                                            </td>
                                        ))}
                                    </tr>
                                );
                            })
                        )}
                    </tbody>
                </table>
            </div>

            {/* Quick Status Bar */}
            <div className="mt-4 flex items-center justify-between px-2 text-xs text-zinc-500">
                <div className="flex gap-4">
                    <span className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-green-500"></div> Aktif</span>
                    <span className="flex items-center gap-1"><Clock size={12}/> Otomatik Kayıt</span>
                </div>
                <div>Top. {rosterData.length} Personel</div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default ShiftSchedule;

import React, { useState, useMemo, useEffect } from 'react';
import { MOCK_EMPLOYEES } from '../constants';
import { Branch, Employee, Role, CalendarEvent, Task } from '../types';
import { Plus, X, Calendar as CalendarIcon, Clock, MapPin, Users, Save, Building2, CheckCircle2, AlignLeft, Trash2, ChevronLeft, ChevronRight, AlertTriangle, CheckSquare, Loader2, Rocket, ArrowRightLeft, CalendarRange, MoreHorizontal, Filter, List } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';

interface CalendarProps {
    currentUser: Employee;
}

interface DisplayEvent extends CalendarEvent {
    isTask?: boolean;
    isShift?: boolean;
    status?: string;
}

const Calendar: React.FC<CalendarProps> = ({ currentUser }) => {
  // --- STATE ---
  const [viewDate, setViewDate] = useState(new Date()); // Haftanın referans günü

  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const { t, formatDate, language } = useLanguage();

  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [shifts, setShifts] = useState<any[]>([]); // New Shift State

  // Modal & Selection
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<DisplayEvent | null>(null);

  // Filters
  const [selectedBranches, setSelectedBranches] = useState<Branch[]>([]);
  const [targetBranch, setTargetBranch] = useState<Branch>(Branch.DOM);

  // Form
  const [newEventForm, setNewEventForm] = useState<Partial<CalendarEvent>>({
      title: '',
      type: 'Toplantı',
      date: new Date().toISOString().split('T')[0],
      endDate: new Date().toISOString().split('T')[0], 
      startTime: '09:00',
      endTime: '10:00',
      attendees: [],
      description: ''
  });

  // --- DATA FETCHING ---
  useEffect(() => {
    const fetchData = async () => {
        setIsLoading(true);
        try {
            // 1. Events
            let eventQuery = supabase.from('calendar_events').select('*');
            if (currentUser.role !== Role.ADMIN) {
                eventQuery = eventQuery.contains('attendees', [currentUser.id]);
            }
            const { data: eventData } = await eventQuery;
            if (eventData) {
                const dbEvents: CalendarEvent[] = eventData.map((e: any) => ({
                    id: e.id, title: e.title, type: e.type, date: e.date,
                    endDate: e.end_date || e.date, startTime: e.start_time, endTime: e.end_time,
                    attendees: e.attendees || [], description: e.description
                }));
                setEvents(dbEvents);
            }

            // 2. Tasks
            let taskQuery = supabase.from('tasks').select('*');
            if (currentUser.role !== Role.ADMIN) {
                taskQuery = taskQuery.contains('assigned_to', [currentUser.id]);
            }
            const { data: taskData } = await taskQuery;
            if(taskData) {
                 const dbTasks: Task[] = taskData.map((t: any) => ({
                    id: t.id, title: t.title, description: t.description,
                    assignedTo: t.assigned_to || [], dueDate: t.due_date,
                    priority: t.priority, status: t.status, progress: t.progress, checklist: t.checklist || []
                }));
                setTasks(dbTasks);
            }

            // 3. Shifts (Vardiyalar) - Personelin kendi vardiyası
            // Note: time_slot column holds Employee ID in new schema
            const { data: shiftData } = await supabase
                .from('shift_schedules')
                .select('*')
                .eq('time_slot', currentUser.id);

            if (shiftData) {
                setShifts(shiftData);
            }

        } catch (e) {
            console.log("Error:", e);
        } finally {
            setIsLoading(false);
        }
    };
    fetchData();
  }, [currentUser]); 

  // --- LOGIC ---
  const combinedEvents = useMemo((): DisplayEvent[] => {
      const filteredEvents = currentUser.role === Role.ADMIN ? events : events.filter(evt => evt.attendees.includes(currentUser.id));
      const filteredTasks = currentUser.role === Role.ADMIN ? tasks : tasks.filter(t => t.assignedTo.includes(currentUser.id));

      const taskEvents: DisplayEvent[] = filteredTasks.map(t => ({
          id: t.id, title: t.title, type: 'Diğer', date: t.dueDate, endDate: t.dueDate,
          startTime: '09:00', endTime: '18:00', attendees: t.assignedTo, description: t.description,
          isTask: true, status: t.status
      }));

      // Generate Shift Events from Roster Data
      const shiftEvents: DisplayEvent[] = shifts.flatMap(schedule => {
          const start = new Date(schedule.week_start_date);
          return schedule.days.map((shiftTime: string, index: number) => {
              if (!shiftTime) return null;

              const eventDate = new Date(start);
              eventDate.setDate(eventDate.getDate() + index);
              const dateStr = eventDate.toISOString().split('T')[0];

              // Basit parse (örn: "09:00 - 17:00" veya "09:00")
              const parts = shiftTime.split('-');
              const sTime = parts[0]?.trim() || '08:00';
              const eTime = parts[1]?.trim() || '18:00';

              return {
                  id: `shift_${schedule.id}_${index}`,
                  title: `Vardiya: ${shiftTime}`,
                  type: 'Diğer', 
                  date: dateStr,
                  endDate: dateStr,
                  startTime: sTime,
                  endTime: eTime,
                  attendees: [currentUser.id],
                  description: `Şube: ${schedule.branch}`,
                  isShift: true
              } as DisplayEvent;
          }).filter(Boolean) as DisplayEvent[];
      });

      return [...(filteredEvents as DisplayEvent[]), ...taskEvents, ...shiftEvents];
  }, [events, tasks, shifts, currentUser]);

  // WEEK LOGIC
  const getStartOfWeek = (d: Date) => {
      const date = new Date(d);
      const day = date.getDay(); 
      const diff = date.getDate() - day + (day === 0 ? -6 : 1); // Adjust when day is Sunday
      return new Date(date.setDate(diff));
  };

  const currentWeekStart = useMemo(() => getStartOfWeek(viewDate), [viewDate]);

  const weekDays = useMemo(() => {
      const days = [];
      for (let i = 0; i < 7; i++) {
          const d = new Date(currentWeekStart);
          d.setDate(d.getDate() + i);
          days.push(d);
      }
      return days;
  }, [currentWeekStart]);

  const changeWeek = (direction: 'prev' | 'next') => {
      const newDate = new Date(viewDate);
      newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
      setViewDate(newDate);
  };

  const isToday = (d: Date) => {
      const today = new Date();
      return d.getDate() === today.getDate() && d.getMonth() === today.getMonth() && d.getFullYear() === today.getFullYear();
  };

  const getText = (text?: string) => {
    if (!text) return '';
    return text.startsWith('task.mock') ? t(text) : text;
  };

  // Handlers
  const handleSaveEvent = async (e: React.FormEvent) => {
      e.preventDefault();
      const isTransfer = newEventForm.type === 'Şube Transferi';
      if (!newEventForm.title && !isTransfer) return alert(t('cal.warnTitle'));

      setIsSaving(true);
      try {
          const finalTitle = isTransfer ? `${newEventForm.attendees?.length} Personel -> ${targetBranch}` : newEventForm.title!;
          const dbPayload = {
              title: finalTitle, type: newEventForm.type, date: newEventForm.date,
              end_date: newEventForm.endDate || newEventForm.date, start_time: newEventForm.startTime,
              end_time: newEventForm.endTime, attendees: newEventForm.attendees || [], description: newEventForm.description
          };
          const { data, error } = await supabase.from('calendar_events').insert([dbPayload]).select();
          if (error) throw error;

          if(isTransfer && currentUser.role === Role.ADMIN) {
               await supabase.from('profiles').update({ branch: targetBranch }).in('id', newEventForm.attendees || []);
          }

          if (data) {
              setEvents(prev => [...prev, { ...data[0], attendees: data[0].attendees || [] } as CalendarEvent]);
              setShowAddModal(false);
              alert(t('common.success'));
          }
      } catch (err: any) {
          alert("Error: " + err.message);
      } finally {
          setIsSaving(false);
      }
  };

  const handleDeleteEvent = async () => {
      if (!selectedEvent || selectedEvent.isTask || selectedEvent.isShift) return;
      if (confirm('Silmek istediğinize emin misiniz?')) {
          const { error } = await supabase.from('calendar_events').delete().eq('id', selectedEvent.id);
          if (!error) {
              setEvents(events.filter(e => e.id !== selectedEvent.id));
              setSelectedEvent(null);
