            </div>
        )}

        <header className="flex flex-col md:flex-row md:items-center justify-between gap-3 px-4 py-3 md:px-6 md:py-4 border-b border-zinc-800 bg-zinc-950/80 backdrop-blur-sm shrink-0">
            <h2 className="text-lg font-bold text-white tracking-tight">{t('pay.title')}</h2>
            <div className="flex w-full md:w-auto bg-zinc-900 p-1 rounded-xl border border-zinc-800">
                {currentUser.role === Role.ADMIN && (
                    <button 
                        onClick={() => setCurrentTab('STAFF')} 
                        className={`flex-1 md:flex-none text-center px-4 py-1.5 text-xs font-medium rounded-lg transition-all ${currentTab === 'STAFF' ? 'bg-zinc-800 text-white shadow' : 'text-zinc-500 hover:text-zinc-300'}`}
                    >
                        {t('pay.tabStaff')}
                    </button>
                )}
                <button 
                    onClick={() => setCurrentTab('MONTHLY')} 
                    className={`flex-1 md:flex-none text-center px-4 py-1.5 text-xs font-medium rounded-lg transition-all ${currentTab === 'MONTHLY' ? 'bg-zinc-800 text-white shadow' : 'text-zinc-500 hover:text-zinc-300'}`}
                >
                    {currentUser.role === Role.ADMIN ? 'Bordro' : t('pay.tabMonthly')}
                </button>
                {/* NEW: FINANCIAL SUMMARY TAB BUTTON */}
                {currentUser.role === Role.ADMIN && (
                    <button 
                        onClick={() => setCurrentTab('FINANCIAL')} 
                        className={`flex-1 md:flex-none text-center px-4 py-1.5 text-xs font-medium rounded-lg transition-all ${currentTab === 'FINANCIAL' ? 'bg-zinc-800 text-white shadow' : 'text-zinc-500 hover:text-zinc-300'}`}
                    >
                        {t('pay.tabFinancial')}
                    </button>
                )}
            </div>
        </header>

        <div className="flex-1 overflow-hidden flex flex-col md:flex-row relative">
            {/* SOL PANEL (LİSTE) - SADECE ADMIN GÖREBİLİR - GENİŞLİK AYARLANDI (240px) */}
             {currentUser.role === Role.ADMIN && (
                 <div className={`w-full md:w-[240px] border-r border-zinc-800 flex-col bg-zinc-950 h-full ${selectedEmployeeId ? 'hidden md:flex' : 'flex'}`}>
                  <div className="p-6 pb-4">
                     <div className="flex justify-between items-center mb-6">
                         <div><h3 className="text-xl font-bold text-white">{t('pay.tabStaff')}</h3><p className="text-xs text-zinc-500">{filteredEmployees.length} kişi</p></div>
                         {currentUser.role === Role.ADMIN && (<button onClick={handleAddNew} className="w-8 h-8 flex items-center justify-center bg-indigo-600 rounded-full text-white hover:bg-indigo-500 shadow-lg"><Plus size={18} /></button>)}
                     </div>
                     <div className="relative mb-4"><Search size={16} className="absolute left-3 top-3 text-zinc-500" /><input type="text" placeholder={t('pay.search')} className="w-full bg-zinc-900/50 border border-zinc-800 rounded-xl pl-10 pr-4 py-2.5 text-sm text-zinc-200 outline-none focus:border-indigo-500"/></div>

                     {/* BRANCH FILTRESI - SADECE ADMIN İÇİN GÖSTER */}
                     {currentUser.role === Role.ADMIN && (
                        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                            <button onClick={() => setSelectedBranch('ALL')} className={`px-3 py-1.5 rounded-lg text-xs ${selectedBranch === 'ALL' ? 'bg-zinc-100 text-zinc-900' : 'bg-zinc-900 text-zinc-400'}`}>All</button>
                            {Object.values(Branch).map(b => (<button key={b} onClick={() => setSelectedBranch(b)} className={`px-3 py-1.5 rounded-lg text-xs ${selectedBranch === b ? 'bg-zinc-100 text-zinc-900' : 'bg-zinc-900 text-zinc-400'}`}>{b}</button>))}
                        </div>
                     )}
                  </div>
                  <div className="flex-1 overflow-y-auto px-4 pb-4 space-y-2">
                    {isLoading && employees.length === 0 ? <div className="text-center p-4 text-zinc-500">{t('common.loading')}</div> : filteredEmployees.map(emp => (
                        <div key={emp.id} onClick={() => handleSelectEmployee(emp.id)} className={`group p-3 rounded-xl cursor-pointer transition-all border ${selectedEmployeeId === emp.id ? 'bg-zinc-900 border-indigo-500/30 shadow' : 'bg-transparent border-transparent hover:bg-zinc-900 hover:border-zinc-800'}`}>
                            <div className="flex items-center gap-4">
                                <div className="relative">
                                    <img src={emp.avatarUrl} className="w-12 h-12 rounded-full object-cover" />
                                    <div className={`absolute bottom-0 right-0 w-3 h-3 rounded-full border-2 border-zinc-950 ${emp.branch === Branch.DOM ? 'bg-blue-500' : 'bg-green-500'}`}></div>
                                </div>
                                <div className="flex-1 min-w-0">
                                    <h4 className={`text-sm font-semibold truncate ${selectedEmployeeId === emp.id ? 'text-white' : 'text-zinc-300'}`}>{emp.name}</h4>
                                    <div className="flex items-center gap-2 mt-0.5">
                                        <span className="text-[11px] text-zinc-500">{emp.role}</span>
                                        {/* ŞUBE BİLGİSİ VE TRANSFER VURGUSU */}
                                        <span className={`text-[11px] flex items-center gap-1 ${selectedBranch === emp.branch ? 'text-orange-400 font-bold' : 'text-zinc-500'}`}>
                                            {emp.branch}
                                            {selectedBranch === emp.branch && <ArrowRightLeft size={10} className="text-orange-500"/>}
                                        </span>
                                    </div>
                                </div>

                                {/* HIZLI TRANSFER BUTONU - LISTE İÇİNDE (TURUNCU GÜNCELLEMESİ) */}
                                {currentUser.role === Role.ADMIN && (
                                    <button 
                                        onClick={(e) => {
                                            e.stopPropagation(); // Detaya girmeyi engelle
                                            setSelectedEmployeeId(emp.id); // Modal için seçimi güncelle
                                            setTargetBranch(emp.branch); // Modal varsayılan şubesini ayarla
                                            setShowTransferModal(true);
                                        }}
                                        className="hidden md:flex items-center justify-center w-8 h-8 rounded-lg bg-zinc-800 text-zinc-400 hover:text-white hover:bg-orange-600 transition-all opacity-0 group-hover:opacity-100 focus:opacity-100 z-20 shadow-lg transform active:scale-95 border border-transparent hover:border-orange-400"
                                        title={t('cal.transfer')}
                                    >
                                        <ArrowRightLeft size={16} />
                                    </button>
                                )}

                                <div className="md:hidden text-zinc-600"><ChevronRight size={18} /></div>
                            </div>
                        </div>
                    ))}
                  </div>
                </div>
            )}

            {/* SAĞ PANEL (İÇERİK) - EĞER PERSONEL İSE TAM EKRAN */}
            <div className={`flex-1 w-full overflow-hidden ${selectedEmployeeId ? 'flex' : 'hidden md:flex'}`}>
                 {currentTab === 'STAFF' ? renderStaffContent() : currentTab === 'FINANCIAL' ? renderFinancialContent() : renderMonthlyContent()}
            </div>
        </div>
    </div>
  );
};

export default Payroll;

import React, { useState, useEffect, useRef } from 'react';
import { Message, Employee, Role } from '../types';
import { Search, Send, Mail, ChevronLeft, MessageSquare, Plus, X, Loader2, Check, CheckCheck, ShieldAlert } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useLanguage } from '../lib/i18n';

interface MessagesProps {
    currentUser: Employee;
}

const ADMIN_BOARD_ID = 'ADMIN_BOARD';

const Messages: React.FC<MessagesProps> = ({ currentUser }) => {
    // Mesaj Listesi (Sol Panel)
    const [messages, setMessages] = useState<Message[]>([]);

    // Aktif Sohbet
    const [activeChatPartnerId, setActiveChatPartnerId] = useState<string | null>(null);
    const [conversation, setConversation] = useState<Message[]>([]);

    const [isLoading, setIsLoading] = useState(true);
    const [loadingConversation, setLoadingConversation] = useState(false);
    const [replyText, setReplyText] = useState('');
    const [isSending, setIsSending] = useState(false);

    const scrollRef = useRef<HTMLDivElement>(null);

    const { t } = useLanguage();

    // Gerçek kullanıcı listesi
    const [recipientList, setRecipientList] = useState<Employee[]>([]);

    // Compose Modal
    const [showCompose, setShowCompose] = useState(false);
    const [composeForm, setComposeForm] = useState({
        receiverId: '',
        subject: '',
        content: ''
    });

    // Helper: ID'den İsim Bulma
    const getName = (id: string) => {
        if (id === currentUser.id) return 'Ben';
        if (id === 'ALL') return '📢 Tüm Personel';
        if (id === ADMIN_BOARD_ID) return '🏢 Yönetim Ekibi';
        const user = recipientList.find(e => e.id === id);
        return user ? user.name : 'Bilinmeyen Kullanıcı';
    };

    // Helper: ID'den Profil Resmi Bulma
    const getAvatar = (id: string) => {
        if (id === ADMIN_BOARD_ID) return null; // Özel ikon kullanılacak
        const user = recipientList.find(e => e.id === id);
        return user ? user.avatarUrl : null;
    };

    // Helper: Admin mi kontrolü
    const isAdmin = (id: string) => {
        const user = recipientList.find(e => e.id === id);
        return user?.role === Role.ADMIN;
    };

    // 1. Başlangıç Verilerini Çek
    useEffect(() => {
        fetchPotentialRecipients().then(() => {
            // Recipient list yüklendikten sonra mesajları çek ki Admin check yapabilelim
            fetchMessages(); 
        });
    }, [currentUser]);

    // 2. Realtime Aboneliği
    useEffect(() => {
        const channel = supabase.channel('messages-core')
            .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages' }, (payload) => {
                const newMsg = payload.new;

                // Realtime filtreleme:
                // 1. Bana geldi (receiver_id = me)
                // 2. Ben attım (sender_id = me)
                // 3. Herkese atıldı (ALL)
                // 4. ADMIN ise ve mesaj ADMIN_BOARD'a atıldıysa

                let isRelevant = false;

                if (newMsg.receiver_id === currentUser.id || newMsg.sender_id === currentUser.id || newMsg.receiver_id === 'ALL') {
                    isRelevant = true;
                } else if (currentUser.role === Role.ADMIN && newMsg.receiver_id === ADMIN_BOARD_ID) {
                    isRelevant = true;
                }

                if (isRelevant) {
                     fetchMessages();

                     // Aktif sohbet güncelleme mantığı
                     if (activeChatPartnerId) {
                         // Eğer Personel isem ve 'ADMIN_BOARD' açıksa:
                         // Gelen mesaj Admin'den bana ise VEYA ben Admin'e attıysam
                         if (currentUser.role !== Role.ADMIN && activeChatPartnerId === ADMIN_BOARD_ID) {
                             if (newMsg.receiver_id === currentUser.id || newMsg.receiver_id === ADMIN_BOARD_ID) {
                                 fetchConversation(ADMIN_BOARD_ID);
                             }
                         }
                         // Eğer Admin isem:
                         else {
                             // Mesajı atan şu an konuştuğum kişiyse (veya ben ona attıysam)
                             const senderIsActive = newMsg.sender_id === activeChatPartnerId;
                             const receiverIsActive = newMsg.receiver_id === activeChatPartnerId;

                             // Admin olarak ben Staff'a cevap yazdıysam
                             const iRepliedToActive = newMsg.sender_id === currentUser.id && newMsg.receiver_id === activeChatPartnerId;

                             // Staff, ADMIN_BOARD'a yazdıysa ve ben o Staff ile konuşuyorsam
                             const staffWroteToBoard = newMsg.sender_id === activeChatPartnerId && newMsg.receiver_id === ADMIN_BOARD_ID;

                             if (senderIsActive || receiverIsActive || iRepliedToActive || staffWroteToBoard) {
                                fetchConversation(activeChatPartnerId);
                             }
                         }
                     }
                }
            })
            .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'messages' }, () => {
                fetchMessages(); 
                if(activeChatPartnerId) fetchConversation(activeChatPartnerId);
            })
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [currentUser, activeChatPartnerId]);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [conversation]);

    useEffect(() => {
        if (activeChatPartnerId) {
            fetchConversation(activeChatPartnerId);
        } else {
            setConversation([]);
        }
    }, [activeChatPartnerId]);

    const fetchPotentialRecipients = async () => {
        const { data } = await supabase.from('profiles').select('*');
        if (data) {
            const formattedEmps: Employee[] = data.map((e: any) => ({
                id: e.id,
                name: e.full_name,
                email: e.email,
                role: e.role as Role,
                branch: e.branch,
                hourlyRate: e.hourly_rate,
                taxClass: e.tax_class,
                avatarUrl: e.avatar_url || `https://ui-avatars.com/api/?name=${e.full_name}`,
                advances: 0,
                phone: e.phone,
                bio: e.bio,
                badges: [],
                tags: [],
                metrics: e.metrics
            }));
            setRecipientList(formattedEmps);
        }
    };

    const fetchMessages = async () => {
        try {
            let query = supabase.from('messages').select('*').order('timestamp', { ascending: false });

            // SORGULAMA MANTIĞI:
            if (currentUser.role === Role.ADMIN) {
                // Admin: Kendisine gelen, Kendisinin attığı, ALL, ve ADMIN_BOARD'a gelenler
                query = query.or(`receiver_id.eq.${currentUser.id},sender_id.eq.${currentUser.id},receiver_id.eq.ALL,receiver_id.eq.${ADMIN_BOARD_ID}`);
            } else {
                // Personel: Kendisine gelen, Kendisinin attığı, ALL
                // (Personel ADMIN_BOARD'a attığında sender_id kendisi olduğu için zaten gelir)
                query = query.or(`receiver_id.eq.${currentUser.id},sender_id.eq.${currentUser.id},receiver_id.eq.ALL`);
            }

            const { data, error } = await query;
            if (error) throw error;

            const formattedMessages: Message[] = (data || []).map((m: any) => ({
                id: m.id,
                senderId: m.sender_id,
                receiverId: m.receiver_id,
                subject: m.subject,
                content: m.content,
                timestamp: m.timestamp,
                read: m.read
            }));

            // --- GRUPLAMA MANTIĞI ---
            const uniqueChats: Message[] = [];
            const seenPartners = new Set();

            formattedMessages.forEach(msg => {
                let partnerId = '';

                if (currentUser.role === Role.ADMIN) {
                    // ADMIN GÖZÜNDEN:
                    if (msg.receiverId === 'ALL') {
                        partnerId = 'ALL';
                    } else if (msg.receiverId === ADMIN_BOARD_ID) {
                        // Eğer mesaj Yönetim Havuzuna geldiyse, partner gönderen personeldir.
                        partnerId = msg.senderId;
                    } else if (msg.senderId === currentUser.id) {
                        // Ben birine attım, partner alıcıdır.
                        partnerId = msg.receiverId;
                    } else {
                        // Biri bana attı (Özel mesaj varsa)
                        partnerId = msg.senderId;
                    }
                } else {
                    // PERSONEL GÖZÜNDEN:
                    if (msg.receiverId === 'ALL') {
                        partnerId = 'ALL';
                    } else {
                        // Diğer tüm durumlar (Benim yönetime attığım veya Yönetimin bana attığı)
                        // Tek bir çatı altında toplanmalı: 'ADMIN_BOARD'
                        partnerId = ADMIN_BOARD_ID;
                    }
                }

                // Kendi kendime mesajlaşmayı engelle (Nadir durum)
                if (partnerId === currentUser.id) return;

                if (partnerId && !seenPartners.has(partnerId)) {
                    seenPartners.add(partnerId);
                    uniqueChats.push(msg);
                }
            });

            setMessages(uniqueChats);
            setIsLoading(false);
        } catch (error) {
            console.error("Mesajlar alınamadı:", error);
            setIsLoading(false);
        }
    };

    const fetchConversation = async (partnerId: string) => {
        if(conversation.length === 0) setLoadingConversation(true);

        try {
            let query = supabase.from('messages').select('*').order('timestamp', { ascending: true });

            if (partnerId === 'ALL') {
                query = query.eq('receiver_id', 'ALL');
            } else if (currentUser.role === Role.ADMIN) {
                // ADMIN OLARAK SOHBET GEÇMİŞİ:
                // 1. Partnerin ADMIN_BOARD'a attıkları
                // 2. Partnerin BANA attıkları
                // 3. BENİM Partnere attıklarım
                // 4. BAŞKA ADMİNLERİN Partnere attıkları (Tüm adminler görsün kuralı) -> receiver_id = partnerId
                query = query.or(`and(sender_id.eq.${partnerId},receiver_id.eq.${ADMIN_BOARD_ID}),and(sender_id.eq.${partnerId},receiver_id.eq.${currentUser.id}),receiver_id.eq.${partnerId}`);
            } else {
                // PERSONEL OLARAK SOHBET GEÇMİŞİ (partnerId = ADMIN_BOARD):
                // 1. BENİM ADMIN_BOARD'a attıklarım
                // 2. HERHANGİ BİR ADMININ BANA attıkları (receiver_id = ME)
                if (partnerId === ADMIN_BOARD_ID) {
                     query = query.or(`and(sender_id.eq.${currentUser.id},receiver_id.eq.${ADMIN_BOARD_ID}),receiver_id.eq.${currentUser.id}`);
                }
            }

            const { data, error } = await query;
            if (error) throw error;

            const formattedConv: Message[] = (data || []).map((m: any) => ({
                id: m.id,
                senderId: m.sender_id,
                receiverId: m.receiver_id,
                subject: m.subject,
                content: m.content,
                timestamp: m.timestamp,
                read: m.read
            }));

            // Sadece ADMIN_BOARD dışı mesajları filtrele (Personel için ALL karışmasın)
            const cleanConv = partnerId === 'ALL' 
                ? formattedConv 
                : formattedConv.filter(m => m.receiverId !== 'ALL');

            setConversation(cleanConv);

            // Okundu İşaretleme
            if (partnerId !== 'ALL') {
                const unreadMsgIds = cleanConv
                    .filter(m => !m.read && m.senderId !== currentUser.id) // Başkası attıysa ve okunmadıysa
                    .map(m => m.id);

                if (unreadMsgIds.length > 0) {
                    await supabase.from('messages').update({ read: true }).in('id', unreadMsgIds);
                    fetchMessages(); 
                }
            }

        } catch (err) {
            console.error("Sohbet geçmişi hatası:", err);
        } finally {
            setLoadingConversation(false);
        }
    };

    const handleSelectChat = (msg: Message) => {
        let partnerId = '';
        if (currentUser.role === Role.ADMIN) {
            if (msg.receiverId === 'ALL') partnerId = 'ALL';
            else if (msg.receiverId === ADMIN_BOARD_ID) partnerId = msg.senderId;
            else if (msg.senderId === currentUser.id) partnerId = msg.receiverId;
            else partnerId = msg.senderId;
        } else {
            if (msg.receiverId === 'ALL') partnerId = 'ALL';
            else partnerId = ADMIN_BOARD_ID;
        }
        setActiveChatPartnerId(partnerId);
    };

    const handleSendReply = async () => {
        if (!replyText.trim() || !activeChatPartnerId) return;
        setIsSending(true);

        try {
            let receiver = activeChatPartnerId;

            // Eğer personel isem ve "Yönetim Ekibi" seçiliyse, mesaj ADMIN_BOARD'a gider.
            if (currentUser.role !== Role.ADMIN && activeChatPartnerId === ADMIN_BOARD_ID) {
                receiver = ADMIN_BOARD_ID;
            }

            const newMessage = {
                sender_id: currentUser.id,
                receiver_id: receiver,
                subject: 'Sohbet Mesajı',
                content: replyText,
                read: false
            };

            const { error } = await supabase.from('messages').insert([newMessage]);
            if (error) throw error;

            setReplyText('');

        } catch (err: any) {
            alert("Gönderilemedi: " + err.message);
        } finally {
            setIsSending(false);
        }
    };

    const handleComposeSend = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!composeForm.receiverId || !composeForm.content) {
            alert("Alıcı ve mesaj içeriği zorunludur.");
            return;
        }

        setIsSending(true);
        try {
            const newMessage = {
                sender_id: currentUser.id,
                receiver_id: composeForm.receiverId,
                subject: composeForm.subject || 'Yeni Mesaj',
                content: composeForm.content,
                read: false
            };

            const { error } = await supabase.from('messages').insert([newMessage]);
            if (error) throw error;

            setShowCompose(false);
            setComposeForm({ receiverId: '', subject: '', content: '' });
            alert("Mesaj gönderildi.");

            // Sohbete geçiş yap
            let nextPartner = composeForm.receiverId;
            // Personel Yönetime attıysa, sohbet ID'si ADMIN_BOARD_ID olur
            if (currentUser.role !== Role.ADMIN && composeForm.receiverId === ADMIN_BOARD_ID) {
                nextPartner = ADMIN_BOARD_ID;
            }
            setActiveChatPartnerId(nextPartner);

        } catch (err: any) {
            alert("Hata: " + err.message);
        } finally {
            setIsSending(false);
        }
    };

    const handleOpenCompose = () => {
        // Varsayılan alıcı: Admin değilse Yönetim, Adminse boş
        const defaultReceiver = currentUser.role !== Role.ADMIN ? ADMIN_BOARD_ID : '';
        setComposeForm({ receiverId: defaultReceiver, subject: '', content: '' });
        setShowCompose(true);
    };

    // UI Helpers: Compose Dropdown Listesi
    const filteredRecipients = recipientList.filter(user => {
        if (user.id === currentUser.id) return false;
        // Personel sadece Yönetim'e atabilir (Dropdown'da özel seçenek olacak)
        // Admin herkese atabilir.
        return currentUser.role === Role.ADMIN;
    });

    return (
        <div className="flex h-full flex-col md:flex-row relative overflow-hidden bg-zinc-950">

            {/* COMPOSE MODAL */}
            {showCompose && (
                <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
                    <div className="bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in fade-in zoom-in-95">
                        <div className="p-5 border-b border-zinc-800 flex justify-between items-center bg-zinc-950/50">
                            <h3 className="text-lg font-bold text-white flex items-center gap-2">
                                <Mail size={20} className="text-indigo-500" /> {t('msg.compose')}
                            </h3>
                            <button onClick={() => setShowCompose(false)} className="text-zinc-500 hover:text-white"><X size={20} /></button>
                        </div>
                        <form onSubmit={handleComposeSend} className="p-6 space-y-4">
                            <div className="space-y-2">
