-- 4. REALTIME (GÜVENLİ VE KAPSAMLI EKLEME)
-- =========================================================
-- Bu blok, uygulamanın canlı çalışması gereken tüm tablolarını yayına açar.
DO $$
DECLARE
    -- Realtime'a eklenecek tabloların listesi
    tables text[] := ARRAY['profiles', 'time_logs', 'tasks', 'messages', 'calendar_events', 'shift_schedules'];
    tbl text;
BEGIN
    FOR tbl IN SELECT unnest(tables) LOOP
        -- Tablo zaten yayında mı kontrol et
        IF NOT EXISTS (
            SELECT 1
            FROM pg_publication_tables
            WHERE pubname = 'supabase_realtime'
            AND schemaname = 'public'
            AND tablename = tbl
        ) THEN
            -- Değilse ekle
            EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', tbl);
        END IF;
    END LOOP;
END $$;

